package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

/**
 * An immutable snapshot of the logged-in character's live state. The client thread builds a new
 * snapshot from the current one via {@link #toBuilder()} and publishes it with a single atomic
 * reference swap, so the sync thread always reads one internally-consistent set of fields - never a
 * torn mix such as a fresh inventory alongside a stale gp (gp is inventory coins + bank coins).
 *
 * <p>It holds only what the {@code /state} sync sends, and the server stores every field of it.
 */
final class AccountSnapshot
{
	final String rsn;
	final String accountHash;
	final boolean members;     // logged into a members world
	final long gp;
	final int freeSlots;
	final JsonArray offers;
	final JsonArray inventory;
	// null until the bank is captured (Include-bank on + bank opened this session), so a sync never
	// uploads an empty bank that would overwrite a previously-synced one.
	final JsonArray bank;
	// null until captured: what the character is wearing, which is owned gear too (best-in-slot
	// "from my bank" counts it), sent with the same keep-the-last-one rule as the bank.
	final JsonArray equipment;
	// null until captured; {skill: {level, xp}}. Feeds the site's level-aware calculators, and the
	// exact XP is how the server proves this account plays the in-game name it syncs under.
	final JsonObject skills;

	private AccountSnapshot(Builder b)
	{
		rsn = b.rsn;
		accountHash = b.accountHash;
		members = b.members;
		gp = b.gp;
		freeSlots = b.freeSlots;
		offers = b.offers;
		inventory = b.inventory;
		bank = b.bank;
		equipment = b.equipment;
		skills = b.skills;
	}

	static AccountSnapshot empty()
	{
		return new Builder().build();
	}

	boolean hasIdentity()
	{
		return rsn != null && !rsn.isEmpty();
	}

	Builder toBuilder()
	{
		return new Builder(this);
	}

	static final class Builder
	{
		private String rsn;
		private String accountHash;
		private boolean members;
		private long gp;
		private int freeSlots;
		private JsonArray offers = new JsonArray();
		private JsonArray inventory = new JsonArray();
		private JsonArray bank;
		private JsonArray equipment;
		private JsonObject skills;

		private Builder()
		{
		}

		private Builder(AccountSnapshot s)
		{
			rsn = s.rsn;
			accountHash = s.accountHash;
			members = s.members;
			gp = s.gp;
			freeSlots = s.freeSlots;
			offers = s.offers;
			inventory = s.inventory;
			bank = s.bank;
			equipment = s.equipment;
			skills = s.skills;
		}

		Builder rsn(String v)
		{
			rsn = v;
			return this;
		}

		Builder accountHash(String v)
		{
			accountHash = v;
			return this;
		}

		Builder members(boolean v)
		{
			members = v;
			return this;
		}

		Builder gp(long v)
		{
			gp = v;
			return this;
		}

		Builder freeSlots(int v)
		{
			freeSlots = v;
			return this;
		}

		Builder offers(JsonArray v)
		{
			offers = v;
			return this;
		}

		Builder inventory(JsonArray v)
		{
			inventory = v;
			return this;
		}

		Builder bank(JsonArray v)
		{
			bank = v;
			return this;
		}

		Builder equipment(JsonArray v)
		{
			equipment = v;
			return this;
		}

		Builder skills(JsonObject v)
		{
			skills = v;
			return this;
		}

		AccountSnapshot build()
		{
			return new AccountSnapshot(this);
		}
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Spots achievements as they happen, for the player's Adventurer's Log on RuneTools: level-ups,
 * quests, diaries, combat tasks, pets, valuable drops, boss kill-count milestones and personal
 * bests, and clue milestones and rewards.
 *
 * <p>Almost everything comes from the messages the game itself prints, matched on the exact texts
 * RuneLite's own Screenshot and Chat Commands plugins match (the plugin removes colour tags first).
 * Levels, quests and clue rewards are read by the plugin and handed in already parsed. Some facts
 * arrive in pieces across a tick or two (a kill count and its personal best, a pet and its name), so
 * those wait a few ticks before they are complete; {@link #onTick} finishes them.
 *
 * <p>Pure (no RuneLite types) so it can be unit tested. The plugin feeds it on the client thread and
 * takes finished events with {@link #drain()}; it is not thread-safe. Each event is the JSON the
 * {@code /api/plugin/achievements} endpoint takes: a {@code type}, a capture time {@code ts} (epoch
 * ms), a random {@code id} so a resend is recognised, and the type's own fields. Keep the README's
 * "What it sends" table in step with what is built here.
 */
final class AdventureLog
{
	/** The categories, each switched on or off by its own setting. */
	enum Category
	{
		LEVELS, QUESTS, COMBAT, PETS, DROPS, CLUES
	}

	/** One stack of loot from a chest or raid, priced by the plugin: {@code value} is the whole stack's. */
	static final class LootStack
	{
		final String name;
		final int qty;
		final long value;

		LootStack(String name, int qty, long value)
		{
			this.name = name;
			this.qty = qty;
			this.value = value;
		}
	}

	/** What the player has switched on, read fresh for every event. */
	interface Settings
	{
		boolean on(Category category);

		/** The smallest drop or clue reward value (gp) worth logging. */
		long minValue();
	}

	/** Kill counts worth an entry: the first kill, then the milestones (a superset of the hiscores' own). */
	static final Set<Integer> KILL_MILESTONES = new HashSet<>(Arrays.asList(
		1, 10, 50, 100, 250, 500, 1000, 2000, 3000, 5000, 10000, 25000, 50000, 100000));
	/** Clue completions (per tier) worth an entry. */
	static final Set<Integer> CLUE_MILESTONES = new HashSet<>(Arrays.asList(
		1, 10, 25, 50, 100, 250, 500, 1000, 2000, 5000, 10000));
	static final List<String> CLUE_TIERS = Arrays.asList("beginner", "easy", "medium", "hard", "elite", "master");
	static final List<String> CA_TIERS = Arrays.asList("easy", "medium", "hard", "elite", "master", "grandmaster");
	static final List<String> DIARY_TIERS = Arrays.asList("easy", "medium", "hard", "elite");

	// How long the pieces of one fact are allowed to arrive apart.
	private static final int PET_WAIT_TICKS = 10;          // the pet's name follows its message
	private static final int TIME_WAIT_TICKS = 10;         // a fight duration waits for its kill count
	private static final int UNTRADEABLE_WAIT_TICKS = 2;   // and an untradeable drop for a log entry
	private static final int CLUE_TIER_TICKS = 3;          // the clue message comes just before its reward
	private static final int MAX_READY = 200;              // a runaway can't grow the queue without bound
	private static final int MAX_PET_NAMES = 5;
	private static final int MAX_REWARD_ITEMS = 8;

	// "Congratulations, you've completed a hard combat task: Whack-a-Mole (3 points)."
	private static final Pattern CA_TASK = Pattern.compile(
		"^Congratulations, you've completed an? (\\w+) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$",
		Pattern.CASE_INSENSITIVE);
	// "Congratulations! You have completed all of the hard tasks in the Varrock area. Speak to ..."
	private static final Pattern DIARY = Pattern.compile(
		"Congratulations! You have completed all of the (\\w+) tasks in the (.+?) area", Pattern.CASE_INSENSITIVE);
	// The pet messages: a new pet following you ("You have a funny feeling like you're being
	// followed."), one sneaking into your backpack (follower already out), and a duplicate you would
	// have got ("...like you would have been followed..."). Matched on their common start.
	private static final Pattern PET = Pattern.compile(
		"^You (?:have a funny feeling like you|feel something weird sneaking into your backpack)",
		Pattern.CASE_INSENSITIVE);
	// The clan broadcast, which may carry the clan's name first and ends with when the pet came:
	// "[Clan] <player> has a funny feeling like he would have been followed: Pet snakeling at 50 killcount.",
	// "<player> feels something weird sneaking into her backpack: Heron at 12,345,678 XP.",
	// "<player> feels like she's acquired something special: Tumeken's guardian".
	private static final Pattern CLAN_PET = Pattern.compile(
		"^(?:\\[[^\\]]*\\] )?(.+?) (?:has a funny feeling like .+? followed|feels something weird sneaking into .+? backpack"
			+ "|feels like .+? acquired something special): (.+?)(?: at (.+?))?\\.?$");
	private static final Pattern CLOG_ITEM = Pattern.compile("New item added to your collection log: (.+?)\\.?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern UNTRADEABLE = Pattern.compile("^Untradeable drop: (.+?)\\.?$");
	// "Valuable drop: 3 x Dragon bones (8,151 coins)"
	private static final Pattern VALUABLE = Pattern.compile(
		"^Valuable drop: (?:([\\d,]+) x )?(.+?) \\(([\\d,]+) coins\\)");
	// Kill counts. "Your Zulrah kill count is: 100.", "Your Barrows chest count is: 50.",
	// "Your Corrupted Gauntlet completion count is: 10.", "Your herbiboar harvest count is: 25."
	private static final Pattern KC_PRIMARY = Pattern.compile(
		"Your (.+?) (kill|chest|completion|success|harvest) count is: ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	// "Your completed Chambers of Xeric count is: 50.", "Your subdued Wintertodt count is: 500."
	private static final Pattern KC_SECONDARY = Pattern.compile(
		"Your (?:completed|subdued) (.+?) count is: ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	// "Your completion count for Tombs of Amascut: Expert Mode is: 5."
	private static final Pattern KC_TERTIARY = Pattern.compile(
		"Your completion count for (.+?) is: ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	// "Fight duration: 1:23.40 (new personal best).", "Subdued in 3:12 (new personal best).",
	// "... Theatre of Blood completion time: 20:00 (new personal best)". Lap times are agility.
	private static final Pattern PB = Pattern.compile(
		"(?:(?:Fight |Challenge |Corrupted challenge )?(?<!Lap )duration:|Subdued in|(?<!total )completion time:) "
			+ "([0-9:]+(?:\\.[0-9]+)?)\\.? \\(new personal best\\)", Pattern.CASE_INSENSITIVE);
	// "Congratulations - your raid is complete! Team size: 3 players Duration: 23:45 (new personal best)"
	private static final Pattern RAID_PB = Pattern.compile(
		"Team size: (Solo|\\d+(?:\\+|-\\d+)? players?) Duration: ([0-9:]+(?:\\.[0-9]+)?)\\.? \\(new personal best\\)",
		Pattern.CASE_INSENSITIVE);
	// "You have completed 100 hard Treasure Trails."
	private static final Pattern CLUE = Pattern.compile(
		"You have completed ([\\d,]+) (\\w+) Treasure Trails?\\.", Pattern.CASE_INSENSITIVE);

	private final Settings settings;
	private final List<JsonObject> ready = new ArrayList<>();

	// pieces still waiting for the rest of their fact
	private PendingPet pet;
	private PendingKill kill;
	private PendingTime time;
	private final List<PendingDrop> untradeables = new ArrayList<>();
	private final Set<String> loggedThisTick = new HashSet<>();   // collection-log names, lower case
	private int loggedTick = -1;
	private String clueTier;
	private int clueTierTick = -1;
	private int tick;

	private static final class PendingPet
	{
		final int tick;
		final boolean duplicate;
		final boolean backpack;
		final long at;
		final Set<String> names = new LinkedHashSet<>();
		String milestone;   // "50 killcount", from the clan broadcast when there is one

		PendingPet(int tick, boolean duplicate, boolean backpack, long at)
		{
			this.tick = tick;
			this.duplicate = duplicate;
			this.backpack = backpack;
			this.at = at;
		}
	}

	private static final class PendingKill
	{
		final int tick;
		final String boss;
		final int count;
		final long at;

		PendingKill(int tick, String boss, int count, long at)
		{
			this.tick = tick;
			this.boss = boss;
			this.count = count;
			this.at = at;
		}
	}

	private static final class PendingTime
	{
		final int tick;
		final String time;
		final String team;

		PendingTime(int tick, String time, String team)
		{
			this.tick = tick;
			this.time = time;
			this.team = team;
		}
	}

	private static final class PendingDrop
	{
		final int tick;
		final String name;
		final long at;

		PendingDrop(int tick, String name, long at)
		{
			this.tick = tick;
			this.name = name;
			this.at = at;
		}
	}

	AdventureLog(Settings settings)
	{
		this.settings = settings;
	}

	/** Take every finished event, oldest first. */
	List<JsonObject> drain()
	{
		List<JsonObject> out = new ArrayList<>(ready);
		ready.clear();
		return out;
	}

	boolean hasReady()
	{
		return !ready.isEmpty();
	}

	/** Forget anything half-seen (a logout, a world hop, a character switch). Finished events stay. */
	void reset()
	{
		pet = null;
		kill = null;
		time = null;
		untradeables.clear();
		loggedThisTick.clear();
		clueTier = null;
	}

	// -- inputs ------------------------------------------------------------------------------------ //

	/**
	 * A message from the game itself (a game message, a message box or a friends-chat notification),
	 * colour tags already removed. {@code now} is epoch ms.
	 */
	void onGameMessage(String text, long now)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		Matcher m;
		if ((m = CA_TASK.matcher(text)).find())
		{
			String tier = m.group(1).toLowerCase(Locale.ROOT);
			if (CA_TIERS.contains(tier) && on(Category.COMBAT))
			{
				JsonObject e = event("ca_task", now);
				e.addProperty("tier", tier);
				e.addProperty("task", clean(m.group(2)));
				add(e);
			}
			return;
		}
		if ((m = DIARY.matcher(text)).find())
		{
			String tier = m.group(1).toLowerCase(Locale.ROOT);
			if (DIARY_TIERS.contains(tier) && on(Category.QUESTS))
			{
				JsonObject e = event("diary", now);
				e.addProperty("tier", tier);
				e.addProperty("area", clean(m.group(2)));
				add(e);
			}
			return;
		}
		if ((m = PET.matcher(text)).find())
		{
			if (on(Category.PETS))
			{
				flushPet();   // two pets in a row: the first keeps whatever name it found
				String lower = text.toLowerCase(Locale.ROOT);
				pet = new PendingPet(tick, lower.contains("would have been"), lower.contains("backpack"), now);
			}
			return;
		}
		if ((m = CLOG_ITEM.matcher(text)).find())
		{
			String name = clean(m.group(1));
			if (loggedTick != tick)
			{
				loggedThisTick.clear();
				loggedTick = tick;
			}
			loggedThisTick.add(name.toLowerCase(Locale.ROOT));
			if (pet != null)
			{
				addPetName(name);
			}
			// The log entry is the better record of this item, so its untradeable drop isn't kept.
			untradeables.removeIf(d -> d.name.equalsIgnoreCase(name));
			return;
		}
		if ((m = UNTRADEABLE.matcher(text)).find())
		{
			String name = clean(m.group(1));
			if (pet != null)
			{
				addPetName(name);
			}
			if (on(Category.DROPS) && !name.isEmpty() && !(loggedTick == tick && loggedThisTick.contains(name.toLowerCase(Locale.ROOT))))
			{
				untradeables.add(new PendingDrop(tick, name, now));
			}
			return;
		}
		if ((m = VALUABLE.matcher(text)).find())
		{
			long value = number(m.group(3));
			if (on(Category.DROPS) && value >= settings.minValue() && value > 0)
			{
				JsonObject e = event("drop", now);
				e.addProperty("item", clean(m.group(2)));
				e.addProperty("qty", m.group(1) != null ? Math.max(1, number(m.group(1))) : 1);
				e.addProperty("value", value);
				add(e);
			}
			return;
		}
		if ((m = CLUE.matcher(text)).find())
		{
			String tier = m.group(2).toLowerCase(Locale.ROOT);
			if (!CLUE_TIERS.contains(tier))
			{
				return;
			}
			clueTier = tier;
			clueTierTick = tick;
			long count = number(m.group(1));
			if (on(Category.CLUES) && count <= Integer.MAX_VALUE && CLUE_MILESTONES.contains((int) count))
			{
				JsonObject e = event("clue_tier", now);
				e.addProperty("tier", tier);
				e.addProperty("count", count);
				add(e);
			}
			return;
		}
		// A Theatre of Blood room message gives the room's own time before the raid's ("Wave 'The
		// Final Challenge' (Normal Mode) complete! Duration: 7:42.60 Theatre of Blood completion time:
		// 21:33.60 (new personal best)"): only the raid's part can be the raid's best.
		String timed = text;
		if (text.startsWith("Wave '"))
		{
			int raid = text.indexOf("Theatre of Blood");
			timed = raid < 0 ? "" : text.substring(raid);
		}
		// A raid's completion message carries the team size, so it is checked before the general time.
		if ((m = RAID_PB.matcher(timed)).find())
		{
			time = new PendingTime(tick, m.group(2), m.group(1));
			return;
		}
		if ((m = PB.matcher(timed)).find())
		{
			time = new PendingTime(tick, m.group(1), null);
		}
		// Not "else": a Theatre of Blood wave message can carry a duration and, in some versions, the
		// count in one line.
		String boss = null;
		long count = -1;
		if ((m = KC_SECONDARY.matcher(text)).find() || (m = KC_TERTIARY.matcher(text)).find())
		{
			boss = clean(m.group(1));
			count = number(m.group(2));
		}
		else if ((m = KC_PRIMARY.matcher(text)).find())
		{
			boss = clean(m.group(1));
			String type = m.group(2).toLowerCase(Locale.ROOT);
			if ("chest".equals(type) && !boss.equalsIgnoreCase("barrows") && !boss.equalsIgnoreCase("lunar"))
			{
				boss = null;   // other "chest counts" are not fights
			}
			else if ("chest".equals(type) && boss.equalsIgnoreCase("lunar"))
			{
				boss = "Lunar Chest";
			}
			count = number(m.group(3));
		}
		if (boss != null && !boss.isEmpty() && count > 0 && count <= Integer.MAX_VALUE)
		{
			if (kill != null)
			{
				finishKill(true);   // kills two ticks apart: the first one is complete already
			}
			kill = new PendingKill(tick, boss, (int) count, now);
		}
	}

	/** A clan or group-chat broadcast: a pet's name, when it's this player's. */
	void onClanMessage(String text, String me)
	{
		if (pet == null || text == null || me == null)
		{
			return;
		}
		Matcher m = CLAN_PET.matcher(text);
		if (m.find() && m.group(1).trim().equalsIgnoreCase(me.trim()))
		{
			addPetName(clean(m.group(2)));
			if (m.group(3) != null && pet.milestone == null)
			{
				pet.milestone = clean(m.group(3));
			}
		}
	}

	/**
	 * Real (unboosted) levels went up in a skill. {@code total} is the total level once this change
	 * is counted; {@code maxed} that every skill is now 99. Virtual levels past 99 aren't passed in.
	 */
	void onLevelUp(String skill, int from, int to, int total, boolean maxed, long now)
	{
		if (!on(Category.LEVELS) || skill == null || to <= from || to > 99 || from < 1)
		{
			return;
		}
		JsonObject e = event("level", now);
		e.addProperty("skill", skill);
		e.addProperty("from", from);
		e.addProperty("level", to);
		e.addProperty("total", total);
		if (maxed)
		{
			e.addProperty("maxed", true);
		}
		add(e);
	}

	/** A quest's completion scroll appeared, already matched to the quest's name. */
	void onQuest(String quest, int completedCount, long now)
	{
		if (!on(Category.QUESTS) || quest == null || quest.isEmpty())
		{
			return;
		}
		JsonObject e = event("quest", now);
		e.addProperty("quest", quest);
		if (completedCount > 0)
		{
			e.addProperty("count", completedCount);
		}
		add(e);
	}

	/**
	 * A clue reward screen: {@code items} as {id, quantity} pairs, most valuable first, and the
	 * total value the plugin priced them at. Logged when it reaches the value setting.
	 */
	void onClueReward(List<int[]> items, long value, long now)
	{
		if (!on(Category.DROPS) || items == null || items.isEmpty() || value < settings.minValue() || value <= 0)
		{
			return;
		}
		JsonObject e = event("clue_reward", now);
		if (clueTier != null && tick - clueTierTick <= CLUE_TIER_TICKS)
		{
			e.addProperty("tier", clueTier);
		}
		e.addProperty("value", value);
		JsonArray arr = new JsonArray();
		for (int[] it : items)
		{
			if (arr.size() >= MAX_REWARD_ITEMS)
			{
				break;
			}
			if (it != null && it.length >= 2 && it[0] > 0 && it[1] > 0)
			{
				JsonObject o = new JsonObject();
				o.addProperty("id", it[0]);
				o.addProperty("qty", it[1]);
				arr.add(o);
			}
		}
		e.add("items", arr);
		add(e);
	}

	/**
	 * Loot from a chest or a raid (Barrows, the raids' reward chests, the Moons...), which the game
	 * doesn't announce the way it does an NPC's valuable drop. Each stack worth at least the value
	 * setting is logged as a drop, the most valuable first, up to {@link #MAX_REWARD_ITEMS}.
	 */
	void onChestLoot(List<LootStack> stacks, long now)
	{
		if (!on(Category.DROPS) || stacks == null)
		{
			return;
		}
		List<LootStack> worth = new ArrayList<>();
		for (LootStack s : stacks)
		{
			if (s != null && s.name != null && !s.name.trim().isEmpty() && s.qty > 0 && s.value > 0
				&& s.value >= settings.minValue())
			{
				worth.add(s);
			}
		}
		worth.sort((a, b) -> Long.compare(b.value, a.value));
		for (int i = 0; i < worth.size() && i < MAX_REWARD_ITEMS; i++)
		{
			LootStack s = worth.get(i);
			JsonObject e = event("drop", now);
			e.addProperty("item", clean(s.name));
			e.addProperty("qty", s.qty);
			e.addProperty("value", s.value);
			add(e);
		}
	}

	/**
	 * A game tick passed (after this tick's messages). Finishes the facts whose pieces have all had
	 * time to arrive.
	 */
	void onTick(int tick)
	{
		this.tick = tick;
		// A kill count waits one more tick for its fight duration (raids send them a tick apart).
		if (kill != null && tick - kill.tick >= 2)
		{
			finishKill(false);
		}
		if (time != null && tick - time.tick > TIME_WAIT_TICKS)
		{
			time = null;   // a duration whose fight never reported a count (agility, a minigame)
		}
		if (pet != null && (tick - pet.tick > PET_WAIT_TICKS || (!pet.names.isEmpty() && tick - pet.tick > 2)))
		{
			flushPet();
		}
		for (Iterator<PendingDrop> it = untradeables.iterator(); it.hasNext(); )
		{
			PendingDrop d = it.next();
			if (tick - d.tick >= UNTRADEABLE_WAIT_TICKS)
			{
				it.remove();
				JsonObject e = event("drop", d.at);
				e.addProperty("item", d.name);
				e.addProperty("qty", 1);
				e.addProperty("untradeable", true);
				add(e);
			}
		}
	}

	// -- finishing ------------------------------------------------------------------------------- //

	/**
	 * Finish the pending kill. {@code newKillArrived}: another kill count just came in, so a duration
	 * seen after this kill belongs to that one and is left for it.
	 */
	private void finishKill(boolean newKillArrived)
	{
		PendingKill k = kill;
		kill = null;
		if (!on(Category.COMBAT))
		{
			time = null;
			return;
		}
		PendingTime t = null;
		if (time != null && !(newKillArrived && time.tick > k.tick) && Math.abs(k.tick - time.tick) <= TIME_WAIT_TICKS)
		{
			t = time;
			time = null;
		}
		if (t != null)
		{
			JsonObject e = event("pb", k.at);
			e.addProperty("boss", k.boss);
			e.addProperty("time", t.time);
			e.addProperty("kc", k.count);
			if (t.team != null)
			{
				e.addProperty("team", t.team);
			}
			add(e);
		}
		if (KILL_MILESTONES.contains(k.count))
		{
			JsonObject e = event("boss_kc", k.at);
			e.addProperty("boss", k.boss);
			e.addProperty("kc", k.count);
			add(e);
		}
	}

	private void flushPet()
	{
		PendingPet p = pet;
		pet = null;
		if (p == null || !on(Category.PETS))
		{
			return;
		}
		JsonObject e = event("pet", p.at);
		if (p.milestone != null && !p.milestone.isEmpty())
		{
			e.addProperty("milestone", p.milestone);
		}
		if (p.duplicate)
		{
			e.addProperty("duplicate", true);
		}
		if (p.backpack)
		{
			e.addProperty("backpack", true);
		}
		// Every item the game named around the pet message; the site keeps the one that is a pet.
		JsonArray names = new JsonArray();
		for (String n : p.names)
		{
			names.add(n);
		}
		e.add("names", names);
		add(e);
	}

	private void addPetName(String name)
	{
		if (pet != null && !name.isEmpty() && pet.names.size() < MAX_PET_NAMES)
		{
			pet.names.add(name);
		}
	}

	// -- helpers ----------------------------------------------------------------------------------- //

	private boolean on(Category c)
	{
		return settings.on(c);
	}

	private JsonObject event(String type, long now)
	{
		JsonObject e = new JsonObject();
		e.addProperty("type", type);
		e.addProperty("ts", now);
		e.addProperty("id", UUID.randomUUID().toString().replace("-", "").substring(0, 16));
		return e;
	}

	private void add(JsonObject e)
	{
		if (ready.size() < MAX_READY)
		{
			ready.add(e);
		}
	}

	/** Trim and drop a trailing full stop; names are bounded so a garbled line can't grow a payload. */
	static String clean(String s)
	{
		if (s == null)
		{
			return "";
		}
		String t = s.replace(' ', ' ').trim();
		while (t.endsWith("."))
		{
			t = t.substring(0, t.length() - 1).trim();
		}
		return t.length() > 80 ? t.substring(0, 80) : t;
	}

	static long number(String s)
	{
		if (s == null)
		{
			return -1;
		}
		try
		{
			return Long.parseLong(s.replace(",", "").trim());
		}
		catch (NumberFormatException ex)
		{
			return -1;
		}
	}

	/**
	 * Recipe for Disaster's subquests end with scrolls that name who was helped rather than the
	 * subquest ("You have freed the Goblin Generals!", "You have assisted the Lumbridge Cook...
	 * again!"): what each title contains (squashed), and the subquest it is in RuneLite's list. The
	 * finale is "You have completed Recipe for Disaster!", matched like any other quest.
	 */
	private static final String[][] RFD_SUBQUESTS = {
		{"anothercooksquest", "Another Cook's Quest"},
		{"lumbridgecookagain", "Another Cook's Quest"},
		{"mountaindwarf", "Mountain Dwarf"},
		{"goblingenerals", "Wartface & Bentnoze"},
		{"wartface", "Wartface & Bentnoze"},
		{"piratepete", "Pirate Pete"},
		{"lumbridgeguide", "Lumbridge Guide"},
		{"evildave", "Evil Dave"},
		{"skrach", "Skrach Uglogwee"},
		{"siramikvarze", "Sir Amik Varze"},
		{"awowogei", "King Awowogei"},
		{"culinaromancer", "Culinaromancer"},
	};

	/**
	 * Which quest a completion scroll's title names ("You have completed The Corsair Curse!",
	 * "'One Small Favour' completed!"), from the game's own quest list: the longest quest name found
	 * in the title, ignoring case and punctuation. A partial completion ("kind of") is not one.
	 */
	static String matchQuest(String title, Collection<String> questNames)
	{
		if (title == null || questNames == null)
		{
			return null;
		}
		String t = title.toLowerCase(Locale.ROOT);
		if (t.contains("kind of"))
		{
			return null;
		}
		String key = squash(t);
		if (!key.contains("recipefordisaster"))
		{
			for (String[] sub : RFD_SUBQUESTS)
			{
				String name = "Recipe for Disaster - " + sub[1];
				if (key.contains(sub[0]) && questNames.contains(name))
				{
					return name;
				}
			}
		}
		String best = null;
		int bestLen = 0;
		for (String q : questNames)
		{
			String k = squash(q.toLowerCase(Locale.ROOT));
			// Titles often drop a leading "The" ("You have completed Corsair Curse!").
			String bare = k.startsWith("the") && k.length() > 6 ? k.substring(3) : k;
			int len = key.contains(k) ? k.length() : key.contains(bare) ? bare.length() : 0;
			if (len > bestLen && len >= 4)
			{
				best = q;
				bestLen = len;
			}
		}
		return best;
	}

	private static String squash(String s)
	{
		StringBuilder b = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if (Character.isLetterOrDigit(c))
			{
				b.append(c);
			}
		}
		return b.toString();
	}

	/** For tests: the categories in a stable order. */
	static List<Category> categories()
	{
		return Collections.unmodifiableList(Arrays.asList(Category.values()));
	}
}

package com.runetools;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Classifies the items currently in a player's bank into a handful of human categories, and - within
 * each category - into ordered <em>groups</em> that {@link BankOrganizer} lays out one-per-row so the
 * tab reads like a tidy, worn-kit-style arrangement rather than a value dump.
 *
 * <ul>
 *   <li><b>Gear</b> - grouped by combat style (Melee, Ranged, Magic), then a Jewelry group for
 *       combat jewelry, then Other; within a group items run in worn-slot order (helm -> cape ->
 *       body -> legs ...) so scanning top-to-bottom mirrors an equipment screen.</li>
 *   <li><b>Teleports</b> - teleport jewelry (glory, games necklace ...), then teleport tablets, then
 *       runes.</li>
 *   <li><b>Supplies</b> - potions, then food.</li>
 *   <li><b>Skilling</b> / <b>Misc</b> - single group, most-valuable-first.</li>
 * </ul>
 *
 * <p>It only reads cached item data ({@link ItemManager}) - it moves nothing - but callers should run
 * it on the client thread. Classification is deliberately heuristic; anything it can't place lands in
 * Misc rather than being hidden.
 */
class BankCategorizer
{
	/** Tabs are emitted in this order. Names double as the Bank Tags tag/tab labels. */
	enum Category
	{
		GEAR("Gear"),
		TELEPORTS("Teleports"),
		SUPPLIES("Supplies"),
		SKILLING("Skilling"),
		MISC("Misc");

		final String label;

		Category(String label)
		{
			this.label = label;
		}
	}

	/** A category's items, split into ordered groups (each laid out starting on a fresh row). */
	static class CategoryTab
	{
		final Category category;
		final int iconItemId;
		final List<List<Integer>> groups;

		CategoryTab(Category category, int iconItemId, List<List<Integer>> groups)
		{
			this.category = category;
			this.iconItemId = iconItemId;
			this.groups = groups;
		}
	}

	// Equipment slot indices (net.runelite.api.EquipmentInventorySlot#getSlotIdx).
	private static final int SLOT_AMULET = 2;
	private static final int SLOT_RING = 12;

	// Worn-silhouette order used to sort a gear group top-to-bottom. Index = equipment slot idx.
	private static final int[] SLOT_ORDER = new int[14];

	static
	{
		Arrays.fill(SLOT_ORDER, 90);
		SLOT_ORDER[0] = 0;    // head
		SLOT_ORDER[1] = 1;    // cape
		SLOT_ORDER[2] = 2;    // amulet
		SLOT_ORDER[4] = 3;    // body
		SLOT_ORDER[7] = 4;    // legs
		SLOT_ORDER[9] = 5;    // hands
		SLOT_ORDER[10] = 6;   // feet
		SLOT_ORDER[3] = 7;    // weapon
		SLOT_ORDER[5] = 8;    // shield
		SLOT_ORDER[12] = 9;   // ring
		SLOT_ORDER[13] = 10;  // ammo
	}

	private static final Pattern DOSE = Pattern.compile("\\([1-4]\\)$");

	// Teleport jewelry (equipable) - pulled into the Teleports tab; combat jewelry stays in Gear.
	private static final String[] TELEPORT_JEWELRY = {
		"amulet of glory", "eternal glory", "games necklace", "ring of dueling", "ring of duelling",
		"ring of wealth", "skills necklace", "digsite pendant", "necklace of passage", "burning amulet",
		"combat bracelet", "ring of returning", "ring of the elements", "slayer ring", "amulet of bounty",
		"xeric's talisman", "drakan's medallion", "pendant of ates"};

	// Non-equipable teleports that don't carry the word "teleport".
	private static final Set<String> TELEPORT_ITEMS = new HashSet<>(Arrays.asList(
		"ectophial", "royal seed pod", "teleport crystal", "enchanted lyre", "chronicle"));

	private static final Set<String> FOOD = new HashSet<>(Arrays.asList(
		"shark", "manta ray", "sea turtle", "anglerfish", "dark crab", "monkfish", "lobster",
		"tuna", "swordfish", "bass", "salmon", "trout", "cooked karambwan", "tuna potato",
		"pineapple pizza", "summer pie", "wild pie", "admiral pie", "curry", "stew",
		"cake", "chocolate cake", "jug of wine", "purple sweets", "peaches", "guthix rest tea"));

	private static final String[] SKILLING_KEYS = {
		"logs", " ore", " bar", "plank", "seed", "sapling", "grimy ", "clean ", "essence",
		"herb", "hide", "leather", "bones", "ashes", "uncut ", " gem", "feather", "arrowtip",
		"dart tip", "bolt tips", "javelin head", "spear head", "nails", "molten glass",
		"soda ash", "seaweed", "flax", "bow string", "bowstring", "ball of wool", "wool",
		"battlestaff", "compost", "bucket", "jug of water", "vial", "coal", "clay", "limestone",
		"tar", "raw ", "unfired", "(unf)", "amethyst", "pure essence", "rune essence",
		"dragon scale", "kebbit", "pyre", "mahogany", "teak", "willow", "maple", "yew",
		"redwood", "crushed", "potato cactus"};

	private final ItemManager itemManager;

	BankCategorizer(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/** Bucket bank item ids into ordered category tabs (non-empty only, in {@link Category} order). */
	List<CategoryTab> categorize(List<Integer> bankItemIds)
	{
		// category -> (groupIndex -> items). TreeMap keeps groups in their intended top-to-bottom order.
		TreeMap<Category, TreeMap<Integer, List<Integer>>> buckets = new TreeMap<>();

		Set<Integer> seen = new HashSet<>();
		for (Integer raw : bankItemIds)
		{
			if (raw == null || raw <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(raw);
			if (id <= 0 || !seen.add(id))
			{
				continue;
			}
			Placement p = classify(id);
			buckets.computeIfAbsent(p.category, k -> new TreeMap<>())
				.computeIfAbsent(p.group, k -> new ArrayList<>())
				.add(id);
		}

		List<CategoryTab> out = new ArrayList<>();
		for (Category cat : Category.values())
		{
			TreeMap<Integer, List<Integer>> groups = buckets.get(cat);
			if (groups == null || groups.isEmpty())
			{
				continue;
			}
			List<List<Integer>> rows = buildRows(cat, groups);
			int icon = -1;
			for (List<Integer> row : rows)
			{
				if (!row.isEmpty())
				{
					icon = row.get(0);
					break;
				}
			}
			out.add(new CategoryTab(cat, icon, rows));
		}
		return out;
	}

	/**
	 * Turn a category's groups into laid-out rows. Gear splits each style group into one row per
	 * equipment slot (helm row, cape row, body row ...) so it reads top-to-bottom like a worn kit;
	 * other categories use one wrapping row per group. A blank row separates consecutive groups.
	 */
	private List<List<Integer>> buildRows(Category cat, TreeMap<Integer, List<Integer>> groups)
	{
		List<List<Integer>> rows = new ArrayList<>();
		for (List<Integer> group : groups.values())
		{
			if (group.isEmpty())
			{
				continue;
			}
			if (!rows.isEmpty())
			{
				rows.add(new ArrayList<>());   // blank separator row between groups
			}
			if (cat == Category.GEAR)
			{
				TreeMap<Integer, List<Integer>> bySlot = new TreeMap<>();
				for (int id : group)
				{
					bySlot.computeIfAbsent(slotOrder(id), k -> new ArrayList<>()).add(id);
				}
				for (List<Integer> slotRow : bySlot.values())
				{
					slotRow.sort(Comparator.comparingLong((Integer id) -> price(id)).reversed()
						.thenComparing(this::name));
					rows.add(slotRow);         // one row per slot, best-first
				}
			}
			else
			{
				group.sort(Comparator.comparingLong((Integer id) -> price(id)).reversed()
					.thenComparing(this::name));
				rows.add(group);
			}
		}
		return rows;
	}

	// -- classification ------------------------------------------------------ //

	private static final class Placement
	{
		final Category category;
		final int group;

		Placement(Category category, int group)
		{
			this.category = category;
			this.group = group;
		}
	}

	// Gear group indices (worn kit reads Melee, Ranged, Magic, then jewelry, then everything else).
	private static final int G_MELEE = 0;
	private static final int G_RANGED = 1;
	private static final int G_MAGIC = 2;
	private static final int G_JEWELRY = 3;
	private static final int G_OTHER = 4;

	private Placement classify(int id)
	{
		ItemComposition comp = itemManager.getItemComposition(id);
		String name = comp != null && comp.getName() != null ? comp.getName().toLowerCase() : "";

		ItemStats stats = itemManager.getItemStats(id);
		ItemEquipmentStats eq = stats != null && stats.isEquipable() ? stats.getEquipment() : null;

		if (eq != null)
		{
			if (isTeleportJewelry(name))
			{
				return new Placement(Category.TELEPORTS, 0);   // teleport jewelry group
			}
			if (isJewelry(eq, name))
			{
				return new Placement(Category.GEAR, G_JEWELRY);
			}
			return new Placement(Category.GEAR, gearStyle(eq));
		}

		if (name.isEmpty())
		{
			return new Placement(Category.MISC, 0);
		}
		if (isTeleportTablet(name))
		{
			return new Placement(Category.TELEPORTS, 1);       // tablets group
		}
		if (isRune(name))
		{
			return new Placement(Category.TELEPORTS, 2);       // runes group
		}
		if (isPotion(name))
		{
			return new Placement(Category.SUPPLIES, 0);
		}
		if (isFood(name))
		{
			return new Placement(Category.SUPPLIES, 1);
		}
		if (isSkilling(name))
		{
			return new Placement(Category.SKILLING, 0);
		}
		return new Placement(Category.MISC, 0);
	}

	private static boolean isTeleportJewelry(String name)
	{
		for (String key : TELEPORT_JEWELRY)
		{
			if (name.contains(key))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isTeleportTablet(String name)
	{
		return name.contains("teleport") || TELEPORT_ITEMS.contains(name);
	}

	private static boolean isJewelry(ItemEquipmentStats eq, String name)
	{
		return eq.getSlot() == SLOT_AMULET || eq.getSlot() == SLOT_RING || name.contains("bracelet");
	}

	/** Classify a piece of gear as Melee/Ranged/Magic by its offensive+defensive bias, else Other. */
	private static int gearStyle(ItemEquipmentStats eq)
	{
		double melee = pos(eq.getAstab()) + pos(eq.getAslash()) + pos(eq.getAcrush())
			+ pos(eq.getStr()) * 2
			+ (pos(eq.getDstab()) + pos(eq.getDslash()) + pos(eq.getDcrush())) / 3.0;
		double ranged = pos(eq.getArange()) + pos(eq.getRstr()) * 2 + pos(eq.getDrange()) / 2.0;
		double magic = pos(eq.getAmagic()) + (eq.getMdmg() > 0 ? eq.getMdmg() * 100 : 0)
			+ pos(eq.getDmagic()) / 2.0;

		double best = Math.max(melee, Math.max(ranged, magic));
		if (best < 1.0)
		{
			return G_OTHER;   // capes/prayer/skilling equipables with no meaningful combat bias
		}
		if (best == ranged)
		{
			return G_RANGED;
		}
		if (best == magic)
		{
			return G_MAGIC;
		}
		return G_MELEE;
	}

	private static double pos(int v)
	{
		return v > 0 ? v : 0;
	}

	private static boolean isRune(String name)
	{
		return name.endsWith("rune") && !name.contains("essence");
	}

	private static boolean isPotion(String name)
	{
		return DOSE.matcher(name).find();
	}

	private static boolean isFood(String name)
	{
		return FOOD.contains(name) || (name.startsWith("cooked") && name.contains("karambwan"));
	}

	private static boolean isSkilling(String name)
	{
		for (String key : SKILLING_KEYS)
		{
			if (name.contains(key))
			{
				return true;
			}
		}
		return false;
	}

	// -- ordering helpers ---------------------------------------------------- //

	private int slotOrder(int id)
	{
		ItemStats stats = itemManager.getItemStats(id);
		if (stats == null || stats.getEquipment() == null)
		{
			return 99;
		}
		int slot = stats.getEquipment().getSlot();
		return slot >= 0 && slot < SLOT_ORDER.length ? SLOT_ORDER[slot] : 90;
	}

	private long price(int id)
	{
		try
		{
			return itemManager.getItemPrice(id);
		}
		catch (RuntimeException ex)
		{
			return 0;
		}
	}

	private String name(int id)
	{
		ItemComposition comp = itemManager.getItemComposition(id);
		return comp != null && comp.getName() != null ? comp.getName() : "";
	}
}

package com.runetools;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * Filters and (optionally) LAYS OUT the in-game bank to a gear setup, the way Inventory Setups
 * does: build a hidden Bank Tag ({@code runetools_setup_<id>}) of the setup's item ids, save a Bank Tags
 * {@link Layout} placing equipment on the left and inventory on the right, then open the tag with
 * that layout. Core Bank Tags does the actual hiding/positioning and re-applies it across redraws.
 *
 * <p>All Bank Tags coupling lives here; every call runs on the client thread.
 */
@Slf4j
class BankFilterController
{
	static final String TAG_PREFIX = BankTagNames.of("setup_");

	// Bank is 8 columns wide: pos = row*8 + col. Equipment sits in cols 0-2 (RS worn-slot shape),
	// inventory in cols 4-7 (col 3 is a gutter).
	private static final Map<String, Integer> EQUIP_POS = new HashMap<>();

	static
	{
		EQUIP_POS.put("head", 1);
		EQUIP_POS.put("cape", 8);
		EQUIP_POS.put("neck", 9);
		EQUIP_POS.put("ammo", 10);
		EQUIP_POS.put("weapon", 16);
		EQUIP_POS.put("body", 17);
		EQUIP_POS.put("shield", 18);
		EQUIP_POS.put("legs", 25);
		EQUIP_POS.put("hands", 32);
		EQUIP_POS.put("feet", 33);
		EQUIP_POS.put("ring", 34);
	}

	private static int invPos(int i)
	{
		return (i / 4) * 8 + 4 + (i % 4);
	}

	private final BankTagsService bankTags;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	BankFilterController(BankTagsService bankTags, TagManager tagManager, LayoutManager layoutManager,
						 ItemManager itemManager, ClientThread clientThread)
	{
		this.bankTags = bankTags;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
	}

	/** Tag the setup's items, optionally save a positional layout, and open the tag. */
	void filter(GearSetup setup, boolean fuzzy, boolean useLayout)
	{
		if (setup == null)
		{
			return;
		}
		clientThread.invoke(() ->
		{
			String tag = TAG_PREFIX + setup.getId();
			tagManager.removeTag(tag);                 // clear stale membership
			int n = 0;
			for (int id : setup.filterItemIds())
			{
				if (id > 0)
				{
					// Per-item fuzzy (like Inventory Setups) OR the global toggle.
					tagManager.addTag(id, tag, fuzzy || setup.isFuzzy(id));
					n++;
				}
			}
			tagManager.setHidden(tag, true);

			int opts = BankTagsService.OPTION_ALLOW_MODIFICATIONS
				| BankTagsService.OPTION_HIDE_TAG_NAME;
			if (useLayout)
			{
				saveLayout(setup, tag);                // open WITH the layout (no OPTION_NO_LAYOUT)
			}
			else
			{
				layoutManager.removeLayout(tag);       // drop any stale layout
				opts |= BankTagsService.OPTION_NO_LAYOUT;
			}
			bankTags.openBankTag(tag, opts);
			log.debug("RuneTools: bank filter -> \"{}\" ({} items, layout={})", setup.getName(), n, useLayout);
		});
	}

	private void saveLayout(GearSetup setup, String tag)
	{
		List<GearSetupItem> inv = setup.getInventory() != null ? setup.getInventory() : Collections.emptyList();
		int max = 34;                                  // last equipment cell (ring)
		for (int i = 0; i < inv.size(); i++)
		{
			max = Math.max(max, invPos(i));
		}
		int[] cells = new int[max + 1];
		Arrays.fill(cells, -1);                        // -1 == empty cell

		if (setup.getEquipment() != null)
		{
			for (Map.Entry<String, Integer> e : setup.getEquipment().entrySet())
			{
				Integer pos = EQUIP_POS.get(e.getKey());
				Integer id = e.getValue();
				if (pos != null && id != null && id > 0 && pos < cells.length)
				{
					cells[pos] = itemManager.canonicalize(id);
				}
			}
		}
		for (int i = 0; i < inv.size(); i++)
		{
			int pos = invPos(i);
			if (pos < cells.length && inv.get(i).getItemId() > 0)
			{
				cells[pos] = itemManager.canonicalize(inv.get(i).getItemId());
			}
		}
		layoutManager.saveLayout(new Layout(tag, cells));
	}

	/** Cancel our filter - only if OUR tag is the active one (don't clobber another plugin's). */
	void clear()
	{
		clientThread.invoke(() ->
		{
			String active = bankTags.getActiveTag();
			if (active != null && active.startsWith(TAG_PREFIX))
			{
				bankTags.closeBankTag();
			}
		});
	}

	/** Drop a setup's tag membership AND its saved layout (e.g. when deleted on the site). */
	void forget(long setupId)
	{
		clientThread.invoke(() ->
		{
			String tag = TAG_PREFIX + setupId;
			tagManager.removeTag(tag);
			layoutManager.removeLayout(tag);
		});
	}
}

package com.runetools;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;

/**
 * One-click bank organiser. Reads the items currently in the bank, asks {@link BankCategorizer}
 * to bucket them, and materialises one Bank Tags tab per category - each with the relevant items
 * tagged and a saved {@link Layout} that packs them into a tidy grid.
 *
 * <p>This never moves a single item in the real bank: like Inventory Setups' bank layouts it only
 * changes how core Bank Tags <em>renders</em> the tab, so it's purely client-side and rules-safe.
 * Every method runs on the client thread.
 *
 * <p>Tabs we create are remembered in config ({@link #KEY_OWNED}) so a re-organise cleanly rebuilds
 * our own tabs (and a "remove" cleanly deletes them) without disturbing tabs the user made.
 */
@Slf4j
class BankOrganizer
{
	private static final String GROUP = RuneToolsConfig.GROUP;
	private static final String KEY_OWNED = "organizedTabs";
	private static final String KEY_FILED = "organizedFiledItems";   // ids we've filed (for File-new)
	private static final String KEY_IMPORTED_BANK = "importedBankTabs";   // tabs of the last whole-bank import
	private static final String ALL_TAG = BankTagNames.of("All");   // a full-bank tab shown before the category tabs
	// Core Bank Tags config: the ordered CSV of tag-tab names the bank rebuilds its tab bar from.
	private static final int COLS = 8;
	private static final int MAX_LAYOUT_CELLS = 4096;   // hard cap on an imported layout's grid size

	private final BankTagsService bankTags;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final TabManager tabManager;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BankCategorizer categorizer;

	BankOrganizer(BankTagsService bankTags, TagManager tagManager, LayoutManager layoutManager,
				  TabManager tabManager, ItemManager itemManager, ClientThread clientThread,
				  ConfigManager configManager)
	{
		this.bankTags = bankTags;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.tabManager = tabManager;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.categorizer = new BankCategorizer(itemManager);
	}

	/** How a run treats tabs that already exist. */
	enum Mode
	{
		/** Regenerate every RuneTools tab from scratch (discards manual edits to them). */
		REBUILD,
		/** Keep existing tabs/edits untouched; only file items gained since the last organise. */
		FILE_NEW
	}

	/** True if we've already built our tabs (so the caller can prompt Rebuild vs File-new). */
	boolean hasOrganized()
	{
		return !ownedTags().isEmpty();
	}

	/**
	 * Organise the bank. {@code onStatus} is called (on the client thread) with a human status line.
	 * {@link Mode#REBUILD} rebuilds every tab; {@link Mode#FILE_NEW} only files newly-gained items,
	 * leaving existing tabs and any manual edits to them alone.
	 */
	void organize(List<Integer> bankItemIds, Mode mode, Consumer<String> onStatus)
	{
		clientThread.invoke(() ->
		{
			String msg = mode == Mode.FILE_NEW ? fileNew(bankItemIds) : rebuild(bankItemIds);
			if (onStatus != null)
			{
				onStatus.accept(msg);
			}
		});
	}

	/** Full (re)build: every tab regenerated from scratch. Resets the "already filed" set. */
	private String rebuild(List<Integer> bankItemIds)
	{
		List<BankCategorizer.CategoryTab> tabs = categorizer.categorize(bankItemIds);
		if (tabs.isEmpty())
		{
			return "Your bank looks empty - nothing to organize.";
		}

		// Desired tags this run: an "All" full-bank tab first, then one per category.
		List<String> owned = new ArrayList<>();
		owned.add(ALL_TAG);
		for (BankCategorizer.CategoryTab ct : tabs)
		{
			owned.add(BankTagNames.of(ct.category.label));
		}

		// Remove only the tabs we previously owned that we no longer want; keep the rest IN PLACE
		// (re-adding a still-wanted tab would append it to the end of the bar - the "jumps to the
		// bottom on re-organise" bug).
		for (String tag : ownedTags())
		{
			if (!owned.contains(tag))
			{
				tagManager.removeTag(tag);
				layoutManager.removeLayout(tag);
				tabManager.remove(tag);
			}
		}

		// "All" tab: tag every bank item, no custom layout, so it mirrors your whole bank.
		Set<Integer> filed = new LinkedHashSet<>();
		tagManager.removeTag(ALL_TAG);
		for (Integer raw : bankItemIds)
		{
			if (raw != null && raw > 0)
			{
				int id = itemManager.canonicalize(raw);
				tagManager.addTag(id, ALL_TAG, false);
				filed.add(id);
			}
		}
		layoutManager.removeLayout(ALL_TAG);
		ensureTab(ALL_TAG, mostValuable(bankItemIds));

		for (BankCategorizer.CategoryTab ct : tabs)
		{
			String tag = BankTagNames.of(ct.category.label);
			tagManager.removeTag(tag);                 // refresh membership (adds new items, drops gone)
			for (List<Integer> group : ct.groups)
			{
				for (int id : group)
				{
					tagManager.addTag(id, tag, false);
				}
			}
			layoutManager.saveLayout(new Layout(tag, packGroups(ct.groups)));
			ensureTab(tag, ct.iconItemId);
		}

		reorderLiveTabsFirst(owned);                   // put ours first (in place for existing, front for new)
		tabManager.save();                             // persist icons + tab order through Bank Tags' own API
		configManager.setConfiguration(GROUP, KEY_OWNED, String.join(",", owned));
		writeFiled(filed);

		bankTags.openBankTag(ALL_TAG, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		log.debug("RuneTools: organised bank into {} tab(s)", owned.size());
		return "Organized into " + owned.size() + " tabs. Open your bank to see it.";
	}

	/**
	 * Additive: file only the items the bank has gained since the last organise. Existing tabs, their
	 * layouts and any manual edits are left untouched - new items are appended after a tab's content,
	 * and a brand-new category gets a fresh tab. Falls back to a full build if we've never organised.
	 */
	private String fileNew(List<Integer> bankItemIds)
	{
		if (!hasOrganized())
		{
			return rebuild(bankItemIds);
		}

		Set<Integer> filed = readFiled();
		List<Integer> fresh = new ArrayList<>();
		Set<Integer> freshSeen = new HashSet<>();
		for (Integer raw : bankItemIds)
		{
			if (raw == null || raw <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(raw);
			if (!filed.contains(id) && freshSeen.add(id))
			{
				fresh.add(id);
			}
		}
		if (fresh.isEmpty())
		{
			return "No new items to file.";
		}

		List<BankCategorizer.CategoryTab> newTabs = categorizer.categorize(fresh);
		List<String> owned = ownedTags();
		boolean structureChanged = false;

		// All tab gets every fresh item (it has no custom layout, so order doesn't matter).
		for (int id : fresh)
		{
			tagManager.addTag(id, ALL_TAG, false);
		}
		if (tabManager.find(ALL_TAG) == null)
		{
			ensureTab(ALL_TAG, mostValuable(bankItemIds));
			if (!owned.contains(ALL_TAG))
			{
				owned.add(0, ALL_TAG);
				structureChanged = true;
			}
		}

		for (BankCategorizer.CategoryTab ct : newTabs)
		{
			String tag = BankTagNames.of(ct.category.label);
			List<Integer> catIds = flatten(ct.groups);
			for (int id : catIds)
			{
				tagManager.addTag(id, tag, false);
			}
			Layout existing = layoutManager.loadLayout(tag);
			if (existing == null)
			{
				layoutManager.saveLayout(new Layout(tag, packGroups(ct.groups)));
				ensureTab(tag, ct.iconItemId);
				if (!owned.contains(tag))
				{
					owned.add(tag);
					structureChanged = true;
				}
			}
			else
			{
				appendToLayout(tag, existing, catIds);   // preserve existing positions/edits
				ensureTab(tag, -1);                       // keep the user's icon
			}
		}

		filed.addAll(fresh);
		writeFiled(filed);

		if (structureChanged)
		{
			reorderLiveTabsFirst(owned);
			tabManager.save();
			configManager.setConfiguration(GROUP, KEY_OWNED, String.join(",", owned));
		}
		tabManager.save();
		log.debug("RuneTools: filed {} new item(s)", fresh.size());
		return "Filed " + fresh.size() + " new item" + (fresh.size() == 1 ? "" : "s") + " into their tabs.";
	}

	/** Find-or-create a tab for {@code tag}, refreshing its icon. Leaves an existing tab's position. */
	private void ensureTab(String tag, int icon)
	{
		TagTab tab = tabManager.find(tag);
		if (tab == null)
		{
			tab = new TagTab();
			tab.setTag(tag);
			tab.setIconItemId(icon);
			tabManager.add(tab);
		}
		else if (icon > 0)
		{
			tab.setIconItemId(icon);
		}
	}

	/** The most valuable item in the bank - used as the "All" tab's icon. */
	private int mostValuable(List<Integer> bankItemIds)
	{
		int bestId = -1;
		long bestPrice = -1;
		for (Integer raw : bankItemIds)
		{
			if (raw == null || raw <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(raw);
			long price;
			try
			{
				price = itemManager.getItemPrice(id);
			}
			catch (RuntimeException ex)
			{
				price = 0;
			}
			if (price > bestPrice)
			{
				bestPrice = price;
				bestId = id;
			}
		}
		return bestId;
	}

	private static List<Integer> flatten(List<List<Integer>> rows)
	{
		List<Integer> out = new ArrayList<>();
		for (List<Integer> row : rows)
		{
			out.addAll(row);
		}
		return out;
	}

	/**
	 * Append {@code ids} onto a tab's existing layout without disturbing anything already placed:
	 * keep every occupied cell where it is, then add the new items on a fresh row after the last one.
	 */
	private void appendToLayout(String tag, Layout existing, List<Integer> ids)
	{
		int[] cur = existing.getLayout();
		int last = -1;
		for (int i = 0; i < cur.length; i++)
		{
			if (cur[i] > 0)
			{
				last = i;
			}
		}
		List<Integer> cells = new ArrayList<>();
		for (int i = 0; i <= last; i++)
		{
			cells.add(cur[i]);
		}
		while (cells.size() % COLS != 0)   // start the new items on a fresh row
		{
			cells.add(-1);
		}
		cells.addAll(ids);
		int[] out = new int[Math.max(cells.size(), COLS)];
		Arrays.fill(out, -1);
		for (int i = 0; i < cells.size(); i++)
		{
			out[i] = cells.get(i);
		}
		layoutManager.saveLayout(new Layout(tag, out));
	}

	private Set<Integer> readFiled()
	{
		Set<Integer> out = new HashSet<>();
		String raw = configManager.getConfiguration(GROUP, KEY_FILED);
		if (raw != null && !raw.trim().isEmpty())
		{
			for (String s : raw.split(","))
			{
				try
				{
					out.add(Integer.parseInt(s.trim()));
				}
				catch (NumberFormatException ignored)
				{
					// skip malformed entries
				}
			}
		}
		return out;
	}

	private void writeFiled(Set<Integer> ids)
	{
		StringBuilder sb = new StringBuilder();
		for (int id : ids)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(id);
		}
		configManager.setConfiguration(GROUP, KEY_FILED, sb.toString());
	}

	/** Delete every tab/layout/tag this organiser created, leaving the user's own tabs untouched. */
	void remove(Runnable onDone)
	{
		clientThread.invoke(() ->
		{
			clearOwned();
			tabManager.save();
			configManager.unsetConfiguration(GROUP, KEY_OWNED);
			configManager.unsetConfiguration(GROUP, KEY_FILED);
			if (BankTagNames.ours(bankTags.getActiveTag()))
			{
				bankTags.closeBankTag();
			}
			log.debug("RuneTools: removed organised bank tabs");
			if (onDone != null)
			{
				onDone.run();
			}
		});
	}

	/**
	 * Turn a native bank tab's exact contents (item ids in tab order, passed in by the caller) into a
	 * standalone Bank Tags tag + layout + tab named {@code name} after {@link BankTagNames#PREFIX}. This is a user-owned tag - it is NOT
	 * tracked in {@link #KEY_OWNED}, so Rebuild/Remove never touch it - and it can be shared straight
	 * away via core Bank Tags' right-click "Export tag tab". The name is sanitised like any tag name,
	 * and a tag that already exists is never overwritten: the player is asked for another name.
	 * {@code onStatus} gets a status line and whether it is good news.
	 */
	void saveTabAsTag(String name, List<Integer> ids, BiConsumer<String, Boolean> onStatus)
	{
		clientThread.invoke(() ->
		{
			if (ids.isEmpty())
			{
				onStatus.accept("That bank tab is empty.", false);
				return;
			}
			String bare = sanitizeTagName(name);
			if (bare.isEmpty())
			{
				onStatus.accept("Enter a name for the tag.", false);
				return;
			}
			String tag = BankTagNames.of(bare);
			if (tagExists(tag))
			{
				onStatus.accept("A tag named \"" + tag + "\" already exists. Pick another name.", false);
				return;
			}
			List<Integer> canon = new ArrayList<>();
			for (int id : ids)
			{
				int c = itemManager.canonicalize(id);
				tagManager.addTag(c, tag, false);
				canon.add(c);
			}
			int[] cells = new int[Math.max(canon.size(), COLS)];
			Arrays.fill(cells, -1);
			for (int i = 0; i < canon.size(); i++)
			{
				cells[i] = canon.get(i);               // dense, in tab order - mirrors the native tab
			}
			layoutManager.saveLayout(new Layout(tag, cells));
			ensureTab(tag, mostValuable(canon));
			tabManager.save();
			bankTags.openBankTag(tag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
			log.debug("RuneTools: saved bank tab as tag \"{}\" ({} items)", tag, canon.size());
			onStatus.accept("Saved as tag \"" + tag + "\".", true);
		});
	}

	/** Whether a Bank Tags tab or tag with this name already exists. Client thread. */
	private boolean tagExists(String tag)
	{
		if (tabManager.find(tag) != null)
		{
			return true;
		}
		try
		{
			return !tagManager.getItemsForTag(tag).isEmpty();
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}

	/**
	 * Apply a layout imported from the site: create/refresh a Bank Tags tag + positional layout + tab
	 * named {@code name} from the given cells (index = grid position, value = item id, -1 = empty).
	 * A user-owned tag - NOT tracked in {@link #KEY_OWNED} - so Rebuild/Remove never touch it.
	 */
	void applyImportedLayout(String name, int icon, int[] cells)
	{
		clientThread.invoke(() ->
		{
			String base = sanitizeTagName(name);
			if (base.isEmpty() || cells == null || cells.length == 0)
			{
				return;
			}
			// Never destructively overwrite a tab the user (or the organiser) already owns: an
			// imported layout reusing an existing tag name gets a fresh, non-colliding name instead.
			String tag = uniqueTagName(BankTagNames.of(base));
			makeTab(tag, icon, cells, null);
			tabManager.save();
			log.debug("RuneTools: applied imported layout \"{}\"", tag);
		});
	}

	/**
	 * Tag {@code tag} with the items of an untrusted positional layout (index = grid position, value =
	 * item id, -1 = empty), save the layout and make sure the tab exists. Adds every item placed to
	 * {@code placed} when given. Returns false when the layout held no usable item.
	 */
	private boolean makeTab(String tag, int icon, int[] cells, Set<Integer> placed)
	{
		// Cap grid size on untrusted imports (the caller also bounds it).
		int[] safe = cells.length > MAX_LAYOUT_CELLS ? Arrays.copyOf(cells, MAX_LAYOUT_CELLS) : cells.clone();
		int first = -1;
		tagManager.removeTag(tag);
		for (int i = 0; i < safe.length; i++)
		{
			int id = safe[i];
			if (id > 0 && plausibleItemId(id) && id != ItemID.BANK_FILLER)
			{
				int c = itemManager.canonicalize(id);
				tagManager.addTag(c, tag, false);
				safe[i] = c;
				if (placed != null)
				{
					placed.add(c);
				}
				if (first < 0)
				{
					first = c;
				}
			}
			else
			{
				safe[i] = -1;   // drop implausible ids rather than write junk keys into banktags config
			}
		}
		if (first < 0)
		{
			return false;
		}
		layoutManager.saveLayout(new Layout(tag, safe));
		ensureTab(tag, (icon > 0 && plausibleItemId(icon)) ? icon : first);
		return true;
	}

	/** One tab of a whole bank layout imported from the site. */
	static final class BankTab
	{
		final String name;
		final int icon;
		final int[] cells;   // index = grid position, value = item id, -1 = empty

		BankTab(String name, int icon, int[] cells)
		{
			this.name = name;
			this.icon = icon;
			this.cells = cells;
		}
	}

	/**
	 * Apply a whole bank layout imported from the site: one Bank Tags tab per shared tab, in its order
	 * and at the front of the tab bar, then a <b>Misc</b> tab with everything in this bank (placeholders
	 * included) that the layout doesn't place. Replaces the tabs of the previous whole-bank import and,
	 * like every tab here, moves nothing in the real bank. Call on the client thread with this
	 * character's bank contents; returns a status line.
	 */
	String applyImportedBank(String name, List<BankTab> tabs, List<Integer> bankItemIds)
	{
		clearImportedBank();
		String prefix = sanitizeTagName(name);
		if (prefix.length() > 24)
		{
			prefix = prefix.substring(0, 24).trim();
		}
		if (prefix.isEmpty())
		{
			prefix = "Imported";
		}
		List<String> made = new ArrayList<>();
		Set<Integer> placed = new HashSet<>();
		for (BankTab t : tabs)
		{
			String tag = uniqueTagName(BankTagNames.of(sanitizeTagName(prefix + " " + sanitizeTagName(t.name))));
			if (t.cells != null && t.cells.length > 0 && makeTab(tag, t.icon, t.cells, placed))
			{
				made.add(tag);
			}
		}
		List<Integer> misc = unplaced(bankItemIds, placed, itemManager::canonicalize);
		if (!misc.isEmpty())
		{
			String tag = uniqueTagName(BankTagNames.of(sanitizeTagName(prefix + " Misc")));
			if (makeTab(tag, -1, packGroups(Collections.singletonList(misc)), null))
			{
				made.add(tag);
			}
		}
		reorderLiveTabsFirst(made);
		tabManager.save();
		configManager.setConfiguration(GROUP, KEY_IMPORTED_BANK, String.join(",", made));
		if (!made.isEmpty())
		{
			bankTags.openBankTag(made.get(0), BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
		log.debug("RuneTools: applied imported bank \"{}\" as {} tab(s)", prefix, made.size());
		int laidOut = made.size() - (misc.isEmpty() ? 0 : 1);
		return "Imported \"" + prefix + "\": " + laidOut + " tab" + (laidOut == 1 ? "" : "s")
			+ (misc.isEmpty() ? "" : ", plus Misc with " + misc.size() + " item" + (misc.size() == 1 ? "" : "s")
				+ " of yours it doesn't place")
			+ ". Open your bank to see it.";
	}

	/**
	 * What goes in an imported bank's Misc tab: each item in the bank (as {@code canon} names it, so a
	 * placeholder counts as its item) that the layout doesn't place, once, in bank order. Bank fillers
	 * and empty slots are skipped.
	 */
	static List<Integer> unplaced(List<Integer> bankItemIds, Set<Integer> placed, IntUnaryOperator canon)
	{
		List<Integer> out = new ArrayList<>();
		Set<Integer> seen = new HashSet<>();
		for (Integer raw : bankItemIds)
		{
			if (raw == null || raw <= 0 || raw == ItemID.BANK_FILLER)
			{
				continue;
			}
			int c = canon.applyAsInt(raw);
			if (!placed.contains(c) && seen.add(c))
			{
				out.add(c);
			}
		}
		return out;
	}

	/**
	 * Slice the bank's items into its native tabs: tabs 1 to {@code tabCounts.length} (each holding
	 * the next {@code tabCounts[i]} items, as the BANK_TAB varbits count them), then the main tab with
	 * the rest. Each tab is an array of slot -> item id (as {@code canon} names it, so a placeholder
	 * becomes its item), with -1 for a bank filler or an empty slot, which keeps the gap in place.
	 */
	static List<int[]> nativeTabs(int[] itemIds, int[] tabCounts, IntUnaryOperator canon)
	{
		List<int[]> out = new ArrayList<>();
		int offset = 0;
		for (int t = 0; t <= tabCounts.length; t++)
		{
			int count = t == tabCounts.length ? itemIds.length - offset : tabCounts[t];
			count = Math.max(0, Math.min(count, itemIds.length - offset));
			int[] tab = new int[count];
			for (int i = 0; i < count; i++)
			{
				int id = itemIds[offset + i];
				tab[i] = id <= 0 || id == ItemID.BANK_FILLER ? -1 : canon.applyAsInt(id);
			}
			out.add(tab);
			offset += count;
		}
		return out;
	}

	/** True if a whole bank layout imported from the site is applied. */
	boolean hasImportedBank()
	{
		return !csv(KEY_IMPORTED_BANK).isEmpty();
	}

	/** Delete the tabs of the last whole-bank import (leaves every other tab alone). */
	void removeImportedBank(Runnable onDone)
	{
		clientThread.invoke(() ->
		{
			List<String> tags = csv(KEY_IMPORTED_BANK);
			String active = bankTags.getActiveTag();
			clearImportedBank();
			tabManager.save();
			if (active != null && tags.contains(active))
			{
				bankTags.closeBankTag();
			}
			if (onDone != null)
			{
				onDone.run();
			}
		});
	}

	private void clearImportedBank()
	{
		for (String tag : csv(KEY_IMPORTED_BANK))
		{
			tagManager.removeTag(tag);
			layoutManager.removeLayout(tag);
			tabManager.remove(tag);
		}
		configManager.unsetConfiguration(GROUP, KEY_IMPORTED_BANK);
	}

	/**
	 * Sanitise an untrusted (server/imported) tag name: drop control characters, the commas/newlines
	 * that delimit the {@code banktags.tagtabs}/{@code banktags.item_*} CSVs, and the angle brackets
	 * that would let it start Swing auto-HTML in a status label; cap the length.
	 */
	static String sanitizeTagName(String name)
	{
		if (name == null)
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < name.length() && sb.length() < 40; i++)
		{
			char c = name.charAt(i);
			if (c >= 0x20 && c != 0x7f && c != ',' && c != '<' && c != '>')
			{
				sb.append(c);
			}
		}
		return sb.toString().trim();
	}

	/** A free tab name based on {@code base}, so applying an import never clobbers an existing tab. */
	private String uniqueTagName(String base)
	{
		if (tabManager.find(base) == null)
		{
			return base;
		}
		for (int i = 2; i < 100; i++)
		{
			String candidate = base + " (" + i + ")";
			if (tabManager.find(candidate) == null)
			{
				return candidate;
			}
		}
		return base;
	}

	/** Reject obviously-bogus item ids so imported data can't scatter junk keys into banktags config. */
	private static boolean plausibleItemId(int id)
	{
		return id > 0 && id <= 5_000_000;
	}

	private void clearOwned()
	{
		for (String tag : ownedTags())
		{
			tagManager.removeTag(tag);
			layoutManager.removeLayout(tag);
			tabManager.remove(tag);
		}
	}

	private List<String> ownedTags()
	{
		return csv(KEY_OWNED);
	}

	/**
	 * A config value holding a comma-separated list of tag names, only those named as ours: a list
	 * saved before the prefix (or edited by hand) can't make this plugin change a player's own tag.
	 */
	private List<String> csv(String key)
	{
		String raw = configManager.getConfiguration(GROUP, key);
		if (raw == null || raw.trim().isEmpty())
		{
			return new ArrayList<>();
		}
		List<String> out = new ArrayList<>();
		for (String t : raw.split(","))
		{
			String s = t.trim();
			if (BankTagNames.ours(s))
			{
				out.add(s);
			}
		}
		return out;
	}

	/**
	 * Row-major packing where each list in {@code rows} occupies its own grid row (wrapping if it
	 * holds more than {@link #COLS} items). An <em>empty</em> row is honoured as a full blank row, so
	 * the categoriser can use it as a visible separator between groups. Bank Tags treats -1 as empty.
	 */
	private static int[] packGroups(List<List<Integer>> rows)
	{
		List<Integer> cells = new ArrayList<>();
		for (List<Integer> row : rows)
		{
			while (cells.size() % COLS != 0)   // move to the start of the next row
			{
				cells.add(-1);
			}
			if (row == null || row.isEmpty())
			{
				for (int i = 0; i < COLS; i++)
				{
					cells.add(-1);             // a whole blank row as a separator
				}
			}
			else
			{
				cells.addAll(row);
			}
		}
		int[] out = new int[Math.max(cells.size(), COLS)];
		Arrays.fill(out, -1);
		for (int i = 0; i < cells.size(); i++)
		{
			out[i] = cells.get(i);
		}
		return out;
	}

	/**
	 * Move our category tabs to the front of core Bank Tags' <em>live</em> tab list. The tab bar
	 * renders from this list, and {@link TabManager#save()} re-serialises it - so leading the list is
	 * what keeps a later save from writing our tabs back to the end.
	 */
	private void reorderLiveTabsFirst(List<String> owned)
	{
		List<TagTab> live = tabManager.getTabs();
		List<TagTab> ours = new ArrayList<>();
		for (String tag : owned)
		{
			TagTab t = tabManager.find(tag);
			if (t != null)
			{
				ours.add(t);
			}
		}
		live.removeAll(ours);
		live.addAll(0, ours);
	}
}

package com.runetools;

import java.util.Locale;

/**
 * Every Bank Tags tag, tab and layout this plugin adds, changes or deletes is named with {@link #PREFIX},
 * so it can never touch a tag the player made (Plugin Hub rule). Bank Tags keeps tag names lower case.
 */
final class BankTagNames
{
	static final String PREFIX = "runetools_";

	private BankTagNames()
	{
	}

	/** Our tag for {@code name}: the prefix, then the name. */
	static String of(String name)
	{
		return PREFIX + name;
	}

	/** Whether {@code tag} is one of ours (so this plugin may change or delete it). */
	static boolean ours(String tag)
	{
		return tag != null && tag.toLowerCase(Locale.ROOT).startsWith(PREFIX);
	}

	/** {@code tag} without our prefix, for a name the player types or reads. */
	static String shown(String tag)
	{
		return ours(tag) ? tag.substring(PREFIX.length()) : tag;
	}
}

package com.runetools;

import java.util.concurrent.atomic.AtomicReference;

/**
 * Everything captured from the character in game, kept together so it can be dropped together the
 * moment it stops belonging to whoever is playing.
 *
 * <ul>
 *   <li>The account snapshot (bank, inventory, worn gear, skills, offers, name and account hash) and
 *       the coin counters belong to one character's session: a logout drops them, and so does any
 *       capture that finds a different account hash. Without that, the previous character's bank or
 *       skills were uploaded as the next one's.</li>
 *   <li>The Grand Exchange baselines (and this session's P/L) belong to one character: a different
 *       account hash gets fresh ones, but a logout or world hop keeps them, so fills that happened
 *       while logged out are still counted once at the next login.</li>
 * </ul>
 *
 * <p>{@link #adopt} and the trackers are used on the client thread; the snapshot is published through
 * an atomic reference for the sync thread.
 */
final class CharacterState
{
	final AtomicReference<AccountSnapshot> snapshot = new AtomicReference<>(AccountSnapshot.empty());

	private String owner;          // account hash the snapshot belongs to, null when none
	private String trackerOwner;   // account hash the GE trackers belong to, null when none
	private OfferTracker offers = new OfferTracker();
	private SessionTracker session = new SessionTracker();

	// Client thread only.
	int inventoryCoins;
	int bankCoins;

	// The bank the server last accepted in a /state body (its hash), so an unchanged bank is left out.
	private volatile int acceptedBankHash;
	private volatile boolean bankAccepted;

	/**
	 * What was captured now belongs to {@code hash} (the account hash in game). A different hash than
	 * the one the captured state came from drops that state and starts fresh GE trackers. Returns
	 * true when anything was dropped. A null hash (not known yet) changes nothing.
	 */
	synchronized boolean adopt(String hash)
	{
		if (hash == null || hash.isEmpty())
		{
			return false;
		}
		boolean dropped = false;
		if (trackerOwner != null && !trackerOwner.equals(hash))
		{
			offers = new OfferTracker();
			session = new SessionTracker();
			dropped = true;
		}
		trackerOwner = hash;
		if (owner != null && !owner.equals(hash))
		{
			clearCaptured();
			dropped = true;
		}
		owner = hash;
		return dropped;
	}

	/** Back at the login screen: the session's capture goes, the GE baselines stay with their character. */
	synchronized void logout()
	{
		clearCaptured();
		owner = null;
	}

	/** The plugin was switched off: forget everything. */
	synchronized void reset()
	{
		clearCaptured();
		owner = null;
		trackerOwner = null;
		offers = new OfferTracker();
		session = new SessionTracker();
	}

	/** The account hash the captured state belongs to, or null. */
	synchronized String owner()
	{
		return owner;
	}

	synchronized OfferTracker offers()
	{
		return offers;
	}

	synchronized SessionTracker session()
	{
		return session;
	}

	/** Whether {@code bankHash} is the bank the server already holds for this character. */
	boolean bankAlreadySent(int bankHash)
	{
		return bankAccepted && acceptedBankHash == bankHash;
	}

	/** The server accepted a /state body carrying this bank. */
	void bankSent(int bankHash)
	{
		acceptedBankHash = bankHash;
		bankAccepted = true;
	}

	private void clearCaptured()
	{
		snapshot.set(AccountSnapshot.empty());
		inventoryCoins = 0;
		bankCoins = 0;
		bankAccepted = false;
		acceptedBankHash = 0;
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/**
 * Reads the player's Collection Log from the game so the site can render a per-account replica.
 *
 * <p>The complete obtained set is NOT stored account-wide in varps (only a handful of gating
 * varbits plus overall/per-tab counters), so per-item data is read from the collection-log
 * <em>interface</em> as the player opens pages - the same approach the collection-log ecosystem
 * uses. Overall progress comes straight from varps and is available the moment you log in.
 *
 * <p>Interface, varbit and varp ids come from RuneLite's gameval constants ({@code InterfaceID},
 * {@code VarbitID}, {@code VarPlayerID}); the page-draw script is {@code ScriptID.COLLECTION_DRAW_LIST}.
 * The three whole-log scripts below ({@link #SETUP_SCRIPT}, {@link #TRANSMIT_SCRIPT},
 * {@link #INIT_SCRIPT}) have no public constant, so they stay numeric. Every read here touches
 * widgets/varps and MUST run on the client thread.
 */
final class CollectionLog
{
	// Whole-log transmit. SETUP_SCRIPT fires when the interface is built; asking for a search makes
	// the server send every entry, one TRANSMIT_SCRIPT pre-fire each; INIT_SCRIPT restores the view.
	static final int SETUP_SCRIPT = 7797;      // collection log interface setup
	static final int TRANSMIT_SCRIPT = 4100;   // one obtained entry: args {?, itemId, quantity}
	private static final int INIT_SCRIPT = 2240;

	// Per-tab page-list containers, indexed by tab 0..4: boss, raid, clue, minigame, other.
	private static final int[] TAB_CONTAINER = {
		InterfaceID.Collection.BOSS_CONTAINER,
		InterfaceID.Collection.RAID_CONTAINER,
		InterfaceID.Collection.CLUE_CONTAINER,
		InterfaceID.Collection.MINIGAME_CONTAINER,
		InterfaceID.Collection.OTHER_CONTAINER};

	// Per-tab {obtained, total} counters, in tab order - always available once logged in.
	private static final int[][] VP_TAB = {
		{VarPlayerID.COLLECTION_COUNT_BOSSES, VarPlayerID.COLLECTION_COUNT_BOSSES_MAX},
		{VarPlayerID.COLLECTION_COUNT_RAIDS, VarPlayerID.COLLECTION_COUNT_RAIDS_MAX},
		{VarPlayerID.COLLECTION_COUNT_CLUES, VarPlayerID.COLLECTION_COUNT_CLUES_MAX},
		{VarPlayerID.COLLECTION_COUNT_MINIGAMES, VarPlayerID.COLLECTION_COUNT_MINIGAMES_MAX},
		{VarPlayerID.COLLECTION_COUNT_OTHER, VarPlayerID.COLLECTION_COUNT_OTHER_MAX}};
	static final String[] TAB_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};

	private CollectionLog()
	{
	}

	/** Overall + per-tab progress, straight from varps. Returns null before the counters populate. */
	static JsonObject readTotals(Client client)
	{
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total <= 0)
		{
			return null;
		}
		JsonObject t = new JsonObject();
		t.addProperty("obtained", Math.max(0, client.getVarpValue(VarPlayerID.COLLECTION_COUNT)));
		t.addProperty("total", total);
		JsonArray tabs = new JsonArray();
		for (int i = 0; i < VP_TAB.length; i++)
		{
			JsonObject o = new JsonObject();
			o.addProperty("name", TAB_NAMES[i]);
			o.addProperty("obtained", Math.max(0, client.getVarpValue(VP_TAB[i][0])));
			o.addProperty("total", Math.max(0, client.getVarpValue(VP_TAB[i][1])));
			tabs.add(o);
		}
		t.add("tabs", tabs);
		return t;
	}

	/** The page currently drawn in the open collection log, or null if it can't be read. */
	static Page readOpenPage(Client client, ItemManager itemManager)
	{
		Widget container = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (container == null)
		{
			return null;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}

		// Which page is open - a stable (tab, category) key independent of the UI text.
		int tab = client.getVarbitValue(VarbitID.COLLECTION_LAST_TAB);
		int category = client.getVarbitValue(VarbitID.COLLECTION_LAST_CATEGORY);

		JsonArray items = new JsonArray();
		int hash = 1;
		for (Widget w : children)
		{
			int id = w.getItemId();
			if (id <= 0)
			{
				continue;
			}
			boolean obtained = w.getOpacity() == 0;   // the log fades unobtained items (opacity > 0)
			int qty = obtained ? Math.max(1, w.getItemQuantity()) : 0;
			JsonObject it = new JsonObject();
			it.addProperty("id", id);
			it.addProperty("obtained", obtained);
			if (obtained && qty > 1)
			{
				it.addProperty("qty", qty);
			}
			String name = itemName(itemManager, id);
			if (name != null)
			{
				it.addProperty("name", name);
			}
			items.add(it);
			hash = hash * 31 + id * 2 + (obtained ? 1 : 0) + qty * 7;
		}
		if (items.size() == 0)
		{
			return null;
		}

		JsonObject page = new JsonObject();
		page.addProperty("tab", tab);
		page.addProperty("category", category);
		String pageName = readPageName(client, tab, category);
		if (pageName != null && !pageName.isEmpty())
		{
			page.addProperty("name", pageName);
		}
		page.add("items", items);
		return new Page(tab + ":" + category, hash, page);
	}

	private static String itemName(ItemManager itemManager, int id)
	{
		if (itemManager == null)
		{
			return null;
		}
		try
		{
			String n = itemManager.getItemComposition(id).getName();
			return n != null && !n.isEmpty() && !n.equalsIgnoreCase("null") ? n : null;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	/**
	 * Best-effort page title from the active tab's page list; may be null (the (tab, category) key
	 * still identifies the page). Layout is UI-dependent, so this picks the category-th text entry.
	 */
	private static String readPageName(Client client, int tab, int category)
	{
		if (tab < 0 || tab >= TAB_CONTAINER.length || category < 0)
		{
			return null;
		}
		Widget list = client.getWidget(TAB_CONTAINER[tab]);
		if (list == null)
		{
			return null;
		}
		Widget[] entries = list.getDynamicChildren();
		if (entries == null)
		{
			return null;
		}
		int seen = -1;
		for (Widget e : entries)
		{
			String txt = e.getText();
			if (txt != null && !txt.isEmpty())
			{
				if (++seen == category)
				{
					return txt;
				}
			}
		}
		return null;
	}

	// -- whole-log capture: ask the SERVER for everything, once ----------------------------- //

	/**
	 * True when the open collection log belongs to SOMEONE ELSE - you are viewing it through a POH
	 * Adventure Log. Their items must never be read: they would be uploaded under your account and
	 * shown as yours, and collecting data about other players is a listed Plugin Hub rejection
	 * reason. Every capture path checks this.
	 */
	static boolean isOtherPlayers(Client client)
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	/**
	 * Ask the server to transmit the whole collection log. The "Search" op on the interface's search
	 * toggle is what makes the server send every entry (each arrives as its own
	 * {@link #TRANSMIT_SCRIPT} pre-fire); re-running the interface's init script then puts the view
	 * back how the player left it.
	 *
	 * <p>Why this is acceptable for a Plugin Hub plugin: RuneLite's "Rejected or Rolled Back
	 * Features" wiki page lists {@code Client.menuAction} as a sensitive API and names exactly this
	 * call, the collection log Search toggle, as its one acceptable use ("fetching collection log
	 * data"). It is an interface-only op: it opens no other interface, moves nothing, and has no effect in the
	 * game world. The plugin only makes it when the player has just opened their own Collection Log
	 * themselves, at most once per opening, never for a log viewed in someone else's house, and only
	 * when they have consented to syncing and connected this character. The init script is the log's
	 * own UI script and sends nothing to the server.
	 *
	 * <p>The call is kept textually identical to RuneLite's published form so a reviewer can match
	 * it at a glance. Client thread only.
	 */
	static void requestFullLog(Client client)
	{
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(INIT_SCRIPT);
	}

	/** A single collection-log page read from the interface, with a change hash for dedup. */
	static final class Page
	{
		final String key;        // "tab:category" - stable page identity
		final int hash;          // content hash so an unchanged page isn't re-sent
		final JsonObject json;   // {tab, category, name?, items:[{id, obtained, qty?, name?}]}

		Page(String key, int hash, JsonObject json)
		{
			this.key = key;
			this.hash = hash;
			this.json = json;
		}
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.concurrent.atomic.AtomicBoolean;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads the player's Combat Achievements - the full task catalogue and per-task completion - straight
 * from the game cache, so the site can render a proper planner. Varbits and varps come from RuneLite's
 * gameval constants; the tier enums and task struct params have no public constant, so they are stable
 * cache ids (verified against osrs-reldo/task-json-store and the combat-achievements-tracker plugin):
 *
 * <ul>
 *   <li>one int-enum of task struct ids per tier ({@link #TIER_ENUMS});</li>
 *   <li>struct params for id/name/desc/tier/type/monster;</li>
 *   <li>completion is a bitmap packed across 21 VarPlayers ({@link #COMPLETION_VARPS}), indexed by
 *       the task's global id (param 1306): {@code varp[id/32] bit (id%32)}.</li>
 * </ul>
 *
 * <p>Those varps reach task id 671. A task past that (one a game update adds before RuneLite names the
 * next varp) can't be read, so it is sent in {@code unknown} rather than as not done, the panel leaves
 * it out of the counts, and the client log says so once.
 *
 * <p>{@link #read} must run on the client thread; the cache structs only resolve while logged in.
 * Task counts and tier point thresholds change with game updates, so everything is enumerated at
 * runtime - only the ids here are hard-coded.
 */
@Slf4j
final class CombatAchievements
{
	private static final AtomicBoolean LOGGED_UNREADABLE = new AtomicBoolean();

	// One enum of task struct ids per tier, in tier order (points = tier index + 1).
	private static final int[] TIER_ENUMS = {3981, 3982, 3983, 3984, 3985, 3986};
	static final String[] TIER_NAMES = {"easy", "medium", "hard", "elite", "master", "grandmaster"};
	static final String[] TIER_LABELS = {"Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster"};

	// Point thresholds to COMPLETE each tier - game varbits, read at runtime because Jagex bumps
	// them whenever tasks are added.
	private static final int[] TIER_THRESHOLD_VARBITS = {
		VarbitID.CA_THRESHOLD_EASY, VarbitID.CA_THRESHOLD_MEDIUM, VarbitID.CA_THRESHOLD_HARD,
		VarbitID.CA_THRESHOLD_ELITE, VarbitID.CA_THRESHOLD_MASTER, VarbitID.CA_THRESHOLD_GRANDMASTER};

	// Completion bitmap varps, in bit order - non-contiguous game varp ids, order is load-bearing.
	private static final int[] COMPLETION_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20};

	// CA task struct params.
	private static final int P_ID = 1306;       // global task id (also the completion bit index)
	private static final int P_NAME = 1308;
	private static final int P_DESC = 1309;
	private static final int P_TYPE = 1311;
	private static final int P_MONSTER = 1312;
	private static final int ENUM_MONSTER = 3971;   // bossId -> name

	private static final String[] TYPE_NAMES = {
		null, "stamina", "perfection", "kill_count", "mechanical", "restriction", "speed"};   // 1-indexed

	private CombatAchievements()
	{
	}

	/** The catalogue + completion read from the cache, ready to POST, plus a change hash. */
	static final class Snapshot
	{
		final JsonArray tasks;
		final JsonArray completed;
		final JsonArray unknown;   // task ids whose completion can't be read (past the known varps)
		final JsonObject tiers;
		final int completedHash;
		// Per-tier stats (index = tier order) for the in-plugin progress display.
		final int[] tierDone;
		final int[] tierTotal;
		final int[] tierEarnedPts;
		final int[] tierPossiblePts;

		Snapshot(JsonArray tasks, JsonArray completed, JsonArray unknown, JsonObject tiers, int completedHash,
				 int[] tierDone, int[] tierTotal, int[] tierEarnedPts, int[] tierPossiblePts)
		{
			this.tasks = tasks;
			this.completed = completed;
			this.unknown = unknown;
			this.tiers = tiers;
			this.completedHash = completedHash;
			this.tierDone = tierDone;
			this.tierTotal = tierTotal;
			this.tierEarnedPts = tierEarnedPts;
			this.tierPossiblePts = tierPossiblePts;
		}

		int totalEarnedPts()
		{
			int s = 0;
			for (int p : tierEarnedPts)
			{
				s += p;
			}
			return s;
		}
	}

	/** The point threshold to complete each tier, in tier order. Client thread. */
	static int[] readTierThresholds(Client client)
	{
		int[] out = new int[TIER_THRESHOLD_VARBITS.length];
		for (int i = 0; i < out.length; i++)
		{
			try
			{
				out[i] = client.getVarbitValue(TIER_THRESHOLD_VARBITS[i]);
			}
			catch (RuntimeException ex)
			{
				out[i] = 0;
			}
		}
		return out;
	}

	/** Read all tasks + completion. Returns null if the CA cache data isn't available yet. */
	static Snapshot read(Client client)
	{
		JsonArray tasks = new JsonArray();
		JsonArray completed = new JsonArray();
		JsonArray unknown = new JsonArray();
		int[] tierDone = new int[TIER_ENUMS.length];
		int[] tierTotal = new int[TIER_ENUMS.length];
		int[] tierEarnedPts = new int[TIER_ENUMS.length];
		int[] tierPossiblePts = new int[TIER_ENUMS.length];
		int hash = 1;
		boolean any = false;

		EnumComposition monsters = safeEnum(client, ENUM_MONSTER);

		for (int ti = 0; ti < TIER_ENUMS.length; ti++)
		{
			EnumComposition tierEnum = safeEnum(client, TIER_ENUMS[ti]);
			if (tierEnum == null)
			{
				continue;
			}
			for (int structId : tierEnum.getIntVals())
			{
				StructComposition s = client.getStructComposition(structId);
				if (s == null)
				{
					continue;
				}
				String name = s.getStringValue(P_NAME);
				if (name == null || name.isEmpty())
				{
					continue;
				}
				any = true;
				int id = s.getIntValue(P_ID);
				int typeId = s.getIntValue(P_TYPE);
				int bossId = s.getIntValue(P_MONSTER);
				String desc = s.getStringValue(P_DESC);
				String monster = monsters != null ? monsters.getStringValue(bossId) : null;
				String type = (typeId >= 1 && typeId < TYPE_NAMES.length) ? TYPE_NAMES[typeId] : null;

				JsonObject t = new JsonObject();
				t.addProperty("task_id", id);
				t.addProperty("name", name);
				t.addProperty("tier", TIER_NAMES[ti]);
				t.addProperty("points", ti + 1);
				if (type != null)
				{
					t.addProperty("type", type);
				}
				if (monster != null && !monster.isEmpty())
				{
					t.addProperty("monster", monster);
				}
				if (desc != null && !desc.isEmpty())
				{
					t.addProperty("description", desc);
				}
				tasks.add(t);
				int vi = id / 32, bit = id % 32;
				if (!readable(id))
				{
					unknown.add(id);
					hash = hash * 31 - id - 1;
					continue;   // not counted as done or not done
				}
				tierTotal[ti]++;
				tierPossiblePts[ti] += ti + 1;
				if ((client.getVarpValue(COMPLETION_VARPS[vi]) & (1 << bit)) != 0)
				{
					completed.add(id);
					tierDone[ti]++;
					tierEarnedPts[ti] += ti + 1;
					hash = hash * 31 + id;
				}
			}
		}

		if (!any)
		{
			return null;
		}
		if (unknown.size() > 0 && LOGGED_UNREADABLE.compareAndSet(false, true))
		{
			log.info("RuneTools: {} Combat Achievement task(s) past id {} can't be read yet; sent as unknown",
				unknown.size(), COMPLETION_VARPS.length * 32 - 1);
		}
		JsonObject tiers = new JsonObject();
		for (int i = 0; i < TIER_NAMES.length; i++)
		{
			tiers.addProperty(TIER_NAMES[i], tierDone[i]);
		}
		return new Snapshot(tasks, completed, unknown, tiers, hash, tierDone, tierTotal, tierEarnedPts, tierPossiblePts);
	}

	/** Whether a task's completion bit lies in a varp this build knows. */
	static boolean readable(int taskId)
	{
		return taskId >= 0 && taskId / 32 < COMPLETION_VARPS.length;
	}

	private static EnumComposition safeEnum(Client client, int id)
	{
		try
		{
			return client.getEnum(id);
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}
}

package com.runetools;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;
import java.util.function.Function;

/**
 * One place that writes the plugin's large config values (the setups cache, the unsynced-trade
 * queue). Writes are collected and flushed together a moment later on one executor thread, so a
 * burst of changes (a fill every tick, a pull after every setup edit) becomes one write of each key
 * instead of a rewrite of a big blob per change, and no OkHttp thread writes config itself.
 *
 * <p>Reads go through {@link #get} so a value that hasn't been flushed yet is still the one read.
 * {@link #flush} writes everything now (the plugin calls it when it is switched off). Thread-safe.
 */
final class DebouncedConfig
{
	private static final Object UNSET = new Object();

	private final BiConsumer<String, String> write;    // value null = unset the key
	private final Function<String, String> read;
	private final ScheduledExecutorService executor;   // null = write at once (tests)
	private final long delayMs;

	private final Map<String, Object> dirty = new LinkedHashMap<>();
	private final Map<String, Object> writing = new LinkedHashMap<>();   // taken by a flush, not yet written
	private ScheduledFuture<?> scheduled;
	private final Object flushLock = new Object();   // flushes run one at a time, so writes land in order

	DebouncedConfig(BiConsumer<String, String> write, Function<String, String> read,
		ScheduledExecutorService executor, long delayMs)
	{
		this.write = write;
		this.read = read;
		this.executor = executor;
		this.delayMs = delayMs;
	}

	/** Set {@code key} (null unsets it), written within {@code delayMs}. */
	void set(String key, String value)
	{
		synchronized (this)
		{
			dirty.put(key, value != null ? value : UNSET);
			if (executor != null)
			{
				if (scheduled == null || scheduled.isDone())
				{
					scheduled = executor.schedule(this::flush, delayMs, TimeUnit.MILLISECONDS);
				}
				return;
			}
		}
		flush();
	}

	/** The value of {@code key}, including one still waiting to be written. */
	String get(String key)
	{
		synchronized (this)
		{
			Object v = dirty.containsKey(key) ? dirty.get(key) : writing.get(key);
			if (v != null)
			{
				return v == UNSET ? null : (String) v;
			}
		}
		return read.apply(key);
	}

	/** Write everything waiting, now. */
	void flush()
	{
		synchronized (flushLock)
		{
			Map<String, Object> batch;
			synchronized (this)
			{
				if (dirty.isEmpty())
				{
					return;
				}
				batch = new LinkedHashMap<>(dirty);
				dirty.clear();
				writing.putAll(batch);
				scheduled = null;
			}
			for (Map.Entry<String, Object> en : batch.entrySet())
			{
				try
				{
					write.accept(en.getKey(), en.getValue() == UNSET ? null : (String) en.getValue());
				}
				catch (RuntimeException ignored)
				{
					// one bad write must not stop the rest
				}
				synchronized (this)
				{
					writing.remove(en.getKey(), en.getValue());
				}
			}
		}
	}
}

package com.runetools;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Backoff kept per endpoint, so one failing request (a 5xx on the Combat Achievements catalogue, a
 * 404 on an endpoint the server doesn't have) waits on its own instead of being retried every sweep
 * or every tick, while the endpoints that work carry on at the normal pace.
 *
 * <p>Each failure doubles that endpoint's wait, from {@code baseMs} up to {@code maxMs}; a success
 * clears it. The same payload failing with a server error {@link #GIVE_UP_AFTER} times in a row, over
 * at least {@link #GIVE_UP_MIN_MS}, is given up on: the caller stops sending exactly that payload, so
 * one body the server chokes on can't keep a queue stuck forever, while a server that is down for a
 * while (a deploy, a database restart) costs nothing. Plain logic with the clock passed in, so it can
 * be unit-tested; thread-safe.
 */
final class EndpointBackoff
{
	/** Server errors in a row on the same payload before the caller gives up on it. */
	static final int GIVE_UP_AFTER = 5;
	/** ...and how long they must have gone on for, from the first. */
	static final long GIVE_UP_MIN_MS = 30L * 60L * 1000L;

	private static final class State
	{
		int failures;
		long nextAt;
		long payload;
		int payloadErrors;
		long payloadSince;
	}

	private final Map<String, State> states = new ConcurrentHashMap<>();

	/** Whether {@code endpoint} may be tried at {@code now}. */
	boolean allowed(String endpoint, long now)
	{
		State s = states.get(endpoint);
		return s == null || now >= s.nextAt;
	}

	/** When {@code endpoint} may next be tried (0 when it may now). */
	long nextAt(String endpoint)
	{
		State s = states.get(endpoint);
		return s != null ? s.nextAt : 0L;
	}

	/**
	 * Record a failure and push the endpoint's next try back. {@code serverError} marks a failure that
	 * counts toward giving up on {@code payload} (see {@link SyncResponse#serverError}); a transport
	 * failure, an outage, a 404 or a rate limit never does. Returns true when the caller should give up
	 * on this exact payload.
	 */
	boolean failed(String endpoint, long payload, boolean serverError, long now, long baseMs, long maxMs)
	{
		State s = states.computeIfAbsent(endpoint, k -> new State());
		synchronized (s)
		{
			s.failures++;
			long wait = Math.min(maxMs, baseMs << Math.min(s.failures - 1, 10));
			s.nextAt = Math.max(s.nextAt, now + Math.max(baseMs, wait));
			if (!serverError)
			{
				return false;
			}
			if (s.payloadErrors > 0 && s.payload == payload)
			{
				s.payloadErrors++;
			}
			else
			{
				s.payload = payload;
				s.payloadErrors = 1;
				s.payloadSince = now;
			}
			if (s.payloadErrors >= GIVE_UP_AFTER && now - s.payloadSince >= GIVE_UP_MIN_MS)
			{
				s.payloadErrors = 0;
				return true;
			}
			return false;
		}
	}

	/** The endpoint answered properly: back to the normal pace. */
	void succeeded(String endpoint)
	{
		states.remove(endpoint);
	}

	/** Forget every endpoint's backoff (a new login, a new key). */
	void clear()
	{
		states.clear();
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Data;

/** A gear/inventory loadout authored on the RuneTools site and pulled by the plugin. */
@Data
public class GearSetup
{
	private long id;
	private String name;
	private String source;               // dps | bis | manual | imported
	private String style;                // melee | ranged | magic | null
	private boolean twoHanded;           // weapon is 2h -> shield slot is empty
	private Map<String, Integer> equipment = new LinkedHashMap<>();  // slot -> item id
	private List<GearSetupItem> inventory = new ArrayList<>();
	private List<GearSetupItem> runePouch = new ArrayList<>();
	private List<GearSetupItem> quiver = new ArrayList<>();
	private List<GearSetupItem> additional = new ArrayList<>();
	private int spellbook = -1;                                     // 0 std|1 ancient|2 lunar|3 arceuus|-1 none
	private Integer monsterId;
	private Set<Integer> fuzzy = new HashSet<>();                   // item ids matched by variation
	private String notes;
	private long updatedAt;
	// The site's setup collections this setup sits in (none for most setups). Read only: the site owns them.
	private List<SetupCollection> collections = new ArrayList<>();

	public boolean isFuzzy(int itemId)
	{
		return fuzzy != null && fuzzy.contains(itemId);
	}

	/** Flip fuzzy for an item id; returns the new state. */
	public boolean toggleFuzzy(int itemId)
	{
		if (fuzzy == null)
		{
			fuzzy = new HashSet<>();
		}
		if (fuzzy.remove(itemId))
		{
			return false;
		}
		fuzzy.add(itemId);
		return true;
	}

	/** Item ids the bank filter/layout should cover: equipment + inventory + rune pouch + quiver + additional. */
	public Collection<Integer> filterItemIds()
	{
		List<Integer> ids = new ArrayList<>();
		if (equipment != null)
		{
			for (Integer id : equipment.values())
			{
				if (id != null && id > 0)
				{
					ids.add(id);
				}
			}
		}
		addItemIds(ids, inventory);
		addItemIds(ids, runePouch);
		addItemIds(ids, quiver);
		addItemIds(ids, additional);
		return ids;
	}

	private static void addItemIds(List<Integer> ids, List<GearSetupItem> items)
	{
		if (items == null)
		{
			return;
		}
		for (GearSetupItem it : items)
		{
			if (it.getItemId() > 0)   // skip positional empty slots
			{
				ids.add(it.getItemId());
			}
		}
	}

	/**
	 * Same items as {@link #filterItemIds()} but aggregated to id -> total quantity (equipment counts
	 * as one each). Used for the "missing items / cost to complete" diff so a stack of 1000 runes is
	 * priced as 1000, and the same id appearing in two lists is counted once.
	 */
	public Map<Integer, Integer> filterItemCounts()
	{
		LinkedHashMap<Integer, Integer> counts = new LinkedHashMap<>();
		if (equipment != null)
		{
			for (Integer id : equipment.values())
			{
				if (id != null && id > 0)
				{
					counts.merge(id, 1, Integer::sum);
				}
			}
		}
		addItemCounts(counts, inventory);
		addItemCounts(counts, runePouch);
		addItemCounts(counts, quiver);
		addItemCounts(counts, additional);
		return counts;
	}

	private static void addItemCounts(Map<Integer, Integer> counts, List<GearSetupItem> items)
	{
		if (items == null)
		{
			return;
		}
		for (GearSetupItem it : items)
		{
			if (it.getItemId() > 0)   // skip positional empty slots
			{
				counts.merge(it.getItemId(), Math.max(1, it.getQty()), Integer::sum);
			}
		}
	}

	/** Upper bound on any single item list from an (untrusted) setup, to cap Swing/render work. */
	private static final int MAX_ITEMS = 500;

	static GearSetup fromJson(JsonObject o)
	{
		GearSetup s = new GearSetup();
		s.id = o.has("id") && !o.get("id").isJsonNull() ? asLong(o.get("id"), 0L) : 0L;
		s.name = str(o, "name");
		s.source = str(o, "source");
		s.style = str(o, "style");
		s.twoHanded = o.has("two_handed") && !o.get("two_handed").isJsonNull() && asBool(o.get("two_handed"));
		s.updatedAt = o.has("updated_at") && !o.get("updated_at").isJsonNull() ? asEpoch(o.get("updated_at")) : 0L;

		JsonElement eq = o.get("equipment");
		if (eq != null && eq.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : eq.getAsJsonObject().entrySet())
			{
				if (s.equipment.size() >= MAX_ITEMS)
				{
					break;
				}
				if (!e.getValue().isJsonNull())
				{
					int id = asInt(e.getValue(), 0);
					if (id > 0)
					{
						s.equipment.put(e.getKey(), id);
					}
				}
			}
		}
		s.inventory = items(o, "inventory");
		s.runePouch = items(o, "rune_pouch");
		s.quiver = items(o, "quiver");
		s.additional = items(o, "additional");
		s.spellbook = o.has("spellbook") && !o.get("spellbook").isJsonNull() ? asInt(o.get("spellbook"), -1) : -1;
		s.monsterId = o.has("monster_id") && !o.get("monster_id").isJsonNull() ? asInt(o.get("monster_id"), 0) : null;
		s.fuzzy = new HashSet<>();
		JsonElement fz = o.get("fuzzy");
		if (fz != null && fz.isJsonArray())
		{
			for (JsonElement e : fz.getAsJsonArray())
			{
				if (!e.isJsonNull() && s.fuzzy.size() < MAX_ITEMS)
				{
					int id = asInt(e, 0);
					if (id > 0)
					{
						s.fuzzy.add(id);
					}
				}
			}
		}
		s.notes = str(o, "notes");
		s.collections = SetupCollection.parse(o);
		return s;
	}

	/** Serialize for POST/PUT to the site (matches the /api/setups body). */
	JsonObject toJson()
	{
		JsonObject o = new JsonObject();
		o.addProperty("name", name != null ? name : "Setup");
		o.addProperty("source", source != null ? source : "manual");
		if (style != null)
		{
			o.addProperty("style", style);
		}
		if (monsterId != null)
		{
			o.addProperty("monster_id", monsterId);
		}
		if (spellbook >= 0)
		{
			o.addProperty("spellbook", spellbook);
		}
		JsonObject eq = new JsonObject();
		if (equipment != null)
		{
			for (Map.Entry<String, Integer> e : equipment.entrySet())
			{
				if (e.getValue() != null && e.getValue() > 0)
				{
					eq.addProperty(e.getKey(), e.getValue());
				}
			}
		}
		o.add("equipment", eq);
		o.add("inventory", itemsToJson(inventory));
		o.add("rune_pouch", itemsToJson(runePouch));
		o.add("quiver", itemsToJson(quiver));
		o.add("additional", itemsToJson(additional));
		JsonArray fzArr = new JsonArray();
		if (fuzzy != null)
		{
			for (int id : fuzzy)
			{
				fzArr.add(id);
			}
		}
		o.add("fuzzy", fzArr);
		if (notes != null)
		{
			o.addProperty("notes", notes);
		}
		return o;
	}

	private static JsonArray itemsToJson(List<GearSetupItem> list)
	{
		JsonArray arr = new JsonArray();
		if (list != null)
		{
			for (GearSetupItem it : list)
			{
				JsonObject j = new JsonObject();
				j.addProperty("item_id", it.getItemId());
				j.addProperty("qty", it.getQty());
				arr.add(j);
			}
		}
		return arr;
	}

	private static List<GearSetupItem> items(JsonObject o, String key)
	{
		List<GearSetupItem> out = new ArrayList<>();
		JsonElement el = o.get(key);
		if (el != null && el.isJsonArray())
		{
			for (JsonElement e : el.getAsJsonArray())
			{
				if (out.size() >= MAX_ITEMS)
				{
					break;
				}
				if (!e.isJsonObject())
				{
					continue;
				}
				JsonObject j = e.getAsJsonObject();
				if (!j.has("item_id") || j.get("item_id").isJsonNull())
				{
					continue;   // no item id
				}
				int itemId = asInt(j.get("item_id"), 0);
				int qty = j.has("qty") && !j.get("qty").isJsonNull() ? asInt(j.get("qty"), 1) : 1;
				out.add(new GearSetupItem(itemId, qty));
			}
		}
		return out;
	}

	private static String str(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		try
		{
			return e.getAsString();   // a nested object/array would throw - treat as absent
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	private static long asLong(JsonElement e, long fallback)
	{
		try
		{
			return e.getAsLong();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	private static long asEpoch(JsonElement e)
	{
		try
		{
			return (long) e.getAsDouble();
		}
		catch (RuntimeException ex)
		{
			return 0L;
		}
	}

	private static boolean asBool(JsonElement e)
	{
		try
		{
			return e.getAsBoolean();
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}

	private static int asInt(JsonElement e, int fallback)
	{
		try
		{
			return e.getAsInt();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}
}

package com.runetools;

import lombok.Value;

/** One item in a setup's inventory / rune pouch / quiver. */
@Value
public class GearSetupItem
{
	int itemId;
	int qty;
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure data converter between a RuneTools {@link GearSetup} and the RuneLite
 * <a href="https://github.com/dillydill123/inventory-setups">Inventory Setups</a> plugin's
 * Export / Import STRING format.
 *
 * <p>Inventory Setups' "Export setup" button copies (and "Import setup" pastes) the <b>plain,
 * un-encoded JSON</b> of a single {@code InventorySetupPortable}. That wrapper is:
 * <pre>
 *   { "setup": &lt;InventorySetupSerializable&gt;, "layout": &lt;int[]&gt; }
 * </pre>
 * Both classes are Lombok {@code @Value} types with <b>no</b> {@code @SerializedName}, so Gson keys
 * are the raw (short) Java field names. The relevant setup keys are:
 * <pre>
 *   inv  List&lt;item&gt;   inventory   (28 fixed slots, dummy = null element)
 *   eq   List&lt;item&gt;   equipment   (14 fixed slots, dummy = null element)
 *   rp   List&lt;item&gt;   rune pouch  (nullable)
 *   bp   List&lt;item&gt;   bolt pouch  (nullable)
 *   qv   List&lt;item&gt;   quiver      (nullable)
 *   afi  Map&lt;Integer,item&gt; additional filtered items (nullable)
 *   name String        setup name
 *   notes String       notes (nullable)
 *   hc   Color         highlight color   (RuneLite serializes java.awt.Color as its int RGB "value")
 *   hd,dc,fb,uh,fv     misc flags/colors (all nullable -> omitted here so IS uses defaults)
 *   sb   Integer       spellbook (null = 0 standard; 1 ancient, 2 lunar, 3 arceuus)
 *   iId  Integer       icon id (nullable)
 *   ao   String        attack option (nullable)
 * </pre>
 * An item element is {@code InventorySetupItemSerializable}:
 * <pre>
 *   id  int      item id (-1 for a dummy, but dummies serialize as a null list element)
 *   q   Integer  quantity (null = 1)
 *   f   Boolean  fuzzy   (null = false)
 *   sc  enum     stack compare (null = None)
 * </pre>
 * An empty slot is a {@code null} element in the {@code inv}/{@code eq} list (the plugin turns a
 * null element back into its "dummy item", id -1, quantity 0).
 *
 * <p>Equipment index order is RuneLite's {@code EquipmentInventorySlot} (14 slots):
 * 0 head, 1 cape, 2 amulet(neck), 3 weapon, 4 body, 5 shield, 6 arms, 7 legs, 8 hair, 9 gloves(hands),
 * 10 boots(feet), 11 jaw, 12 ring, 13 ammo. RuneTools only uses 11 of these; the rest stay empty.
 *
 * <p>This class makes no RuneLite client / UI calls, so it is unit-testable headless.
 */
public final class InventorySetupsBridge
{
	/** Number of equipment slots Inventory Setups stores (EquipmentInventorySlot order). */
	static final int NUM_EQUIPMENT_ITEMS = 14;
	/** Number of inventory slots Inventory Setups stores. */
	static final int NUM_INVENTORY_ITEMS = 28;

	/** RuneTools slot name -> EquipmentInventorySlot index used by Inventory Setups. */
	static final Map<String, Integer> EQUIP_INDEX;

	static
	{
		Map<String, Integer> m = new LinkedHashMap<>();
		m.put("head", 0);
		m.put("cape", 1);
		m.put("neck", 2);    // AMULET
		m.put("weapon", 3);
		m.put("body", 4);
		m.put("shield", 5);
		m.put("legs", 7);
		m.put("hands", 9);   // GLOVES
		m.put("feet", 10);   // BOOTS
		m.put("ring", 12);
		m.put("ammo", 13);
		EQUIP_INDEX = m;
	}

	/** Inverse of {@link #EQUIP_INDEX}: equipment index -> RuneTools slot name. */
	private static final Map<Integer, String> INDEX_EQUIP;

	static
	{
		Map<Integer, String> m = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : EQUIP_INDEX.entrySet())
		{
			m.put(e.getValue(), e.getKey());
		}
		INDEX_EQUIP = m;
	}

	private InventorySetupsBridge()
	{
	}

	// ------------------------------------------------------------------ export (RuneTools -> IS)

	/**
	 * Produce the exact string Inventory Setups' "Import setup" accepts for one setup: the plain JSON
	 * of an {@code InventorySetupPortable} wrapping this loadout. Never throws; returns {@code null}
	 * only if {@code s} is null.
	 */
	public static String toImportString(GearSetup s)
	{
		if (s == null)
		{
			return null;
		}

		JsonObject setup = new JsonObject();

		// name (required non-null on import)
		setup.addProperty("name", s.getName() != null ? s.getName() : "Setup");

		// equipment -> 14-slot list, empty slots are JSON null elements
		JsonArray eq = new JsonArray();
		Map<String, Integer> equipment = s.getEquipment();
		String[] byIndex = new String[NUM_EQUIPMENT_ITEMS];
		for (Map.Entry<Integer, String> e : INDEX_EQUIP.entrySet())
		{
			byIndex[e.getKey()] = e.getValue();
		}
		for (int i = 0; i < NUM_EQUIPMENT_ITEMS; i++)
		{
			String slot = byIndex[i];
			Integer id = (slot != null && equipment != null) ? equipment.get(slot) : null;
			eq.add(itemElement(id, 1, s, id));
		}
		setup.add("eq", eq);

		// inventory -> fixed 28-slot list, preserving positions/empties
		setup.add("inv", itemsList(s.getInventory(), NUM_INVENTORY_ITEMS, s));

		// rune pouch / quiver (nullable lists; omit when empty so IS uses "no pouch")
		JsonArray rp = itemsListLoose(s.getRunePouch(), s);
		if (rp != null)
		{
			setup.add("rp", rp);
		}
		JsonArray qv = itemsListLoose(s.getQuiver(), s);
		if (qv != null)
		{
			setup.add("qv", qv);
		}

		// additional filtered items -> Map<Integer id, item>
		JsonObject afi = additionalMap(s.getAdditional(), s);
		if (afi != null)
		{
			setup.add("afi", afi);
		}

		// spellbook: sb null means standard(0). RuneTools -1 (none) or 0 (standard) => omit.
		int sb = s.getSpellbook();
		if (sb > 0)
		{
			setup.addProperty("sb", sb);
		}

		// notes
		if (s.getNotes() != null && !s.getNotes().isEmpty())
		{
			setup.addProperty("notes", s.getNotes());
		}

		JsonObject portable = new JsonObject();
		portable.add("setup", setup);
		// layout is required non-null on import; an empty array is valid (IS regenerates a layout).
		portable.add("layout", new JsonArray());

		// toString(), not a Gson instance: the Plugin Hub blocks `new Gson()`, and this tree is built
		// by hand out of JsonObject/JsonArray so its own serialisation is all we need.
		return portable.toString();
	}

	/**
	 * Every setup as one file Inventory Setups' "Mass Import Setups" reads: a JSON array of the same
	 * objects its single-setup Import takes.
	 */
	public static String toMassExport(List<GearSetup> setups)
	{
		StringBuilder sb = new StringBuilder("[");
		int n = 0;
		for (GearSetup s : setups)
		{
			String one = toImportString(s);
			if (one == null)
			{
				continue;
			}
			if (n++ > 0)
			{
				sb.append(',');
			}
			sb.append(one);
		}
		return sb.append(']').toString();
	}

	/** One item list element: JSON null for an empty/absent item, else {id,q?,f?}. */
	private static JsonElement itemElement(Integer id, int qty, GearSetup s, Integer fuzzyId)
	{
		if (id == null || id <= 0)
		{
			return JsonNull.INSTANCE;
		}
		JsonObject o = new JsonObject();
		o.addProperty("id", id);
		if (qty != 1)
		{
			o.addProperty("q", qty);
		}
		if (s != null && fuzzyId != null && s.isFuzzy(fuzzyId))
		{
			o.addProperty("f", true);
		}
		return o;
	}

	/** Fixed-length list (inv/eq): positions preserved, gaps and overflow become null elements. */
	private static JsonArray itemsList(List<GearSetupItem> items, int size, GearSetup s)
	{
		JsonArray arr = new JsonArray();
		for (int i = 0; i < size; i++)
		{
			GearSetupItem it = (items != null && i < items.size()) ? items.get(i) : null;
			if (it == null || it.getItemId() <= 0)
			{
				arr.add(JsonNull.INSTANCE);
			}
			else
			{
				arr.add(itemElement(it.getItemId(), it.getQty(), s, it.getItemId()));
			}
		}
		return arr;
	}

	/** Variable-length list (rp/qv): null when there is nothing to store. */
	private static JsonArray itemsListLoose(List<GearSetupItem> items, GearSetup s)
	{
		if (items == null || items.isEmpty())
		{
			return null;
		}
		boolean any = false;
		JsonArray arr = new JsonArray();
		for (GearSetupItem it : items)
		{
			if (it != null && it.getItemId() > 0)
			{
				arr.add(itemElement(it.getItemId(), it.getQty(), s, it.getItemId()));
				any = true;
			}
			else
			{
				arr.add(JsonNull.INSTANCE);
			}
		}
		return any ? arr : null;
	}

	/** additional filtered items map: id -> item, keyed by string item id (Gson keys map ints as strings). */
	private static JsonObject additionalMap(List<GearSetupItem> items, GearSetup s)
	{
		if (items == null || items.isEmpty())
		{
			return null;
		}
		JsonObject o = new JsonObject();
		for (GearSetupItem it : items)
		{
			if (it != null && it.getItemId() > 0)
			{
				o.add(String.valueOf(it.getItemId()), itemElement(it.getItemId(), it.getQty(), s, it.getItemId()));
			}
		}
		return o.size() > 0 ? o : null;
	}

	// ------------------------------------------------------------------ import (IS -> RuneTools)

	/**
	 * Parse an Inventory Setups export string into a RuneTools {@link GearSetup} (reverse mapping).
	 * Defensive: returns {@code null} (never throws) on any malformed / empty / non-matching input.
	 */
	public static GearSetup fromExportString(String exportString)
	{
		if (exportString == null || exportString.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = new JsonParser().parse(exportString);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject portable = root.getAsJsonObject();

			// Accept either the portable wrapper {setup:..} or a bare setup object.
			JsonObject setup;
			if (portable.has("setup") && portable.get("setup").isJsonObject())
			{
				setup = portable.getAsJsonObject("setup");
			}
			else if (portable.has("eq") || portable.has("inv"))
			{
				setup = portable;
			}
			else
			{
				return null;
			}

			GearSetup out = new GearSetup();
			out.setSource("imported");
			out.setName(strOr(setup, "name", "Imported setup"));
			out.setNotes(str(setup, "notes"));

			// spellbook (sb): null/absent means standard (0)
			int sb = 0;
			JsonElement sbEl = setup.get("sb");
			if (sbEl != null && !sbEl.isJsonNull())
			{
				sb = asInt(sbEl, 0);
			}
			out.setSpellbook(sb);

			// equipment: 14-slot list -> {slotName -> itemId} for the slots RuneTools knows
			Map<String, Integer> equipment = new LinkedHashMap<>();
			JsonArray eq = arr(setup, "eq");
			if (eq != null)
			{
				for (int i = 0; i < eq.size(); i++)
				{
					String slot = INDEX_EQUIP.get(i);
					if (slot == null)
					{
						continue;   // arms/hair/jaw etc. have no RuneTools slot
					}
					Integer id = itemId(eq.get(i));
					if (id != null && id > 0)
					{
						equipment.put(slot, id);
						markFuzzy(out, eq.get(i), id);
					}
				}
			}
			out.setEquipment(equipment);
			out.setTwoHanded(!equipment.containsKey("shield") && equipment.containsKey("weapon"));

			// inventory: preserve positions (empty slots become id 0 placeholders)
			out.setInventory(readItems(setup, "inv", out, true));
			out.setRunePouch(readItems(setup, "rp", out, false));
			out.setQuiver(readItems(setup, "qv", out, false));
			out.setAdditional(readAfi(setup, out));

			return out;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	/** Read an inv/eq/rp/qv list. When {@code keepEmpty}, empty slots are kept as id-0 placeholders. */
	private static List<GearSetupItem> readItems(JsonObject setup, String key, GearSetup out, boolean keepEmpty)
	{
		List<GearSetupItem> list = new ArrayList<>();
		JsonArray a = arr(setup, key);
		if (a == null)
		{
			return list;
		}
		for (JsonElement el : a)
		{
			Integer id = itemId(el);
			if (id != null && id > 0)
			{
				int qty = qty(el);
				list.add(new GearSetupItem(id, qty));
				markFuzzy(out, el, id);
			}
			else if (keepEmpty)
			{
				list.add(new GearSetupItem(0, 0));   // positional empty slot
			}
		}
		// trim trailing empties for inventory so a mostly-empty inv doesn't carry 28 placeholders
		if (keepEmpty)
		{
			int last = -1;
			for (int i = 0; i < list.size(); i++)
			{
				if (list.get(i).getItemId() > 0)
				{
					last = i;
				}
			}
			if (last < 0)
			{
				return new ArrayList<>();
			}
			return new ArrayList<>(list.subList(0, last + 1));
		}
		return list;
	}

	/** additional filtered items: Map<Integer id, item> -> list of items. */
	private static List<GearSetupItem> readAfi(JsonObject setup, GearSetup out)
	{
		List<GearSetupItem> list = new ArrayList<>();
		JsonElement el = setup.get("afi");
		if (el == null || !el.isJsonObject())
		{
			return list;
		}
		for (Map.Entry<String, JsonElement> e : el.getAsJsonObject().entrySet())
		{
			Integer id = itemId(e.getValue());
			if (id == null || id <= 0)
			{
				// key is the item id; fall back to it when the value has no explicit id
				try
				{
					id = Integer.parseInt(e.getKey());
				}
				catch (NumberFormatException nfe)
				{
					continue;
				}
			}
			if (id != null && id > 0)
			{
				list.add(new GearSetupItem(id, qty(e.getValue())));
				markFuzzy(out, e.getValue(), id);
			}
		}
		return list;
	}

	private static void markFuzzy(GearSetup out, JsonElement el, int id)
	{
		if (el != null && el.isJsonObject())
		{
			JsonElement f = el.getAsJsonObject().get("f");
			if (f != null && !f.isJsonNull() && asBool(f))
			{
				if (out.getFuzzy() == null)
				{
					out.setFuzzy(new java.util.HashSet<>());
				}
				out.getFuzzy().add(id);
			}
		}
	}

	// ------------------------------------------------------------------ small json helpers

	/** Item id from a list element (null element => absent). */
	private static Integer itemId(JsonElement el)
	{
		if (el == null || el.isJsonNull() || !el.isJsonObject())
		{
			return null;
		}
		JsonElement idEl = el.getAsJsonObject().get("id");
		if (idEl == null || idEl.isJsonNull())
		{
			return null;
		}
		return asInt(idEl, -1);
	}

	private static int qty(JsonElement el)
	{
		if (el != null && el.isJsonObject())
		{
			JsonElement q = el.getAsJsonObject().get("q");
			if (q != null && !q.isJsonNull())
			{
				int v = asInt(q, 1);
				return v > 0 ? v : 1;
			}
		}
		return 1;   // q null = 1
	}

	private static JsonArray arr(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return (e != null && e.isJsonArray()) ? e.getAsJsonArray() : null;
	}

	private static String str(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		try
		{
			return e.getAsString();
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	private static String strOr(JsonObject o, String key, String fallback)
	{
		String v = str(o, key);
		return v != null ? v : fallback;
	}

	private static int asInt(JsonElement e, int fallback)
	{
		try
		{
			return e.getAsInt();
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	private static boolean asBool(JsonElement e)
	{
		try
		{
			return e.getAsBoolean();
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}
}

package com.runetools;

import java.awt.GridLayout;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * A plain grid of {@link SlotLabel}s (e.g. Inventory 7x4, Rune pouch 1x4). The panel wraps it with a
 * centred caption; this class is just the fixed slot matrix. The 1px gaps show the darker grid
 * background, so each slot reads as its own box - the way Inventory Setups looks.
 */
final class ItemGrid extends JPanel
{
	private final SlotLabel[] slots;

	ItemGrid(int rows, int cols)
	{
		super(new GridLayout(rows, cols, 1, 1));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		slots = new SlotLabel[rows * cols];
		for (int i = 0; i < slots.length; i++)
		{
			slots[i] = new SlotLabel(ColorScheme.DARKER_GRAY_COLOR);
			add(slots[i]);
		}
	}

	SlotLabel slot(int i)
	{
		return (i >= 0 && i < slots.length) ? slots[i] : null;
	}

	int count()
	{
		return slots.length;
	}

	void clearAll()
	{
		for (SlotLabel s : slots)
		{
			s.clear();
		}
	}
}

package com.runetools;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Snapshots the player's live loadout (worn gear, inventory, rune pouch, quiver, spellbook) into a
 * {@link GearSetup}. All reads touch varbits/varps/enums/containers, so {@link #snapshot()} MUST be
 * called on the client thread.
 */
class LoadoutReader
{
	private static final Map<EquipmentInventorySlot, String> SLOT_KEY = new EnumMap<>(EquipmentInventorySlot.class);

	static
	{
		SLOT_KEY.put(EquipmentInventorySlot.HEAD, "head");
		SLOT_KEY.put(EquipmentInventorySlot.CAPE, "cape");
		SLOT_KEY.put(EquipmentInventorySlot.AMULET, "neck");
		SLOT_KEY.put(EquipmentInventorySlot.WEAPON, "weapon");
		SLOT_KEY.put(EquipmentInventorySlot.BODY, "body");
		SLOT_KEY.put(EquipmentInventorySlot.SHIELD, "shield");
		SLOT_KEY.put(EquipmentInventorySlot.LEGS, "legs");
		SLOT_KEY.put(EquipmentInventorySlot.GLOVES, "hands");
		SLOT_KEY.put(EquipmentInventorySlot.BOOTS, "feet");
		SLOT_KEY.put(EquipmentInventorySlot.RING, "ring");
		SLOT_KEY.put(EquipmentInventorySlot.AMMO, "ammo");
	}

	private static final int[] RP_TYPE = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4,
	};
	private static final int[] RP_QTY = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4,
	};

	// The pouches whose runes the RUNE_POUCH varbits describe, and the items whose ammo slot the
	// Dizana's quiver varps describe. Those vars keep their contents when the item is banked, so they
	// are only read into a setup when one of these is actually carried or worn.
	static final Set<Integer> RUNE_POUCHES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER)));
	static final Set<Integer> QUIVERS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.DIZANAS_QUIVER_UNCHARGED, ItemID.DIZANAS_QUIVER_UNCHARGED_TROUVER,
		ItemID.DIZANAS_QUIVER_CHARGED, ItemID.DIZANAS_QUIVER_CHARGED_TROUVER,
		ItemID.DIZANAS_QUIVER_INFINITE, ItemID.DIZANAS_QUIVER_INFINITE_TROUVER,
		ItemID.SKILLCAPE_MAX_DIZANAS, ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER)));

	private final Client client;
	private final ItemManager itemManager;

	LoadoutReader(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Snapshot the current loadout. Client thread only. */
	GearSetup snapshot()
	{
		GearSetup s = new GearSetup();
		s.setSource("manual");

		// (1) worn equipment
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Map<String, Integer> eq = new LinkedHashMap<>();
		Integer weaponId = null;
		if (worn != null)
		{
			Item[] w = worn.getItems();
			for (Map.Entry<EquipmentInventorySlot, String> e : SLOT_KEY.entrySet())
			{
				int idx = e.getKey().getSlotIdx();
				if (idx >= 0 && idx < w.length && w[idx].getId() > 0)
				{
					eq.put(e.getValue(), w[idx].getId());
					if (e.getKey() == EquipmentInventorySlot.WEAPON)
					{
						weaponId = w[idx].getId();
					}
				}
			}
		}
		// (2) 2h weapon -> no shield
		if (weaponId != null)
		{
			ItemStats st = itemManager.getItemStats(weaponId);
			if (st != null && st.getEquipment() != null && st.getEquipment().isTwoHanded())
			{
				eq.remove("shield");
				s.setTwoHanded(true);
			}
		}
		s.setEquipment(eq);

		// (3) inventory (positional: preserve the real slot layout, empty slots as blanks, trim the tail)
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		List<GearSetupItem> invList = new ArrayList<>();
		if (inv != null)
		{
			for (Item it : inv.getItems())
			{
				invList.add(it.getId() > 0
					? new GearSetupItem(it.getId(), Math.max(1, it.getQuantity()))
					: new GearSetupItem(0, 0));
			}
			while (!invList.isEmpty() && invList.get(invList.size() - 1).getItemId() <= 0)
			{
				invList.remove(invList.size() - 1);
			}
		}
		s.setInventory(invList);

		// (4) rune pouch (scan all 4 slots; empty slots have type 0), only while a pouch is carried
		List<GearSetupItem> runes = new ArrayList<>();
		EnumComposition runeEnum = holds(inv, RUNE_POUCHES) ? client.getEnum(EnumID.RUNEPOUCH_RUNE) : null;
		if (runeEnum != null)
		{
			for (int i = 0; i < RP_TYPE.length; i++)
			{
				int type = client.getVarbitValue(RP_TYPE[i]);
				if (type == 0)
				{
					continue;
				}
				int runeId = runeEnum.getIntValue(type);
				if (runeId > 0)
				{
					runes.add(new GearSetupItem(runeId, Math.max(1, client.getVarbitValue(RP_QTY[i]))));
				}
			}
		}
		s.setRunePouch(runes);

		// (5) Dizana's quiver ammo, only while the quiver (or its max cape) is worn or carried
		List<GearSetupItem> quiver = new ArrayList<>();
		if (holds(worn, QUIVERS) || holds(inv, QUIVERS))
		{
			int ammoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
			int ammoQty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
			if (ammoId > 0 && ammoQty > 0)
			{
				quiver.add(new GearSetupItem(ammoId, ammoQty));
			}
		}
		s.setQuiver(quiver);

		// (6) spellbook  0 std | 1 ancient | 2 lunar | 3 arceuus
		int sb = client.getVarbitValue(VarbitID.SPELLBOOK);
		s.setSpellbook(sb >= 0 && sb <= 3 ? sb : -1);

		return s;
	}

	/** Whether the container holds any of {@code ids}. */
	private static boolean holds(ItemContainer c, Set<Integer> ids)
	{
		if (c == null)
		{
			return false;
		}
		for (Item it : c.getItems())
		{
			if (it != null && ids.contains(it.getId()))
			{
				return true;
			}
		}
		return false;
	}
}

package com.runetools;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns the stream of {@code GrandExchangeOfferChanged}-derived offers into completed-fill
 * {@link Trade}s:
 *
 * <ul>
 *   <li>keep a per-slot {@link SavedOffer} baseline;</li>
 *   <li>emit a trade only for a POSITIVE (quantitySold, spent) delta, so multi-tick partial
 *       fills are each counted exactly once and never re-counted;</li>
 *   <li>a slot with no baseline yet (fresh start / first sight) is adopted silently - we can't
 *       count fills that happened before we were tracking;</li>
 *   <li>a changed item/price/total is treated as a fresh offer (desync guard);</li>
 *   <li>EMPTY clears the slot's baseline. The caller drops the login-time EMPTY burst.</li>
 * </ul>
 *
 * <p>Baselines are held <b>in memory</b> (a fresh array per plugin start), deliberately NOT in the
 * RSProfile config: round-tripping this custom object through {@code ConfigManager} proved
 * unreliable - the read came back {@code null}, so every fill looked like a fresh baseline and no
 * trade was ever emitted. The only cost of in-memory state is that baselines don't survive a client
 * restart (an offer already partly filled before startup is adopted, not back-counted), which is an
 * acceptable trade for correct, reliable capture.
 */
class OfferTracker
{
	private static final int SLOTS = 8;

	private final SavedOffer[] baselines = new SavedOffer[SLOTS];

	static boolean isBuy(GrandExchangeOfferState s)
	{
		return s == GrandExchangeOfferState.BUYING
			|| s == GrandExchangeOfferState.BOUGHT
			|| s == GrandExchangeOfferState.CANCELLED_BUY;
	}

	private SavedOffer get(int slot)
	{
		return (slot >= 0 && slot < SLOTS) ? baselines[slot] : null;
	}

	private void set(int slot, SavedOffer o)
	{
		if (slot >= 0 && slot < SLOTS)
		{
			baselines[slot] = o;
		}
	}

	/**
	 * @return a Trade for a newly-filled quantity, or {@code null} if this event yields none.
	 *         The caller must drop the login-time EMPTY burst (state==EMPTY while not LOGGED_IN)
	 *         before calling this.
	 */
	Trade process(int slot, GrandExchangeOffer offer, String rsn, String accountHash)
	{
		GrandExchangeOfferState state = offer.getState();

		if (state == GrandExchangeOfferState.EMPTY)
		{
			set(slot, null);   // slot collected/cancelled in-game
			return null;
		}

		SavedOffer cur = SavedOffer.from(offer);
		SavedOffer prev = get(slot);

		if (prev == null)
		{
			set(slot, cur);    // fresh baseline; emit nothing (can't count pre-tracking fills)
			return null;
		}

		boolean newOffer = prev.getItemId() != cur.getItemId()
			|| prev.getPrice() != cur.getPrice()
			|| prev.getTotalQuantity() != cur.getTotalQuantity();

		int prevQty = newOffer ? 0 : prev.getQuantitySold();
		long prevSpent = newOffer ? 0 : prev.getSpent();
		int qtyDiff = cur.getQuantitySold() - prevQty;
		long spentDiff = cur.getSpent() - prevSpent;

		set(slot, cur);

		if (qtyDiff <= 0 || spentDiff <= 0)
		{
			return null;
		}

		// Exact integer half-up rounding (both diffs are > 0 here): avoids float precision loss.
		long unitPrice = (spentDiff + qtyDiff / 2) / qtyDiff;
		String side = isBuy(state) ? "buy" : "sell";
		String extId = slot + ":" + cur.getItemId() + ":" + side + ":" + cur.getQuantitySold();
		return new Trade(cur.getItemId(), side, qtyDiff, unitPrice, System.currentTimeMillis(),
			extId, rsn, accountHash);
	}
}

package com.runetools;

/**
 * This build's version, sent on every request so the site can tell which plugin it is talking to
 * (and, through the remote config's {@code min_version}, pause an old one's writes). A unit test
 * keeps {@link #VERSION} equal to the version in runelite-plugin.properties.
 */
final class PluginVersion
{
	/** Must equal {@code version} in runelite-plugin.properties. */
	static final String VERSION = "1.0.0";

	/**
	 * The request and response shapes this build speaks. Bumped only when the plugin starts relying
	 * on a different shape, so the server can keep answering older builds the way they expect.
	 */
	static final int API_LEVEL = 1;

	static final String HEADER_VERSION = "X-RuneTools-Plugin";
	static final String HEADER_API = "X-RuneTools-Api";

	private PluginVersion()
	{
	}

	/**
	 * Compare two dotted numeric versions ("1.2.10" against "1.2.9"). Missing parts count as 0 and a
	 * part that isn't a number counts as 0, so a garbled value can never throw.
	 */
	static int compare(String a, String b)
	{
		String[] pa = a != null ? a.trim().split("\\.") : new String[0];
		String[] pb = b != null ? b.trim().split("\\.") : new String[0];
		int n = Math.max(pa.length, pb.length);
		for (int i = 0; i < n; i++)
		{
			long x = i < pa.length ? part(pa[i]) : 0;
			long y = i < pb.length ? part(pb[i]) : 0;
			if (x != y)
			{
				return x < y ? -1 : 1;
			}
		}
		return 0;
	}

	private static long part(String s)
	{
		int end = 0;
		while (end < s.length() && end < 9 && Character.isDigit(s.charAt(end)))
		{
			end++;
		}
		return end == 0 ? 0 : Long.parseLong(s.substring(0, end));
	}
}

package com.runetools;

/**
 * Decides when the background loop next asks the server for changes made on the website: gear
 * setups and imported bank layouts. Those are ETag polls, so "nothing changed" is a cheap 304, but
 * at a fixed 20 seconds they still came to two requests every 20 seconds for as long as a character
 * stayed logged in, about 8,600 a day for a client left idle.
 *
 * <p>Instead the gap between polls starts at {@link #MIN_INTERVAL_MS} and doubles after every poll,
 * up to {@link #MAX_INTERVAL_MS}. A poll that finds something new on the site puts it back to the
 * short gap, since more edits usually follow, and so does a new login ({@link #reset}). Anything
 * that suggests the player is about to use the synced data (opening the side panel, opening the
 * bank) asks for a poll right away through {@link #pollSoon}, but never sooner than the gap given
 * there after the previous poll, so repeatedly opening the panel or the bank can't turn into a
 * request storm.
 *
 * <p>Plain logic with an injected clock value, so it can be unit-tested; thread-safe, since the
 * scheduler thread, the client thread, the Swing thread and OkHttp callbacks all reach it.
 */
final class PollSchedule
{
	/** Gap after a poll that found changes, or after the player showed up. */
	static final long MIN_INTERVAL_MS = 30_000L;
	/** Ceiling for an idle client: one poll every five minutes. */
	static final long MAX_INTERVAL_MS = 5L * 60L * 1000L;
	/** The closest two polls may be, even when the player asks for one (e.g. opens the side panel). */
	static final long PANEL_GAP_MS = 10_000L;
	/** The closest a bank opening can pull a poll in; players bank far more often than they need a poll. */
	static final long BANK_GAP_MS = 60_000L;

	private long nextAt;                  // first moment the next poll may start; 0 = due now
	private long lastStartedAt = -1;      // -1 = never polled since the last reset
	private long minMs = MIN_INTERVAL_MS;
	private long maxMs = MAX_INTERVAL_MS;
	private long interval = MIN_INTERVAL_MS;

	/**
	 * Use these bounds instead of the built-in ones (the site's remote config may lengthen them; it
	 * never shortens them, see {@link RemoteConfig#limitMs}).
	 */
	synchronized void setBounds(long minIntervalMs, long maxIntervalMs)
	{
		minMs = Math.max(MIN_INTERVAL_MS, minIntervalMs);
		maxMs = Math.max(minMs, Math.max(MAX_INTERVAL_MS, maxIntervalMs));
		interval = Math.max(minMs, Math.min(interval, maxMs));
	}

	/**
	 * If a poll is due at {@code now}, record that it is starting and return true; the caller then
	 * sends it. Until an answer says otherwise, the poll is assumed to find nothing new, so the gap
	 * to the following one has already doubled.
	 */
	synchronized boolean tryStart(long now)
	{
		if (now < nextAt)
		{
			return false;
		}
		lastStartedAt = now;
		nextAt = now + interval;
		interval = Math.min(maxMs, interval * 2);
		return true;
	}

	/** A poll found something changed on the site: keep polling at the short gap for a while. */
	synchronized void onChanged()
	{
		interval = minMs;
		if (lastStartedAt >= 0)
		{
			nextAt = Math.min(nextAt, lastStartedAt + minMs);
		}
	}

	/**
	 * The player did something that makes fresh data worth having. Make a poll due as soon as
	 * {@code minGap} has passed since the last one started. The backoff itself carries on where it
	 * was: only a real change on the site shortens it, so a player who opens the bank every few
	 * seconds gets one poll per {@code minGap}, not a return to the short gap.
	 */
	synchronized void pollSoon(long now, long minGap)
	{
		long earliest = lastStartedAt >= 0 ? Math.max(now, lastStartedAt + minGap) : now;
		nextAt = Math.min(nextAt, earliest);
	}

	/** Back to the starting state (a new login): the next check polls straight away. */
	synchronized void reset()
	{
		nextAt = 0;
		lastStartedAt = -1;
		interval = minMs;
	}

	/** When the next poll may start (for tests and debug logging). */
	synchronized long nextAt()
	{
		return nextAt;
	}
}

package com.runetools;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Settings the site can hand the plugin ({@code GET /api/plugin/config}) so a problem can be eased
 * from the server side without a new release. Every field is optional and a plain value: there is no
 * code, no pattern and no id in it, and it can only make the plugin do less.
 *
 * <ul>
 *   <li>{@code features}: a flag set to {@code false} switches that sync off. Nothing here can switch
 *       on what the player turned off.</li>
 *   <li>{@code limits}: intervals in seconds, clamped so the server can only slow the plugin down.</li>
 *   <li>{@code paths}: where each request goes, accepted only under {@code /api/plugin/}.</li>
 *   <li>{@code delete_method}: {@code DELETE} (the default) or {@code POST} to {@code <path>/delete}.</li>
 *   <li>{@code message}: a short notice for the panel, shown once in chat.</li>
 *   <li>{@code min_version}: a build older than this pauses every write.</li>
 * </ul>
 *
 * <p>An answer that isn't a JSON object is ignored, so the last good copy (or the built-in defaults,
 * which are exactly the plugin's own behaviour) stays in force. Immutable and thread-safe.
 */
final class RemoteConfig
{
	static final String PATH = "/api/plugin/config";
	static final String PATH_PREFIX = "/api/plugin/";

	static final Set<String> FEATURES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"trades", "state", "bank", "ca", "clog", "clog_request", "achievements", "setups_pull",
		"setups_write", "layouts_apply", "layouts_publish", "live", "pairing", "web_login")));

	/** Limit name -> {built-in default, ceiling}, in milliseconds. */
	private static final Map<String, long[]> LIMITS = new LinkedHashMap<>();
	/** Logical request name -> built-in path. */
	private static final Map<String, String> PATHS = new LinkedHashMap<>();

	static
	{
		limit("sync_s", 20, 3600);           // background sweep
		limit("poll_min_s", 30, 3600);       // setups / layouts ETag poll, shortest gap
		limit("poll_max_s", 300, 86400);     // ... and the idle ceiling
		limit("panel_gap_s", 10, 3600);      // opening the side panel pulls a poll in, at most this often
		limit("bank_gap_s", 60, 3600);       // opening the bank does too
		limit("live_gap_s", 10, 3600);       // shortest gap between two live-update requests
		limit("backoff_max_s", 600, 86400);  // a failing endpoint waits at most this long
		limit("config_s", 1800, 86400);      // how often this config is fetched again
		limit("pair_poll_s", 3, 60);         // pairing poll while a connection is being approved

		PATHS.put("web_login", "/api/plugin/web-login");
		PATHS.put("pair", "/api/plugin/pair");
		PATHS.put("pair_poll", "/api/plugin/pair/poll");
		PATHS.put("changes", "/api/plugin/changes");
		PATHS.put("setups", "/api/plugin/setups");
		PATHS.put("trades", "/api/plugin/trades");
		PATHS.put("state", "/api/plugin/state");
		PATHS.put("bank_layouts", "/api/plugin/bank-layouts");
		PATHS.put("combat_achievements", "/api/plugin/combat-achievements");
		PATHS.put("collection_log", "/api/plugin/collection-log");
		PATHS.put("achievements", "/api/plugin/achievements");
	}

	private static void limit(String name, long defaultSeconds, long maxSeconds)
	{
		LIMITS.put(name, new long[]{defaultSeconds * 1000L, maxSeconds * 1000L});
	}

	private static final int MAX_TEXT = 200;
	private static final RemoteConfig DEFAULTS = new RemoteConfig(Collections.emptySet(), Collections.emptyMap(),
		Collections.emptyMap(), false, null, null, "{}");

	/** A notice for the panel. */
	static final class Message
	{
		final String id;
		final String level;   // info | warn | error
		final String text;
		final String link;    // a path on the configured server, or null

		Message(String id, String level, String text, String link)
		{
			this.id = id;
			this.level = level;
			this.text = text;
			this.link = link;
		}
	}

	private final Set<String> off;
	private final Map<String, Long> limits;
	private final Map<String, String> paths;
	private final boolean deleteViaPost;
	private final Message message;
	private final String minVersion;
	private final String raw;

	private RemoteConfig(Set<String> off, Map<String, Long> limits, Map<String, String> paths,
		boolean deleteViaPost, Message message, String minVersion, String raw)
	{
		this.off = off;
		this.limits = limits;
		this.paths = paths;
		this.deleteViaPost = deleteViaPost;
		this.message = message;
		this.minVersion = minVersion;
		this.raw = raw;
	}

	/** The plugin's own behaviour: what applies when the site has never answered. */
	static RemoteConfig defaults()
	{
		return DEFAULTS;
	}

	/** Parse an answer, or null when it isn't a JSON object (the caller keeps what it had). */
	static RemoteConfig parse(String json)
	{
		if (json == null || json.trim().isEmpty() || json.length() > 64 * 1024)
		{
			return null;
		}
		JsonObject o;
		try
		{
			JsonElement root = new JsonParser().parse(json);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			o = root.getAsJsonObject();
		}
		catch (RuntimeException ex)
		{
			return null;
		}

		Set<String> off = new HashSet<>();
		JsonObject features = obj(o, "features");
		if (features != null)
		{
			for (String f : FEATURES)
			{
				JsonElement e = features.get(f);
				if (e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && !e.getAsBoolean())
				{
					off.add(f);
				}
			}
		}

		Map<String, Long> limits = new HashMap<>();
		JsonObject lim = obj(o, "limits");
		if (lim != null)
		{
			for (Map.Entry<String, long[]> en : LIMITS.entrySet())
			{
				JsonElement e = lim.get(en.getKey());
				if (e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber())
				{
					double seconds = e.getAsDouble();
					if (!Double.isNaN(seconds) && !Double.isInfinite(seconds))
					{
						limits.put(en.getKey(), clampMillis((long) Math.min(seconds * 1000d, 1e15),
							en.getValue()[0], en.getValue()[1]));
					}
				}
			}
		}

		Map<String, String> paths = new HashMap<>();
		boolean deleteViaPost = isPost(string(o, "delete_method"));
		JsonObject p = obj(o, "paths");
		if (p != null)
		{
			for (String name : PATHS.keySet())
			{
				String v = string(p, name);
				if (validPath(v))
				{
					paths.put(name, v);
				}
			}
			deleteViaPost |= isPost(string(p, "delete_method"));
		}

		return new RemoteConfig(Collections.unmodifiableSet(off), Collections.unmodifiableMap(limits),
			Collections.unmodifiableMap(paths), deleteViaPost, message(obj(o, "message")),
			version(string(o, "min_version")), json);
	}

	/** {@code remote} within [default, ceiling]: the server may only lengthen an interval. */
	static long clampMillis(long remote, long defaultMs, long maxMs)
	{
		return Math.max(defaultMs, Math.min(remote, maxMs));
	}

	/** A request path the server may point us at: under /api/plugin/, plain characters, no "..". */
	static boolean validPath(String path)
	{
		if (path == null || path.length() <= PATH_PREFIX.length() || path.length() > 120
			|| !path.startsWith(PATH_PREFIX) || path.contains("..") || path.contains("//"))
		{
			return false;
		}
		for (int i = 0; i < path.length(); i++)
		{
			char c = path.charAt(i);
			boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
				|| c == '/' || c == '-' || c == '_' || c == '.';
			if (!ok)
			{
				return false;
			}
		}
		return !path.endsWith("/");
	}

	/** A link a notice may carry: a path on the configured server, never another host or scheme. */
	static boolean validLink(String link)
	{
		if (link == null || link.isEmpty() || link.length() > MAX_TEXT || link.charAt(0) != '/'
			|| link.startsWith("//") || link.contains("..") || link.contains("\\"))
		{
			return false;
		}
		for (int i = 0; i < link.length(); i++)
		{
			char c = link.charAt(i);
			boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
				|| "/-_.?=&%#~+".indexOf(c) >= 0;
			if (!ok)
			{
				return false;
			}
		}
		return true;
	}

	boolean on(String feature)
	{
		return !off.contains(feature);
	}

	/** An interval in milliseconds: the built-in value unless the server asked for a longer one. */
	long limitMs(String name)
	{
		Long v = limits.get(name);
		if (v != null)
		{
			return v;
		}
		long[] d = LIMITS.get(name);
		return d != null ? d[0] : 0L;
	}

	/** Where a request goes: the built-in path unless the server named a valid one. */
	String path(String name)
	{
		String v = paths.get(name);
		return v != null ? v : PATHS.get(name);
	}

	boolean deleteViaPost()
	{
		return deleteViaPost;
	}

	Message message()
	{
		return message;
	}

	String minVersion()
	{
		return minVersion;
	}

	/** True when {@code version} is older than the server's {@code min_version}. */
	boolean tooOld(String version)
	{
		return minVersion != null && PluginVersion.compare(version, minVersion) < 0;
	}

	/** The answer as received, to cache. */
	String raw()
	{
		return raw;
	}

	private static Message message(JsonObject m)
	{
		if (m == null)
		{
			return null;
		}
		String text = clean(string(m, "text"), MAX_TEXT).trim();
		if (text.isEmpty())
		{
			return null;
		}
		String id = clean(string(m, "id"), 64).trim();
		if (id.isEmpty())
		{
			id = "t" + Integer.toHexString(text.hashCode());
		}
		String level = string(m, "level");
		level = "warn".equals(level) || "error".equals(level) ? level : "info";
		String link = string(m, "link");
		return new Message(id, level, text, validLink(link) ? link : null);
	}

	private static String version(String v)
	{
		if (v == null || v.isEmpty() || v.length() > 20)
		{
			return null;
		}
		for (int i = 0; i < v.length(); i++)
		{
			char c = v.charAt(i);
			if (!(c == '.' || (c >= '0' && c <= '9')))
			{
				return null;
			}
		}
		return v;
	}

	private static boolean isPost(String method)
	{
		return method != null && method.trim().equalsIgnoreCase("POST");
	}

	private static JsonObject obj(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		return p.isString() ? p.getAsString() : null;
	}

	/** Strip control and direction-override characters and cap the length. */
	static String clean(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < s.length() && sb.length() < max; i++)
		{
			int c = s.charAt(i);
			boolean drop = (c < 0x20) || (c == 0x7f)
				|| (c >= 0x80 && c <= 0x9f)
				|| (c == 0x2028 || c == 0x2029)
				|| (c >= 0x202a && c <= 0x202e)
				|| (c >= 0x2066 && c <= 0x2069);
			if (!drop)
			{
				sb.append((char) c);
			}
		}
		return sb.toString();
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Thin wrapper over the RuneTools plugin API. Every request carries the plugin's version headers and,
 * where it needs one, a character's Bearer key (never in the body, never in a log line), and is
 * dispatched asynchronously via OkHttp's {@code enqueue}, so nothing here ever blocks the game/client
 * thread.
 *
 * <p>One client lives for one run of the plugin. {@link #close} cancels everything still in flight and
 * drops any answer that arrives afterwards, so a request sent before the plugin was switched off can
 * never act once it is off (or after it is switched back on, which makes a new client).
 */
class RuneToolsApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	static final String DEFAULT_SERVER = "https://runetools.com";
	static final String BAD_URL_MESSAGE = "The Server URL setting isn't a valid web address.";

	/** Never buffer more than this from a response - bounds a hostile/huge body (memory-exhaustion DoS). */
	static final long MAX_RESPONSE_BYTES = 4L * 1024 * 1024;

	private final OkHttpClient http;
	// The same client, allowed to wait longer for an answer: the live-update request is held open by
	// the site for up to 50 seconds on purpose.
	private final OkHttpClient longPoll;
	private final RuneToolsConfig config;
	private final Supplier<RemoteConfig> remote;
	// Resolves the API key for the CURRENTLY logged-in character (per-account keys).
	private volatile Supplier<String> keySupplier = () -> null;

	private volatile boolean closed;
	private final Set<Call> inFlight = ConcurrentHashMap.newKeySet();
	private volatile Call liveCall;

	RuneToolsApiClient(OkHttpClient http, RuneToolsConfig config, Supplier<RemoteConfig> remote)
	{
		this.http = http;
		this.longPoll = http.newBuilder().readTimeout(80, TimeUnit.SECONDS).build();
		this.config = config;
		this.remote = remote != null ? remote : RemoteConfig::defaults;
	}

	/** Point the client at the plugin's per-character key resolver. */
	void setKeySupplier(Supplier<String> keySupplier)
	{
		this.keySupplier = keySupplier != null ? keySupplier : () -> null;
	}

	/** The active character's key, or "" (an empty key reads as "no key" server-side). */
	String activeKey()
	{
		String k = keySupplier.get();
		return k != null ? k : "";
	}

	/** Stop for good: cancel what is in flight and ignore every answer still to come. */
	void close()
	{
		closed = true;
		for (Call c : inFlight)
		{
			c.cancel();
		}
		inFlight.clear();
	}

	/** Cancel the live-update request, if one is waiting (a character switch or logout). */
	void cancelLive()
	{
		Call c = liveCall;
		if (c != null)
		{
			c.cancel();
		}
	}

	/**
	 * The server's base URL. The saved setting is normalised (see {@link #normalizeServerUrl}); an
	 * unusable one gives {@link #DEFAULT_SERVER} here, for display, while {@link #validBase} says the
	 * requests themselves must not go out.
	 */
	String base()
	{
		String b = validBase();
		return b != null ? b : DEFAULT_SERVER;
	}

	/** The normalised server URL, or null when the setting is not a usable https address. */
	String validBase()
	{
		return normalizeServerUrl(config.serverUrl());
	}

	/**
	 * Normalise a Server URL setting: blank means the default; a bare host gets {@code https://}; an
	 * {@code http://} one is upgraded (the key must never travel over cleartext, localhost included);
	 * the old gecharts.com address and www.runetools.com become https://runetools.com; trailing slashes
	 * go. Anything else that isn't a plain https URL (another scheme, a query, junk) gives null.
	 */
	static String normalizeServerUrl(String raw)
	{
		if (raw == null || raw.trim().isEmpty())
		{
			return DEFAULT_SERVER;
		}
		String u = raw.trim();
		while (u.endsWith("/"))
		{
			u = u.substring(0, u.length() - 1);
		}
		int scheme = u.indexOf("://");
		if (scheme < 0)
		{
			if (u.contains(":") && !u.matches("^[A-Za-z0-9.\\-]+:\\d+(/.*)?$"))
			{
				return null;   // "javascript:..." and the like, not a host with a port
			}
			u = "https://" + u;
		}
		else if (u.regionMatches(true, 0, "http://", 0, 7))
		{
			u = "https://" + u.substring(7);
		}
		else if (!u.regionMatches(true, 0, "https://", 0, 8))
		{
			return null;
		}
		HttpUrl parsed = HttpUrl.parse(u);
		if (parsed == null || parsed.query() != null || parsed.fragment() != null || u.contains("@"))
		{
			return null;
		}
		String host = parsed.host().toLowerCase(Locale.ROOT);
		boolean plain = parsed.port() == 443 && ("/".equals(parsed.encodedPath()) || parsed.encodedPath().isEmpty());
		if (plain && (host.equals("gecharts.com") || host.equals("www.gecharts.com") || host.equals("www.runetools.com")))
		{
			return DEFAULT_SERVER;
		}
		String out = parsed.toString();
		while (out.endsWith("/"))
		{
			out = out.substring(0, out.length() - 1);
		}
		return out;
	}

	/** The bare host of a URL (no scheme, userinfo, port, path), or "" if it can't be parsed. */
	static String hostOf(String url)
	{
		if (url == null)
		{
			return "";
		}
		int scheme = url.indexOf("://");
		String rest = scheme >= 0 ? url.substring(scheme + 3) : url;
		int slash = rest.indexOf('/');
		if (slash >= 0)
		{
			rest = rest.substring(0, slash);
		}
		int at = rest.lastIndexOf('@');   // strip userinfo
		if (at >= 0)
		{
			rest = rest.substring(at + 1);
		}
		if (rest.startsWith("["))         // IPv6 literal: [::1]:port
		{
			int rb = rest.indexOf(']');
			return rb >= 0 ? rest.substring(1, rb) : rest.substring(1);
		}
		int colon = rest.indexOf(':');    // strip port
		if (colon >= 0)
		{
			rest = rest.substring(0, colon);
		}
		return rest;
	}

	/**
	 * True only for genuine loopback hosts. Used to vet the (untrusted) host of a server-supplied
	 * share URL, so the 127.0.0.0/8 test validates four numeric octets - a bare
	 * {@code startsWith("127.")} would wrongly accept "127.evil.com" or "127.0.0.1.attacker.example".
	 */
	static boolean isLoopbackHost(String host)
	{
		if (host == null || host.isEmpty())
		{
			return false;
		}
		String h = host.toLowerCase();
		if (h.equals("localhost") || h.equals("::1") || h.equals("0:0:0:0:0:0:0:1"))
		{
			return true;
		}
		String[] octets = h.split("\\.");
		if (octets.length != 4)
		{
			return false;
		}
		try
		{
			if (Integer.parseInt(octets[0]) != 127)
			{
				return false;
			}
			for (int i = 1; i < 4; i++)
			{
				int o = Integer.parseInt(octets[i]);
				if (o < 0 || o > 255)
				{
					return false;
				}
			}
			return true;
		}
		catch (NumberFormatException ex)
		{
			return false;   // non-numeric label is not loopback
		}
	}

	/** Read a response body without ever buffering more than {@link #MAX_RESPONSE_BYTES}. Re-readable. */
	static String readBoundedBody(Response r) throws IOException
	{
		if (r == null || r.body() == null)
		{
			return "";
		}
		return r.peekBody(MAX_RESPONSE_BYTES).string();
	}

	/** Like {@link #readBoundedBody}, but "" instead of an exception (an error body is best-effort). */
	static String bodyOrEmpty(Response r)
	{
		try
		{
			return readBoundedBody(r);
		}
		catch (IOException | RuntimeException ex)
		{
			return "";
		}
	}

	private String path(String name)
	{
		return remote.get().path(name);
	}

	/** A request with the version headers and no key (pairing is how a client without one gets one). */
	private Request.Builder plain(String path)
	{
		String b = validBase();
		if (b == null)
		{
			throw new IllegalArgumentException(BAD_URL_MESSAGE);
		}
		return new Request.Builder()
			.url(b + path)
			.header("Accept", "application/json")
			.header(PluginVersion.HEADER_VERSION, PluginVersion.VERSION)
			.header(PluginVersion.HEADER_API, String.valueOf(PluginVersion.API_LEVEL));
	}

	private Request.Builder authed(String path)
	{
		return authed(path, activeKey());
	}

	private Request.Builder authed(String path, String key)
	{
		return plain(path).header("Authorization", "Bearer " + (key != null ? key : ""));
	}

	private interface RequestMaker
	{
		Request make();
	}

	/**
	 * Send a request. A request that can't even be built (an unusable Server URL) fails through the
	 * callback at once, so a caller's in-flight flag is always released; after {@link #close} nothing
	 * is sent and no callback runs.
	 */
	private void send(OkHttpClient client, RequestMaker maker, Callback callback, boolean live)
	{
		if (closed)
		{
			return;
		}
		Request req;
		try
		{
			req = maker.make();
		}
		catch (RuntimeException ex)
		{
			callback.onFailure(null, new IOException(BAD_URL_MESSAGE));
			return;
		}
		Call call = client.newCall(req);
		inFlight.add(call);
		if (closed)
		{
			// close() ran while this was being built: it may have missed the call, so it never leaves.
			inFlight.remove(call);
			return;
		}
		if (live)
		{
			liveCall = call;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException ex)
			{
				inFlight.remove(c);
				if (!closed)
				{
					callback.onFailure(c, ex);
				}
			}

			@Override
			public void onResponse(Call c, Response r) throws IOException
			{
				inFlight.remove(c);
				if (closed)
				{
					r.close();
					return;
				}
				callback.onResponse(c, r);
			}
		});
	}

	private static RequestBody json(String body)
	{
		return RequestBody.create(JSON, body);
	}

	/** The site's settings for the plugin (see {@link RemoteConfig}). Optional: a 404 changes nothing. */
	void getConfig(Callback callback)
	{
		send(http, () -> plain(RemoteConfig.PATH).get().build(), callback, false);
	}

	/**
	 * Wait for setups or bank layouts saved on the site: the server answers as soon as either differs
	 * from the versions given (the ones its last answer named; empty the first time), or with an
	 * empty 204 after about 50 seconds. Response: {@code {setups, layouts, setups_tag, layouts_tag}},
	 * and {@code config_tag} once the site has a remote config.
	 */
	void waitForChanges(String setupsTag, String layoutsTag, String configTag, Callback callback)
	{
		String q = "?setups=" + enc(setupsTag) + "&layouts=" + enc(layoutsTag) + "&config=" + enc(configTag);
		send(longPoll, () -> authed(path("changes") + q).get().build(), callback, true);
	}

	private static String enc(String s)
	{
		return URLEncoder.encode(s != null ? s : "", StandardCharsets.UTF_8);
	}

	/**
	 * Mint a one-time browser-login code for the account this character's stored key opens, so the
	 * user can open the site already signed in. It never creates an account or hands out a key: with
	 * no working key for this character the site answers 403 {@code code: "pair"} (connect it by
	 * {@link #pairStart pairing}), and for an account with an email 403 {@code code: "email_signin"}.
	 * {@code next} is the site path to land on once signed in (null for the home page). Response:
	 * {@code {code, url}}.
	 */
	void webLogin(String accountHash, String rsn, String next, Callback callback)
	{
		JsonObject body = new JsonObject();
		if (accountHash != null)
		{
			body.addProperty("account_hash", accountHash);
		}
		body.addProperty("rsn", rsn);
		if (next != null)
		{
			body.addProperty("next", next);
		}
		send(http, () -> authed(path("web_login")).post(json(body.toString())).build(), callback, false);
	}

	/**
	 * Start pairing: how a character with no working key here gets connected. Sent without a key.
	 * Response: {@code {poll_token, user_code, url, expires_in, interval}}; a person approves
	 * user_code at <site>{url} in the browser, and {@link #pairPoll} then hands back this
	 * character's key.
	 */
	void pairStart(String accountHash, String rsn, Callback callback)
	{
		JsonObject body = new JsonObject();
		if (accountHash != null)
		{
			body.addProperty("account_hash", accountHash);
		}
		body.addProperty("rsn", rsn);
		send(http, () -> plain(path("pair")).post(json(body.toString())).build(), callback, false);
	}

	/**
	 * Poll a pairing: {@code {status: "pending"}} until the player approves it, then once
	 * {@code {status: "approved", api_key}}; HTTP 410 once it expired or was used.
	 */
	void pairPoll(String pollToken, Callback callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("poll_token", pollToken);
		send(http, () -> plain(path("pair_poll")).post(json(body.toString())).build(), callback, false);
	}

	/** Pull the user's gear setups (full list). A matching {@code etag} yields a cheap 304. */
	void getSetups(String etag, Callback callback)
	{
		send(http, () ->
		{
			Request.Builder b = authed(path("setups") + "?since=0");
			if (etag != null && !etag.isEmpty())
			{
				b.header("If-None-Match", etag);
			}
			return b.get().build();
		}, callback, false);
	}

	/** Create a setup on the site from the plugin (two-way sync). */
	void createSetup(JsonObject setup, Callback callback)
	{
		String body = setup.toString();
		send(http, () -> authed(path("setups")).post(json(body)).build(), callback, false);
	}

	/** Update a setup on the site. */
	void updateSetup(long id, JsonObject setup, Callback callback)
	{
		String body = setup.toString();
		send(http, () -> authed(path("setups") + "/" + id).put(json(body)).build(), callback, false);
	}

	/** Delete a setup on the site ({@code DELETE}, or {@code POST .../delete} when the site asks for it). */
	void deleteSetup(long id, Callback callback)
	{
		boolean viaPost = remote.get().deleteViaPost();
		send(http, () -> viaPost
			? authed(path("setups") + "/" + id + "/delete").post(json("{}")).build()
			: authed(path("setups") + "/" + id).delete().build(), callback, false);
	}

	/** Upload fills with the key of the character that made them (see {@link TradeGroups}). */
	void postTrades(String key, String rsn, String accountHash, List<Trade> trades, Callback callback)
	{
		JsonArray arr = new JsonArray();
		for (Trade t : trades)
		{
			JsonObject o = new JsonObject();
			o.addProperty("item_id", t.getItemId());
			o.addProperty("side", t.getSide());
			o.addProperty("qty", t.getQty());
			o.addProperty("price", t.getPrice());
			o.addProperty("ts", t.getTsMillis());
			o.addProperty("ext_id", t.getExtId());
			arr.add(o);
		}
		JsonObject body = new JsonObject();
		body.addProperty("rsn", rsn);
		if (accountHash != null)
		{
			body.addProperty("account_hash", accountHash);
		}
		body.add("trades", arr);
		String s = body.toString();
		send(http, () -> authed(path("trades"), key).post(json(s)).build(), callback, false);
	}

	/** Publish a bank layout to the user's runetools.com profile; response carries {code, url}. */
	void postBankLayout(JsonObject body, Callback callback)
	{
		String s = body.toString();
		send(http, () -> authed(path("bank_layouts")).post(json(s)).build(), callback, false);
	}

	/** Push the CA catalog + this account's completion to the site's planner. */
	void postCombatAchievements(JsonObject body, Callback callback)
	{
		String s = body.toString();
		send(http, () -> authed(path("combat_achievements")).post(json(s)).build(), callback, false);
	}

	/** Push collection-log totals + the pages read this session (server accumulates the replica). */
	void postCollectionLog(JsonObject body, Callback callback)
	{
		String s = body.toString();
		send(http, () -> authed(path("collection_log")).post(json(s)).build(), callback, false);
	}

	/** Push achievements for the Adventurer's Log: {@code {rsn, account_hash, events: [...]}}. */
	void postAchievements(JsonObject body, Callback callback)
	{
		String s = body.toString();
		send(http, () -> authed(path("achievements")).post(json(s)).build(), callback, false);
	}

	/** Pull the user's bank layouts (incl. ones imported on the site). A matching {@code etag} -> 304. */
	void getBankLayouts(String etag, Callback callback)
	{
		send(http, () ->
		{
			Request.Builder b = authed(path("bank_layouts") + "?since=0");
			if (etag != null && !etag.isEmpty())
			{
				b.header("If-None-Match", etag);
			}
			return b.get().build();
		}, callback, false);
	}

	/**
	 * The {@code /state} body for a snapshot, without the capture timestamp ({@code ts}): that differs
	 * on every send, and leaving it to the caller lets two sends of the same state be compared.
	 * {@code includeBank} false leaves the bank out, which tells the server to keep the one it has.
	 *
	 * <p>Every field here is one the server stores; anything it would only throw away is not sent.
	 * Keep this in step with the README's "What it sends" table and the consent text.
	 */
	static JsonObject stateBody(AccountSnapshot s, boolean includeBank)
	{
		JsonObject body = new JsonObject();
		body.addProperty("rsn", s.rsn);
		if (s.accountHash != null)
		{
			body.addProperty("account_hash", s.accountHash);
		}
		body.addProperty("members", s.members);
		body.addProperty("gp", s.gp);
		body.addProperty("free_slots", s.freeSlots);
		body.add("offers", s.offers);
		body.add("inventory", s.inventory);
		// Only send the bank once it's captured; omitting it tells the server to keep the last one.
		if (includeBank && s.bank != null)
		{
			body.add("bank", s.bank);
		}
		// Worn equipment likewise.
		if (s.equipment != null)
		{
			body.add("equipment", s.equipment);
		}
		// Same preserve-if-absent contract for skills.
		if (s.skills != null)
		{
			body.add("skills", s.skills);
		}
		return body;
	}

	/** {@link #stateBody(AccountSnapshot, boolean)} with the bank, when captured. */
	static JsonObject stateBody(AccountSnapshot s)
	{
		return stateBody(s, true);
	}

	/** Post a {@link #stateBody} with its {@code ts} stamped in. */
	void postState(JsonObject body, Callback callback)
	{
		String s = body.toString();
		send(http, () -> authed(path("state")).post(json(s)).build(), callback, false);
	}
}

package com.runetools;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(RuneToolsConfig.GROUP)
public interface RuneToolsConfig extends Config
{
	String GROUP = "runetools";

	@ConfigSection(
		name = "Connection",
		description = "How the plugin talks to the RuneTools site",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigSection(
		name = "What to sync",
		description = "Which data the plugin uploads",
		position = 1
	)
	String syncSection = "sync";

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "The RuneTools server to sync with. Leave as the default unless you are testing against a local/staging server.",
		section = connectionSection,
		position = 1
	)
	default String serverUrl()
	{
		return "https://runetools.com";
	}

	@ConfigItem(
		keyName = "consent",
		name = "I consent to sending my account data to RuneTools",
		description = "The plugin sends nothing until this is enabled.",
		// Keep this in step with what the plugin actually sends (RuneToolsApiClient) and with the
		// README's "What it sends" table.
		warning = "Once enabled, and once you connect a character, this plugin sends the following "
			+ "to the RuneTools server:\n"
			+ "- The plugin's version, with every request.\n"
			+ "- Your character name (RSN), RuneLite account hash and a capture time, to link the character "
			+ "to your RuneTools account.\n"
			+ "- Completed Grand Exchange trades (item, buy or sell, quantity, price, time), for "
			+ "profit tracking.\n"
			+ "- Your coins (including banked coins once you open your bank), free GE slots, open GE "
			+ "offers, inventory, the gear you're wearing and whether you are on a members world, for "
			+ "flip suggestions that fit your bankroll and best-in-slot from the gear you own.\n"
			+ "- Your skill levels and experience, for level-aware calculators and to prove the "
			+ "character is yours (the site checks it against the official hiscores).\n"
			+ "- Your Combat Achievements (the task list and which tasks you have completed), for the "
			+ "site's planner.\n"
			+ "- Your Collection Log progress counts, the items you have obtained when you open "
			+ "the log in-game, and the name and time of each new item the game announces, for a "
			+ "browsable copy of your log and your drop timeline on the site.\n"
			+ "- A gear setup's worn gear, inventory, rune pouch, quiver and spellbook, when you save "
			+ "or update that setup.\n"
			+ "- A bank tab's item layout, only when you export it to share it.\n"
			+ "- Your bank contents, only if you turn on \"Include bank\".\n"
			+ "- Achievements as they happen, for the Adventurer's Log on your public profile: level-ups, "
			+ "quests, achievement diaries, combat tasks, pets, boss kill-count milestones and personal "
			+ "bests, and clue milestones; and, only with \"Drops and loot\" on, valuable and untradeable "
			+ "drops, chest and raid loot and valuable clue rewards (the item and its value).\n"
			+ "Nothing else is sent. The automatic syncs can each be switched off under \"What to "
			+ "sync\", \"Gear setups\" and \"Adventurer's Log\", and your profile can be "
			+ "made private on the site.\n"
			// The Plugin Hub requires this sentence, near enough verbatim, on any config item that
			// turns on a third-party-server feature. Without it the plugin fails review.
			+ "This feature submits your IP address to a 3rd-party server not controlled or verified "
			+ "by RuneLite developers. Your API key is stored locally and sent only to that server "
			+ "over HTTPS. Enable only if you accept this.",
		section = connectionSection,
		position = 2
	)
	default boolean consent()
	{
		return false;
	}

	@ConfigItem(
		keyName = "syncTrades",
		name = "Sync GE trades",
		description = "Upload completed Grand Exchange buys and sells for automatic profit tracking on the site.",
		section = syncSection,
		position = 0
	)
	default boolean syncTrades()
	{
		return true;
