		{
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			if (rows.getComponentCount() > 0)
			{
				rows.add(Box.createVerticalStrut(4));
			}
			rows.add(row);
		}
		rows.setAlignmentX(Component.LEFT_ALIGNMENT);

		signIn = flatButton("Open RuneTools  ↗");
