	/** Lets the setups panel open the in-game item search and read live equipment/inventory slots. */
	private final SlotEditor slotEditor = new SlotEditor()
	{
		@Override
		public void searchItem(String tooltip, ItemPick onPicked)
		{
			clientThread.invoke(() ->
			{
				if (client.getGameState() != GameState.LOGGED_IN)
				{
					panel.showMessage(MSG_LOG_IN, false);
					return;
				}
				itemSearch
					.tooltipText(tooltip)
					.onItemSelected(itemId -> clientThread.invoke(() ->
					{
						int canon = itemManager.canonicalize(itemId);
						SwingUtilities.invokeLater(() -> onPicked.accept(canon, 1));
					}))
					.build();
			});
		}

		@Override
		public void readEquipSlot(int equipIdx, ItemPick onItem)
		{
			readSlot(InventoryID.WORN, equipIdx, onItem);
		}

		@Override
		public void readInvSlot(int index, ItemPick onItem)
		{
			readSlot(InventoryID.INV, index, onItem);
		}

		private void readSlot(int container, int index, ItemPick onItem)
		{
			clientThread.invoke(() ->
			{
				if (client.getGameState() != GameState.LOGGED_IN)
				{
					panel.showMessage(MSG_LOG_IN, false);
					return;
				}
				Item it = itemAt(client.getItemContainer(container), index);
				final int id = it != null ? itemManager.canonicalize(it.getId()) : -1;
				final int qty = it != null ? Math.max(1, it.getQuantity()) : 0;
				SwingUtilities.invokeLater(() -> onItem.accept(id, qty));
			});
		}

		@Override
		public void isQuiver(int itemId, Consumer<Boolean> onResult)
		{
			final boolean q = itemId > 0 && LoadoutReader.QUIVERS.contains(itemId);
			SwingUtilities.invokeLater(() -> onResult.accept(q));
		}

		@Override
		public void itemName(int itemId, Consumer<String> onName)
		{
			clientThread.invoke(() ->
			{
				String name;
				try
				{
					name = itemManager.getItemComposition(itemId).getName();
				}
				catch (RuntimeException ex)
				{
					name = null;
				}
				final String n = name;
				SwingUtilities.invokeLater(() -> onName.accept(n));
			});
		}
	};

	/** The item in a container slot, or null for an empty slot. Client thread. */
	private static Item itemAt(ItemContainer c, int idx)
	{
		if (c == null)
		{
			return null;
		}
		Item[] items = c.getItems();
		if (idx < 0 || idx >= items.length || items[idx].getId() <= 0)
		{
			return null;
		}
		return items[idx];
	}

	@Override
	protected void startUp()
	{
		running = true;
		resetSession();
		// A sweep that was still running when the plugin was switched off can set one of these after
		// shutDown cleared it, for a request the closed client then never answers: start clean.
		liveInFlight.set(false);
		achievementsInFlight.set(false);
		configInFlight.set(false);
		tradesInFlight.clear();
		offWorldShown = false;
		migrateServerUrl();
		debounced = new DebouncedConfig(this::writeConfig,
			k -> configManager.getConfiguration(RuneToolsConfig.GROUP, k), executor, 2_000L);
		remoteConfig = cachedRemoteConfig();
		api = new RuneToolsApiClient(okHttpClient, config, () -> remoteConfig);
		api.setKeySupplier(this::activeApiKey);   // per-character keys: authenticate as the logged-in character
		bankFilter = new BankFilterController(bankTagsService, tagManager, layoutManager, itemManager, clientThread);
		bankOrganizer = new BankOrganizer(bankTagsService, tagManager, layoutManager, tabManager, itemManager,
			clientThread, configManager);
		setupManager = new SetupManager(debounced, api, setupHost, executor);
		// The setups cache used to be one blob for every character; it is kept per account hash now.
		configManager.unsetConfiguration(RuneToolsConfig.GROUP, "setups");
		configManager.unsetConfiguration(RuneToolsConfig.GROUP, "setupsEtag");
		loadoutReader = new LoadoutReader(client, itemManager);
		adventureLog = new AdventureLog(new AdventureLog.Settings()
		{
			@Override
			public boolean on(AdventureLog.Category category)
			{
				switch (category)
				{
					case LEVELS:
						return config.logLevels();
					case QUESTS:
						return config.logQuests();
					case COMBAT:
						return config.logCombat();
					case PETS:
						return config.logPets();
					case DROPS:
						return config.logDrops();
					case CLUES:
						return config.logClues();
					default:
						return false;
				}
			}

			@Override
			public long minValue()
			{
				return Math.max(0, config.logMinValue());
			}
		});
		loadPending();

		panel = new RuneToolsPanel(this::onFilterSetup, this::onClearFilter, itemManager,
			this::addCurrentSetup, this::updateFromGear, this::pushSetup, this::deleteSetup, slotEditor, this::openHistory,
			this::organizeBank, this::removeOrganizedTabs, this::convertBankTab, this::exportBankTag, this::openSiteLogin,
			this::checkDps, this::importInventorySetups);
		// Opening the side panel is the clearest sign the player wants current setups: poll now
		// instead of waiting out the backoff.
		panel.setOnOpened(() -> requestRemotePoll(remoteConfig.limitMs("panel_gap_s")));
		panel.setMissingComputer(this::computeMissingItems);
		panel.setBankLayoutActions(this::exportWholeBank, this::removeImportedBank);
		applyRemoteConfig(remoteConfig, false);
		loadSpellbookIcons();
		navButton = NavigationButton.builder()
			.tooltip("RuneTools")
			.icon(icon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		updatePanelStatic();
		updateTradesPanel();
	}

	@Override
	protected void shutDown()
	{
		running = false;
		// Nothing still in flight may act from here on: cancel it all, and drop what answers anyway.
		api.close();
		setupManager.close();
		loggedIn = false;
		mainGame = false;
		liveInFlight.set(false);
		achievementsInFlight.set(false);
		configInFlight.set(false);
		tradesInFlight.clear();
		// Close our Bank Tags setup filter if it is the one open, so the bank isn't left filtered to a
		// gear setup after the plugin is disabled. Another plugin's open tag is left alone.
		bankFilter.clear();
		removeDpsButton();
		pairing.set(null);   // a pending pairing dies with the plugin; Connect starts a fresh one
		clientToolbar.removeNavigation(navButton);
		savePending();
		debounced.flush();
		// While the plugin is disabled the event bus is unregistered, so no logout is ever seen:
		// without this, disabling, switching character and re-enabling would carry the previous
		// character's captured state (and Collection Log pages) over to the next one.
		resetSession();
		navButton = null;
		// Keep the panel reference: a late callback may still touch it (the api client drops them).
	}

	/**
	 * RuneLite exits without switching plugins off, so the writes DebouncedConfig is holding (the
	 * unsynced-trade queue, the setups cache) go into the config now. This runs before ConfigManager
	 * saves the config for the last time (its handler has priority -100).
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (running && debounced != null)
		{
			savePending();
			debounced.flush();
		}
	}

	/** Forget everything captured from the game this session (plugin start and stop). */
	private void resetSession()
	{
		chars.reset();
		stateDirty.set(false);
		identityAnnounced = false;
		loggedInTick = -1;
		discardCollectionCapture();
		if (adventureLog != null)
		{
			adventureLog.reset();
		}
		levelBaseline = null;
		levelBaselineXp = null;
		synchronized (achievements)
		{
			achievements.clear();
		}
		synchronized (clogLock)
		{
			clogUnlocks.clear();
		}
		forgetCharacterSync();
		parking.clear();
		backoff.clear();
		authFailures.set(0);
		authRevoked = false;
		lastSweepAt = 0;
		lastConfigFetchAt = 0;
		lastConfigTag = "";
	}

	/** Drop what the site sync knows about the character in game (a switch, a logout, a stop). */
	private void forgetCharacterSync()
	{
		caCatalogSent = false;
		caCompletedHash = 0;
		lastCaSnapshot = null;
		caThresholds = null;
		layoutsEtag = null;
		bankImportWaiting = false;
		liveSetupsTag = "";
		liveLayoutsTag = "";
		liveRetryAt = 0;
		liveNextAt = 0;
		liveFailures.set(0);
		if (api != null)
		{
			api.cancelLive();
		}
	}

	/**
	 * Old installs saved https://gecharts.com (the site's first address) as the Server URL, and some
	 * typed www.runetools.com or left the https:// off. Save the address those mean.
	 */
	private void migrateServerUrl()
	{
		String saved = configManager.getConfiguration(RuneToolsConfig.GROUP, "serverUrl");
		if (saved == null || saved.trim().isEmpty())
		{
			return;
		}
		String norm = RuneToolsApiClient.normalizeServerUrl(saved);
		if (norm != null && !norm.equals(saved))
		{
			configManager.setConfiguration(RuneToolsConfig.GROUP, "serverUrl", norm);
		}
	}

	/** How DebouncedConfig writes: null unsets the key. */
	private void writeConfig(String key, String value)
	{
		if (value == null)
		{
			configManager.unsetConfiguration(RuneToolsConfig.GROUP, key);
		}
		else
		{
			configManager.setConfiguration(RuneToolsConfig.GROUP, key, value);
		}
	}

	@Provides
	RuneToolsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneToolsConfig.class);
	}

	// -- capture (all handlers run on the client thread) --------------------- //

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		// The sync loop only runs while a character is in game. LOADING is a region change rather than
		// a logout, so it leaves the gate alone; every other non-LOGGED_IN state closes it.
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			loggedIn = true;
			mainGame = isMainGame();
			if (loggedInTick < 0)
			{
				loggedInTick = client.getTickCount();   // levels are only trusted a few ticks after this
			}
		}
		else if (e.getGameState() != GameState.LOADING)
		{
			loggedIn = false;
		}
		// LOGGING_IN and CONNECTION_LOST are on this list too: a character switch can go straight
		// from one login to the next without passing through LOGIN_SCREEN, and captured state must
		// never survive into a different character's session (the reference plugins reset on the
		// same set). The account-hash check in captureAllowed() catches a switch that skips them.
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING
			|| e.getGameState() == GameState.LOGGING_IN || e.getGameState() == GameState.CONNECTION_LOST)
		{
			// Character context is gone; drop identity so we never attribute to the wrong RSN.
			snapshot.updateAndGet(s -> s.toBuilder().rsn(null).build());
			identityAnnounced = false;
			offWorldShown = false;   // the next world (seasonal or not) gets its own status line
			// Drop any half-read Collection Log: the next character's log must never inherit it.
			discardCollectionCapture();
			// Whoever logs in next gets a clean slate: a different character has a different key, and
			// even the same one may have been reconnected on the site while we sat at the login screen.
			resumeSync();
			// ...and a fresh look at the site's setups as soon as they're in. A world hop keeps the
			// same character, so it keeps the current backoff rather than polling on every hop.
			if (e.getGameState() != GameState.HOPPING)
			{
				remotePoll.reset();
			}
			// Half-seen achievements (a kill waiting for its time, a pet for its name) can't finish
			// now, and the next login reads its levels afresh. Queued ones stay with their character.
			adventureLog.reset();
			levelBaseline = null;
			levelBaselineXp = null;
			loggedInTick = -1;
		}
		if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Logged out: the session's capture (bank, inventory, skills, account hash, coins) goes. A
			// hop keeps it, since it is the same character on another world.
			mainGame = false;
			chars.logout();
			stateDirty.set(false);
			forgetCharacterSync();
			backoff.clear();
			setupManager.switchAccount(null);
			updatePanelStatic();
			updateTradesPanel();
		}
	}

	/**
	 * Whether the world is the main game. Leagues, Deadman, beta, tournament, quest-speedrun, Fresh
	 * Start, PvP Arena and Last Man Standing worlds hold progress that isn't the character's own, so
	 * nothing from them is captured, queued or sent. Client thread.
	 */
	private boolean isMainGame()
	{
		EnumSet<WorldType> types = client.getWorldType();
		return types != null && Collections.disjoint(types, NOT_MAIN_GAME);
	}

	/** The account hash in game, or null before it is known. */
	private String currentHash()
	{
		long ah = client.getAccountHash();
		return ah == -1 ? null : Long.toString(ah);
	}

	/**
	 * Gate for every capture handler (client thread): only on a main-game world, and only once the
	 * captured state is known to belong to the character in game. A capture that finds a different
	 * account hash first drops what the previous character left behind.
	 */
	private boolean captureAllowed()
	{
		if (!running || !isMainGame())
		{
			return false;
		}
		if (chars.adopt(currentHash()))
		{
			onCharacterChanged();
		}
		return true;
	}

	/** Another character's captured state was just dropped (CharacterState.adopt). Client thread. */
	private void onCharacterChanged()
	{
		identityAnnounced = false;
		stateDirty.set(false);
		discardCollectionCapture();
		adventureLog.reset();
		levelBaseline = null;
		levelBaselineXp = null;
		forgetCharacterSync();
		resumeSync();
		backoff.clear();
		remotePoll.reset();
		updateTradesPanel();
		log.debug("RuneTools: a different character is in game; the previous one's captured state was dropped");
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			// Opening the bank is when setups and imported layouts get used, so fetch any new ones.
			requestRemotePoll(remoteConfig.limitMs("bank_gap_s"));
		}
		else if (e.getGroupId() == InterfaceID.COLLECTION)
		{
			clogAskedThisOpen = false;   // a fresh opening of the log may ask for the whole log once
		}
		else if (e.getGroupId() == InterfaceID.QUESTSCROLL && adventureLogOn())
		{
			Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
			final String text = title != null ? Text.removeTags(title.getText()) : null;
			// A moment later, so the completed-quest count has caught up with this quest.
			clientThread.invokeLater(() ->
			{
				String quest = AdventureLog.matchQuest(text, QUEST_NAMES);
				if (quest != null)
				{
					adventureLog.onQuest(quest, client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT),
						System.currentTimeMillis());
				}
				else if (text != null)
				{
					log.debug("RuneTools: no quest matched the completion scroll \"{}\"", text);
				}
			});
		}
		else if (e.getGroupId() == InterfaceID.TRAIL_REWARDSCREEN && adventureLogOn())
		{
			readClueReward();
		}
	}

	/** The items on a clue reward screen, priced, most valuable first. Client thread. */
	private void readClueReward()
	{
		Widget box = client.getWidget(InterfaceID.TrailRewardscreen.ITEMS);
		Widget[] children = box != null ? box.getChildren() : null;
		if (children == null)
		{
			return;
		}
		Map<Integer, Integer> qty = new LinkedHashMap<>();
		for (Widget w : children)
		{
			if (w != null && w.getItemId() > 0 && w.getItemQuantity() > 0)
			{
				qty.merge(w.getItemId(), w.getItemQuantity(), Integer::sum);
			}
		}
		List<long[]> priced = new ArrayList<>();
		long total = 0;
		for (Map.Entry<Integer, Integer> en : qty.entrySet())
		{
			long each = en.getKey() == ItemID.COINS ? 1 : itemManager.getItemPrice(en.getKey());
			long value = Math.max(0, each) * en.getValue();
			total += value;
			priced.add(new long[]{en.getKey(), en.getValue(), value});
		}
		priced.sort((a, b) -> Long.compare(b[2], a[2]));
		List<int[]> items = new ArrayList<>();
		for (long[] p : priced)
		{
			items.add(new int[]{(int) p[0], (int) p[1]});
		}
		adventureLog.onClueReward(items, total, System.currentTimeMillis());
	}

	/**
	 * Loot from chests and raids (Barrows, the raid reward chests, the Moons...), which the game
	 * doesn't announce like an NPC's valuable drop, as RuneLite's Loot Tracker reports it. NPC drops
	 * come from the game's own messages instead, and clue rewards from their reward screen.
	 */
	@Subscribe
	public void onLootReceived(LootReceived e)
	{
		String source = e.getName() != null ? e.getName().toLowerCase(Locale.ROOT) : "";
		if (e.getType() != LootRecordType.EVENT || source.contains("clue") || source.contains("casket")
			|| !config.logDrops() || !adventureLogOn() || e.getItems() == null)
		{
			return;
		}
		List<AdventureLog.LootStack> stacks = new ArrayList<>();
		for (ItemStack it : e.getItems())
		{
			if (it == null || it.getId() <= 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(it.getId());
			long each = id == ItemID.COINS ? 1 : itemManager.getItemPrice(id);
			stacks.add(new AdventureLog.LootStack(itemManager.getItemComposition(id).getName(), it.getQuantity(),
				Math.max(0, each) * it.getQuantity()));
		}
		adventureLog.onChestLoot(stacks, System.currentTimeMillis());
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (!captureAllowed())
		{
			return;
		}
		trackLevel(e.getSkill());
		if (!config.syncState())
		{
			return;
		}
		// Rebuild the whole skills object so the snapshot stays internally consistent.
		JsonObject skills = new JsonObject();
		for (Skill sk : Skill.values())
		{
			// Skip the total: Skill.OVERALL is deprecated (it isn't a real skill), so it's matched by
			// name, which also keeps compiling once the constant is gone.
			if ("Overall".equals(sk.getName()))
			{
				continue;
			}
			JsonObject s = new JsonObject();
			s.addProperty("level", client.getRealSkillLevel(sk));
			s.addProperty("xp", client.getSkillExperience(sk));
			skills.add(sk.getName().toLowerCase(), s);
		}
		// StatChanged also fires for boosted levels (hitpoints regenerating, a potion wearing off),
		// which leave real levels and XP alone. Only an actual change is worth an upload.
		if (skills.equals(snapshot.get().skills))
		{
			return;
		}
		snapshot.updateAndGet(s -> s.toBuilder().skills(skills).build());
		stateDirty.set(true);
	}

	/**
	 * Fail-safe: the moment the game says the open Collection Log belongs to the POH host, drop
	 * anything captured while it was on screen. The capture paths check this too; this catches the
	 * window between the interface opening and the varbit arriving. Client thread.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (e.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN && CollectionLog.isOtherPlayers(client))
		{
			discardCollectionCapture();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		updateIdentity();
		// A CA-completion chat message fired: resync now (a tick later, so the completion varp has
		// settled) instead of waiting for the 20s scheduler.
		if (caResyncPending)
		{
			caResyncPending = false;
			if (config.syncCombatAchievements() && syncAllowed()
				&& backoff.allowed(EP_COMBAT_ACHIEVEMENTS, System.currentTimeMillis()))
			{
				syncCombatAchievements();
			}
		}
		finishCollectionLogStream();
		tickAdventureLog();
	}

	/**
	 * The whole-log transmit arrives as a burst of per-item scripts with no "done" marker, so treat
	 * it as finished once two ticks pass with no new entry (the same settle used by WikiSync and
	 * RuneProfile) and hand the result to the sync queue. Client thread, from onGameTick.
	 */
	private void finishCollectionLogStream()
	{
		// Watchdog: if the request never produced a single entry (a game update moves the search
		// op, or the menu action is swallowed), stop waiting for it so the pages the player opens
		// are captured again. The next opening of the log asks once more; nothing retries before.
		if (clogRequested && clogAllTick < 0 && clogRequestTick >= 0
			&& client.getTickCount() - clogRequestTick > CLOG_REQUEST_TIMEOUT_TICKS)
		{
			clogRequested = false;
			clogRequestTick = -1;
			log.debug("RuneTools: collection log transmit never arrived - will ask again next open");
		}
		if (clogAllTick < 0 || client.getTickCount() - clogAllTick <= 2)
		{
			return;
		}
		clogAllTick = -1;
		clogRequested = false;   // the stream is done; page draws count again
		clogRequestTick = -1;
		if (CollectionLog.isOtherPlayers(client) || clogAll.isEmpty())
		{
			return;
		}
		JsonArray obtained = new JsonArray();
		for (Map.Entry<Integer, Integer> en : clogAll.entrySet())
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", en.getKey());
			if (en.getValue() != null && en.getValue() > 1)
			{
				o.addProperty("qty", en.getValue());
			}
			obtained.add(o);
		}
		synchronized (clogLock)
		{
			clogObtained = obtained;
			clogDirty = true;
		}
		if (panel != null)
		{
			if (parking.isNameParked(EP_COLLECTION_LOG, syncIdentity()))
			{
				panel.setStatus(SYNC_NAME_TAKEN_MSG, false);   // read, but it won't be sent as this character
			}
			else
			{
				panel.setStatus("Collection Log read: " + obtained.size() + " items.", true);
			}
		}
	}

	/**
	 * Throw away EVERYTHING captured from the collection log so far. Called when the log on screen
	 * turns out to be someone else's, and whenever the character context goes away.
	 *
	 * <p>It has to clear the queued pages too, not just the item stream: the varbit that says "this
	 * is the POH host's log" can land a cycle after the interface draws, so a page of THEIR items
	 * can already be sitting in the queue by the time we find out - and on a character switch, a
	 * page queued by the previous character would otherwise upload under the new one's key and rsn.
	 * clogSentHash goes as well, or the next character silently never uploads a page whose contents
	 * happen to hash the same (very common for content neither of them has started).
	 *
	 * <p>Bumping the generation invalidates any send already in flight, so a failed request can't
	 * put the discarded pages back afterwards.
	 */
	private void discardCollectionCapture()
	{
		clogAll.clear();
		clogAllTick = -1;
		clogRequested = false;
		clogAskedThisOpen = false;
		clogRequestTick = -1;
		synchronized (clogLock)
		{
			clogGeneration++;
			clogObtained = null;
			clogChanged.clear();
			clogChangedHash.clear();
			clogSentHash.clear();
			clogTotals = null;
			clogTotalsHash = 0;
			clogDirty = false;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		feedAdventureLog(e);
		if (e.getType() == ChatMessageType.GAMEMESSAGE)
		{
			String msg = e.getMessage() != null ? e.getMessage().toLowerCase() : "";
			// e.g. "Congratulations, you've completed a Hard combat task: ..."
			if (msg.contains("combat task") && msg.contains("complet") && isMainGame())
			{
				caResyncPending = true;
			}
			// "New item added to your collection log: ..." - the drop bumps the overall counters now;
			// the item's page detail syncs the next time you open that page.
			if (msg.contains("added to your collection log") && collectionLogSyncOn() && isMainGame())
			{
				refreshCollectionTotals();
				queueClogUnlock(e.getMessage());
			}
		}
	}

	/**
	 * Remember the item a "New item added to your collection log" message names, with the time it
	 * appeared, so the site's drop timeline shows it within a sync instead of the next time the log
	 * is opened, and at the moment it actually happened. The site only accepts names the wiki lists in
	 * the log. Client thread.
	 */
	private void queueClogUnlock(String message)
	{
		if (!collectionLogSyncOn() || !snapshot.get().hasIdentity())
		{
			return;
		}
		Matcher m = CLOG_NEW_ITEM.matcher(Text.removeTags(message != null ? message : ""));
		if (!m.find())
		{
			return;
		}
		String name = m.group(1).trim();
		while (name.endsWith("."))
		{
			name = name.substring(0, name.length() - 1).trim();
		}
		if (name.isEmpty() || name.length() > 80)
		{
			return;
		}
		JsonObject unlock = new JsonObject();
		unlock.addProperty("name", name);
		unlock.addProperty("ts", System.currentTimeMillis());
		String owner = syncIdentity();
		synchronized (clogLock)
		{
			if (!owner.equals(clogUnlocksOwner))
			{
				clogUnlocks.clear();   // anything still queued was another character's
				clogUnlocksOwner = owner;
			}
			if (clogUnlocks.size() < MAX_CLOG_UNLOCKS)
			{
				clogUnlocks.add(unlock);
			}
			clogDirty = true;
		}
	}

	/**
	 * One entry of the whole-log transmit: {@code args = {?, itemId, quantity}}. Fires once per
	 * obtained item after {@link CollectionLog#requestFullLog}. Client thread.
	 */
	private void collectTransmittedClogItem(ScriptPreFired e)
	{
		if (!collectionLogSyncOn() || !captureAllowed() || CollectionLog.isOtherPlayers(client))
		{
			return;
		}
		Object[] args = e.getScriptEvent() != null ? e.getScriptEvent().getArguments() : null;
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		clogAllTick = client.getTickCount();   // the stream is considered done a couple of ticks after the last one
		int id = (int) args[1];
		int qty = (int) args[2];
		if (id > 0 && clogAll.size() < CLOG_MAX_ITEMS)
		{
			clogAll.put(id, Math.max(0, qty));
		}
	}

	/**
	 * Whether anything read from the Collection Log can actually be synced: the setting is on, the
	 * player has consented and this character is connected. Nothing is read, and no request is made,
	 * otherwise.
	 */
	private boolean collectionLogSyncOn()
	{
		return running && config.syncCollectionLog() && hasKeyAndConsent();
	}

	/**
	 * Collection-log interface events. SETUP means the player just opened the log: ask the server
	 * for the whole thing, once per opening. DRAW means a page was rendered: capture it, which is
	 * what gives pages their names and per-page grouping.
	 *
	 * <p>Both bail out when the log on screen is someone else's, viewed through their POH Adventure
	 * Log, and when Collection Log syncing is off, unconsented or not connected. Client thread.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired e)
	{
		if (e.getScriptId() == CollectionLog.SETUP_SCRIPT)
		{
			if (!collectionLogSyncOn() || !captureAllowed())
			{
				return;
			}
			if (CollectionLog.isOtherPlayers(client))
			{
				discardCollectionCapture();   // theirs: drop anything the open queued
				return;
			}
			// Once per opening (requestFullLog itself re-fires SETUP, and the flag only resets when
			// the interface is opened or closed again).
			if (!clogAskedThisOpen && remoteConfig.on("clog_request"))
			{
				clogAskedThisOpen = true;
				clogRequested = true;
				clogRequestTick = client.getTickCount();
				clogAll.clear();
				CollectionLog.requestFullLog(client);
			}
			return;
		}
		if (e.getScriptId() != ScriptID.COLLECTION_DRAW_LIST || !collectionLogSyncOn() || !captureAllowed())
		{
			return;
		}
		if (CollectionLog.isOtherPlayers(client))
		{
			discardCollectionCapture();
			return;
		}
		if (clogRequested)
		{
			// Mid whole-log request: the search toggle repopulates the item panel, and a draw fired
			// now would be filed under whichever page happened to be open - which then rewrites that
			// page in the SHARED, cross-user item catalog on the server. The stream is carrying the
			// data anyway, so ignore draws until it settles.
			return;
		}
		CollectionLog.Page page = CollectionLog.readOpenPage(client, itemManager);
		JsonObject totals = CollectionLog.readTotals(client);
		synchronized (clogLock)
		{
			if (totals != null)
			{
				int th = totals.toString().hashCode();
				if (th != clogTotalsHash)
				{
					clogTotals = totals;
					clogTotalsHash = th;
					clogDirty = true;
				}
			}
			if (page != null)
			{
				Integer sent = clogSentHash.get(page.key);
				Integer queued = clogChangedHash.get(page.key);
				if ((sent == null || sent != page.hash) && (queued == null || queued != page.hash))
				{
					clogChanged.put(page.key, page.json);
					clogChangedHash.put(page.key, page.hash);
					clogDirty = true;
				}
			}
		}
		pushClogPanel();
	}

	/** Read the overall/per-tab collection-log counters (varps) on the client thread and refresh the UI. */
	private void refreshCollectionTotals()
	{
		clientThread.invoke(() ->
		{
			if (!captureAllowed() || client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			JsonObject totals = CollectionLog.readTotals(client);
			if (totals == null)
			{
				return;
			}
			synchronized (clogLock)
			{
				int th = totals.toString().hashCode();
				if (th != clogTotalsHash)
				{
					clogTotals = totals;
					clogTotalsHash = th;
					clogDirty = true;
				}
			}
			pushClogPanel();
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		ItemContainer c = e.getItemContainer();
		if (c == null || !captureAllowed())
		{
			return;
		}
		if (e.getContainerId() == InventoryID.WORN)
		{
			// What the character wears is owned gear too (best-in-slot "from my bank" counts it).
			final JsonArray eq = itemsToArray(c);
			if (!eq.equals(snapshot.get().equipment))
			{
				snapshot.updateAndGet(s -> s.toBuilder().equipment(eq).build());
				stateDirty.set(true);
			}
			return;
		}
		if (e.getContainerId() == InventoryID.INV)
		{
			chars.inventoryCoins = c.count(ItemID.COINS);
			final JsonArray inv = itemsToArray(c);
			final long gp = (long) chars.inventoryCoins + (long) chars.bankCoins;
			AccountSnapshot before = snapshot.get();
			if (inv.equals(before.inventory) && gp == before.gp)
			{
				return;   // same items (e.g. only rearranged): nothing new to upload
			}
			snapshot.updateAndGet(s -> s.toBuilder().inventory(inv).gp(gp).build());
			stateDirty.set(true);
		}
		else if (e.getContainerId() == InventoryID.BANK)
		{
			if (bankImportWaiting)
			{
				bankImportWaiting = false;
				layoutsEtag = null;   // the waiting import has to come back in full, not as a 304
				pollImportedLayouts();
			}
			chars.bankCoins = c.count(ItemID.COINS);
			final JsonArray bank = config.syncBank() ? itemsToArray(c) : null;
			final long gp = (long) chars.inventoryCoins + (long) chars.bankCoins;
			AccountSnapshot before = snapshot.get();
			if (gp == before.gp && (bank == null || bank.equals(before.bank)))
			{
				return;
			}
			snapshot.updateAndGet(s -> s.toBuilder().gp(gp).bank(bank != null ? bank : s.bank).build());
			stateDirty.set(true);
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
	{
		GrandExchangeOffer offer = e.getOffer();
		// At login/hop the client fires an EMPTY burst for ALL 8 slots (before LOGGED_IN), even
		// for occupied ones. Ignore those so they never wipe our persisted per-slot baselines;
		// a real in-game slot collection produces EMPTY while LOGGED_IN and is still handled.
		if (offer.getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (!captureAllowed())
		{
			return;   // another world's offers (Leagues, Deadman, ...) are never tracked or sent
		}

		AccountSnapshot snap = snapshot.get();
		String rsn = snap.rsn;
		String accountHash = snap.accountHash;
		if (rsn == null)
		{
			// A GE event can beat the first game tick; read identity directly as a fallback,
			// and remember it so later events (and state sync) have it too.
			Player p = client.getLocalPlayer();
			rsn = p != null ? p.getName() : null;
			long ah = client.getAccountHash();
			accountHash = ah == -1 ? null : Long.toString(ah);
			if (rsn != null && !rsn.isEmpty())
			{
				final String frsn = rsn;
				final String fhash = accountHash;
				snapshot.updateAndGet(s -> s.toBuilder().rsn(frsn).accountHash(fhash).build());
			}
		}

		// Queue the trade whenever we captured one - do NOT require an RSN here. The account hash says
		// whose fill it is (TradeGroups sends it with that character's own key); a missing RSN is filled
		// in at flush time, only from that same character. (Dropping on a momentarily-null RSN was
		// silently losing fills.)
		Trade t = chars.offers().process(e.getSlot(), offer, rsn, accountHash);
		if (t != null)
		{
			chars.session().record(t);
		}
		log.debug("RuneTools/GE: slot={} state={} qtySold={} spent={} syncTrades={} -> {}",
			e.getSlot(), offer.getState(), offer.getQuantitySold(), offer.getSpent(),
			config.syncTrades(),
			t == null ? "no-trade" : (t.getSide() + " " + t.getQty() + " @" + t.getPrice()));
		if (t != null && config.syncTrades() && config.consent())
		{
			queuePending(t);
			savePending();
			updatePanelStatic();
			log.debug("RuneTools: queued {} {} x item {} @ {}gp",
				t.getSide(), t.getQty(), t.getItemId(), t.getPrice());
			// A buy fill is what the site's holdings/P-L view is most often waiting on, so expedite the
			// flush instead of leaving it to the next 20s sweep.
			if ("buy".equals(t.getSide()) && syncAllowed())
			{
				flushTrades();
			}
		}

		rebuildOffers();
		updateTradesPanel();
		stateDirty.set(true);
	}

	private void updateIdentity()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// Ticks only fire in game, so this also opens the sync gate when the plugin is ENABLED
		// mid-session, where no GameStateChanged ever arrives to open it.
		loggedIn = true;
		mainGame = isMainGame();
		if (loggedInTick < 0)
		{
			loggedInTick = client.getTickCount();   // enabled mid-session: level-ups count from now
		}
		if (!mainGame)
		{
			if (!offWorldShown)
			{
				offWorldShown = true;
				updatePanelStatic();   // "RuneTools doesn't sync on this world."
			}
			return;   // nothing is captured on Leagues, Deadman and the like (see isMainGame)
		}
		offWorldShown = false;
		final String hash = currentHash();
		if (chars.adopt(hash))
		{
			onCharacterChanged();
		}
		Player p = client.getLocalPlayer();
		String name = p != null ? p.getName() : null;
		if (name == null || name.isEmpty() || hash == null)
		{
			return;
		}
		boolean firstIdentity = !identityAnnounced;
		identityAnnounced = true;
		final boolean members = client.getWorldType().contains(WorldType.MEMBERS);
		snapshot.updateAndGet(s -> s.toBuilder().rsn(name).accountHash(hash).members(members).build());
		if (firstIdentity)
		{
			setupManager.switchAccount(hash);   // this character's cached setups, never another's
			// Ensure at least one state upload after login even if nothing else changes.
			recomputeGpAndOffers();
			stateDirty.set(true);
			updatePanelStatic();
			updateTradesPanel();
			remindToConnect(name, hash);
			fetchRemoteConfig(true, null);
			// RSN only at DEBUG; never log the persistent account hash (a stable cross-session
			// correlator) to the on-disk client log users routinely share.
			log.debug("RuneTools: identity captured for {}", name);
		}
	}

	/**
	 * Once per session, a character with no RuneTools key gets a line in chat saying how to connect
	 * it, so it isn't forgotten. A connected character needs nothing: its key is kept between
	 * sessions and it syncs on its own from login. Nothing is said until consent is given.
	 */
	private void remindToConnect(String rsn, String hash)
	{
		if (hash == null || !config.consent() || keyForHash(hash) != null || !remindedToConnect.add(hash))
		{
			return;
		}
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("RuneTools: ")
			.append(ChatColorType.NORMAL).append(Text.escapeJagex(rsn) + " isn't connected. Open the RuneTools panel "
				+ "and press Connect to RuneTools.")
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(msg).build());
	}

	private void recomputeGpAndOffers()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		final JsonArray invArr = inv != null ? itemsToArray(inv) : null;
		if (inv != null)
		{
			chars.inventoryCoins = inv.count(ItemID.COINS);
		}
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		JsonArray bankArr = null;
		if (bank != null)
		{
			chars.bankCoins = bank.count(ItemID.COINS);
			bankArr = config.syncBank() ? itemsToArray(bank) : null;
		}
		final JsonArray bankJson = bankArr;
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final JsonArray wornArr = worn != null ? itemsToArray(worn) : null;
		final long gp = (long) chars.inventoryCoins + (long) chars.bankCoins;
		snapshot.updateAndGet(s -> s.toBuilder()
			.inventory(invArr != null ? invArr : s.inventory)
			.bank(bankJson != null ? bankJson : s.bank)
			.equipment(wornArr != null ? wornArr : s.equipment)
			.gp(gp)
			.build());
		rebuildOffers();
	}

	private void rebuildOffers()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		JsonArray arr = new JsonArray();
		int free = 0;
		if (offers != null)
		{
			for (int slot = 0; slot < offers.length; slot++)
			{
				GrandExchangeOffer o = offers[slot];
				if (o == null || o.getState() == GrandExchangeOfferState.EMPTY)
				{
					free++;
					continue;
				}
				JsonObject j = new JsonObject();
				j.addProperty("slot", slot);
				j.addProperty("item_id", o.getItemId());
				j.addProperty("side", OfferTracker.isBuy(o.getState()) ? "buy" : "sell");
				j.addProperty("state", o.getState().name().toLowerCase());
				j.addProperty("price", o.getPrice());
				j.addProperty("qty", o.getTotalQuantity());
				j.addProperty("filled", o.getQuantitySold());
				j.addProperty("spent", o.getSpent());
				arr.add(j);
			}
		}
		final JsonArray offersArr = arr;
		final int freeSlots = free;
		snapshot.updateAndGet(s -> s.toBuilder().offers(offersArr).freeSlots(freeSlots).build());
		activeOffers = arr.size();
	}

	private static JsonArray itemsToArray(ItemContainer c)
	{
		JsonArray arr = new JsonArray();
		Map<Integer, Long> agg = new LinkedHashMap<>();
		for (Item it : c.getItems())
		{
			int id = it.getId();
			if (id <= 0)
			{
				continue;
			}
			agg.merge(id, (long) it.getQuantity(), Long::sum);
		}
		for (Map.Entry<Integer, Long> en : agg.entrySet())
		{
			JsonObject o = new JsonObject();
			o.addProperty("item_id", en.getKey());
			o.addProperty("qty", en.getValue());
			arr.add(o);
		}
		return arr;
	}

	// -- Adventurer's Log (client thread unless noted; see AdventureLog) ------ //

	/**
	 * Whether achievements are watched at all: some category is on, the player consented, this
	 * character is connected and in game, and the world is the main game (not Leagues, Deadman, a
	 * beta or tournament world and so on, whose progress isn't the character's own).
	 */
	private boolean adventureLogOn()
	{
		if (!(config.logLevels() || config.logQuests() || config.logCombat() || config.logPets() || config.logDrops()
			|| config.logClues()))
		{
			return false;
		}
		if (!running || !hasKeyAndConsent() || !snapshot.get().hasIdentity()
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		return isMainGame();
	}

	/** Hand the game's own messages to the detector. Messages other plugins print are ignored. */
	private void feedAdventureLog(ChatMessage e)
	{
		ChatMessageType type = e.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.MESBOX
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION && type != ChatMessageType.CLAN_MESSAGE
			&& type != ChatMessageType.CLAN_GIM_MESSAGE && type != ChatMessageType.CLAN_GUEST_MESSAGE)
		{
			return;
		}
		if (!adventureLogOn())
		{
			return;
		}
		String source = e.getName() != null && !e.getName().isEmpty() ? e.getName() : e.getSender();
		if ("runelite".equalsIgnoreCase(source))
		{
			return;   // a plugin's own chat line, not the game's
		}
		String raw = e.getMessage() != null ? e.getMessage() : "";
		String text = Text.removeTags(raw.replace("<br>", "\n")).replace(' ', ' ').trim();
		long now = System.currentTimeMillis();
		if (type == ChatMessageType.CLAN_MESSAGE || type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE)
		{
			adventureLog.onClanMessage(text, snapshot.get().rsn);
		}
		else
		{
			adventureLog.onGameMessage(text, now);
		}
	}

	/**
	 * A skill's real level may have gone up. Compared with what was read after login, so loading
	 * stats, boosts and drains never count; only real levels up to 99 are levels.
	 */
	private void trackLevel(Skill skill)
	{
		if (levelBaseline == null || skill == null || "Overall".equals(skill.getName()) || !adventureLogOn())
		{
			return;
		}
		String name = skill.getName();
		int now = client.getRealSkillLevel(skill);
		Integer before = levelBaseline.get(name);
		Integer xpBefore = levelBaselineXp.get(name);
		levelBaseline.put(name, now);
		levelBaselineXp.put(name, client.getSkillExperience(skill));
		// A big jump from a skill that had no XP at all is its real level arriving late, not play. A
		// big jump from real XP is real (a quest reward can lift a low skill many levels at once).
		if (before == null || now <= before
			|| (now - before > LEVEL_RESYNC_JUMP && (xpBefore == null || xpBefore <= 0)))
		{
			return;   // first sight, no gain, or stats still settling
		}
		int total = 0;
		boolean maxed = true;
		for (int lvl : levelBaseline.values())
		{
			total += lvl;
			maxed &= lvl >= 99;
		}
		adventureLog.onLevelUp(name, before, Math.min(99, now), total, maxed && before < 99,
			System.currentTimeMillis());
	}

	/** Read every skill's real level once stats have loaded after login. */
	private void initLevelBaseline()
	{
		if (levelBaseline != null || loggedInTick < 0 || client.getTickCount() - loggedInTick < LEVEL_BASELINE_TICKS)
		{
			return;
		}
		if (client.getRealSkillLevel(Skill.HITPOINTS) < 10)
		{
			return;   // not loaded yet: every character has at least 10 Hitpoints
		}
		Map<String, Integer> base = new HashMap<>();
		Map<String, Integer> xp = new HashMap<>();
		for (Skill sk : Skill.values())
		{
			if (!"Overall".equals(sk.getName()))
			{
				base.put(sk.getName(), client.getRealSkillLevel(sk));
				xp.put(sk.getName(), client.getSkillExperience(sk));
			}
		}
		levelBaselineXp = xp;
		levelBaseline = base;
	}

	/** Per tick: finish half-seen achievements, queue what's done, and send once a tick's worth has settled. */
	private void tickAdventureLog()
	{
		if (!adventureLogOn())
		{
			adventureLog.reset();
			adventureLog.drain();   // nothing is kept while the log is off
			return;
		}
		initLevelBaseline();
		adventureLog.onTick(client.getTickCount());
		if (adventureLog.hasReady())
		{
			queueAchievements(adventureLog.drain());
		}
		boolean due;
		synchronized (achievements)
		{
			due = !achievements.isEmpty() && client.getTickCount() - achievementsQueuedTick >= ACHIEVEMENTS_SETTLE_TICKS;
		}
		if (due)
		{
			flushAchievements();
		}
	}

	/** Queue finished achievements under the character that earned them; another character's are dropped. */
	private void queueAchievements(List<JsonObject> events)
	{
		String owner = syncIdentity();
		synchronized (achievements)
		{
			if (!owner.equals(achievementsOwner))
			{
				achievements.clear();
				achievementsOwner = owner;
			}
			if (achievements.isEmpty())
			{
				achievementsQueuedTick = client.getTickCount();
			}
			achievements.addAll(events);
			while (achievements.size() > MAX_ACHIEVEMENTS_QUEUED)
			{
				achievements.remove(0);
			}
		}
	}

	/**
	 * Send the oldest queued achievements, one request at a time. Any thread (the tick and the 20s
	 * sweep both call it). Gated like the rest of the background loop, and by this endpoint's own
	 * backoff; a refusal the server will never accept is dropped, anything else stays queued.
	 */
	private void flushAchievements()
	{
		if (!syncAllowed() || !backoff.allowed(EP_ACHIEVEMENTS, System.currentTimeMillis()) || !uploadsOn("achievements"))
		{
			return;
		}
		final String identity = syncIdentity();
		final List<JsonObject> batch;
		synchronized (achievements)
		{
			if (achievements.isEmpty() || !identity.equals(achievementsOwner))
			{
				return;
			}
			batch = new ArrayList<>(achievements.subList(0, Math.min(ACHIEVEMENTS_BATCH, achievements.size())));
		}
		if (parking.isNameParked(EP_ACHIEVEMENTS, identity) || !achievementsInFlight.compareAndSet(false, true))
		{
			return;
		}
		JsonArray events = new JsonArray();
		for (JsonObject ev : batch)
		{
			events.add(ev);
		}
		JsonObject body = new JsonObject();
		stampIdentity(body);
		body.add("events", events);
		final long payload = events.toString().hashCode();
		if (parking.isParked(EP_ACHIEVEMENTS, identity, payload))
		{
			dropAchievements(batch);   // exactly these were refused for good before
			achievementsInFlight.set(false);
			return;
		}
		api.postAchievements(body, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				achievementsInFlight.set(false);
				noteFailure(EP_ACHIEVEMENTS, payload);
				log.debug("RuneTools: achievements sync failed (will retry): {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					SyncResponse.Outcome outcome = noteSyncResult(r, EP_ACHIEVEMENTS, identity, payload,
						SyncResponse.Shape.OK_TRUE, 0, false);
					if (outcome == SyncResponse.Outcome.OK || outcome == SyncResponse.Outcome.PAYLOAD_REJECTED)
					{
						dropAchievements(batch);
					}
					else
					{
						log.debug("RuneTools: achievements sync HTTP {} (kept queued)", r.code());
					}
				}
				finally
				{
					achievementsInFlight.set(false);
				}
			}
		});
	}

	private void dropAchievements(List<JsonObject> sent)
	{
		synchronized (achievements)
		{
			achievements.removeAll(sent);
		}
	}

	// -- upload (scheduler thread; OkHttp enqueue is async, never blocks) ---- //

	@Schedule(period = 20, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void sync()
	{
		if (!running)
		{
			return;
		}
		if (loggedIn && mainGame && config.consent())
		{
			fetchRemoteConfig(false, null);   // the site's settings, every half hour (needs no key)
		}
		if (!syncAllowed())
		{
			return;   // login screen, another world, no key for this character, no consent, or the key was rejected
		}
		long now = System.currentTimeMillis();
		if (now - lastSweepAt < remoteConfig.limitMs("sync_s") - 1_000L)
		{
			return;   // the site asked for a slower pace than every 20 seconds
		}
		lastSweepAt = now;
		syncSweep.incrementAndGet();   // a rejected key is counted once per sweep
		flushTrades();
		flushState();
		pollRemoteIfDue();             // setups + imported layouts, on their own slower schedule
		ensureLiveUpdates();           // and the request the site answers the moment one is saved
		if (config.syncCombatAchievements())
		{
			syncCombatAchievements();
		}
		if (config.syncCollectionLog())
		{
			refreshCollectionTotals();   // keep overall progress fresh even if the log isn't open
			syncCollectionLog();
		}
		flushAchievements();   // anything a failed send left queued (normally sent from the tick)
	}

	// Live updates: one request held open on the site, answered the moment a setup or bank layout is
	// saved there (see RuneToolsApiClient.waitForChanges). Started from the sync loop, re-armed after
	// every answer (never sooner than live_gap_s after the last one started, so a proxy that answers
	// at once can't make the client loop), and stopped by the same gate as every other sync.
	private final AtomicBoolean liveInFlight = new AtomicBoolean();
	private final AtomicInteger liveFailures = new AtomicInteger();
	private volatile String liveSetupsTag = "";
	private volatile String liveLayoutsTag = "";
	private volatile long liveRetryAt;
	private volatile long liveNextAt;

	private void ensureLiveUpdates()
	{
		long now = System.currentTimeMillis();
		if (!running || !config.syncSetups() || !remoteConfig.on("live") || !syncAllowed()
			|| now < liveRetryAt || now < liveNextAt || !liveInFlight.compareAndSet(false, true))
		{
			return;
		}
		liveNextAt = now + remoteConfig.limitMs("live_gap_s");
		final String identity = syncIdentity();
		api.waitForChanges(liveSetupsTag, liveLayoutsTag, lastConfigTag, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				liveInFlight.set(false);
				if (running && (call == null || !call.isCanceled()))
				{
					liveBackoff(0);   // a cancel is a character switch or logout, not a failure
				}
				log.debug("RuneTools: live updates paused: {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				boolean again = false;
				try (Response r = resp)
				{
					if (!running || !identity.equals(syncIdentity()))
					{
						return;   // asked for another character: its answer means nothing now
					}
					if (r.code() == 204)
					{
						again = true;   // nothing saved meanwhile: ask again
					}
					else if (r.isSuccessful())
					{
						String b = RuneToolsApiClient.readBoundedBody(r);
						if (!SyncResponse.confirms(SyncResponse.Shape.OBJECT, b, 0))
						{
							liveBackoff(0);
						}
						else
						{
							JsonObject o = new JsonParser().parse(b).getAsJsonObject();
							liveSetupsTag = str(o, "setups_tag", liveSetupsTag);
							liveLayoutsTag = str(o, "layouts_tag", liveLayoutsTag);
							// Kept as sent, like the other two tags, and only once the config was fetched,
							// so a change the one-minute gap held back is fetched on a later answer.
							String configTag = str(o, "config_tag", null);
							if (configTag != null && configTag.length() <= MAX_CONFIG_TAG
								&& !configTag.equals(lastConfigTag))
							{
								fetchRemoteConfig(true, configTag);
							}
							if (isTrue(o, "setups"))
							{
								setupManager.poll();
							}
							if (isTrue(o, "layouts"))
							{
								pollImportedLayouts();
							}
							again = true;
						}
					}
					else if (r.code() == 429)
					{
						long wait = SyncResponse.retryAfterMillis(r.header("Retry-After"), System.currentTimeMillis(),
							RETRY_AFTER_MAX_MS);
						if (wait > 0)
						{
							retryAfterUntilMillis.accumulateAndGet(System.currentTimeMillis() + wait, Math::max);
						}
						liveBackoff(wait);
					}
					else
					{
						liveBackoff(0);   // a rejected key or an outage: the sync loop reports those
					}
					if (again)
					{
						liveFailures.set(0);
					}
				}
				catch (Exception ex)
				{
					liveBackoff(0);
				}
				finally
				{
					liveInFlight.set(false);
				}
				if (again)
				{
					rearmLive();
				}
			}
		});
	}

	/** Ask again as soon as live_gap_s allows. */
	private void rearmLive()
	{
		if (!running)
		{
			return;
		}
		long delay = Math.max(0L, liveNextAt - System.currentTimeMillis());
		if (delay == 0)
		{
			ensureLiveUpdates();
		}
		else
		{
			executor.schedule(this::ensureLiveUpdates, delay, TimeUnit.MILLISECONDS);
		}
	}

	/** After a failed wait: try again in 15 s, then 30, 60... up to 5 minutes, or what a 429 asked. */
	private void liveBackoff(long atLeastMs)
	{
		int n = liveFailures.incrementAndGet();
		long wait = Math.min(300_000L, 15_000L << Math.min(n - 1, 5));
		liveRetryAt = System.currentTimeMillis() + Math.max(wait, atLeastMs);
	}

	/**
	 * Ask the site for setup and bank-layout changes, if {@link #remotePoll} says one is due. Both
	 * requests are ETag polls (a 304 when nothing changed) and are only queued here, so this returns
	 * at once and is safe from any thread. Gated like the rest of the background loop, and each by its
	 * own endpoint's backoff.
	 */
	private void pollRemoteIfDue()
	{
		if (!running || !config.syncSetups() || !syncAllowed())
		{
			return;
		}
		if (!remotePoll.tryStart(System.currentTimeMillis()))
		{
			return;
		}
		setupManager.poll();             // full pull + ETag -> 304 when unchanged
		pollImportedLayouts();           // apply bank layouts imported on the site
	}

	/**
	 * The player is about to use synced data (opened the side panel or the bank): poll now, or as soon
	 * as {@code minGap} has passed since the last poll, instead of waiting out the backoff.
	 */
	private void requestRemotePoll(long minGap)
	{
		remotePoll.pollSoon(System.currentTimeMillis(), minGap);
		pollRemoteIfDue();
	}

	/**
	 * Gate for the BACKGROUND loop: there has to be something to sync (a character in game on a
	 * main-game world, its name and account hash known, a key for that character, consent), the key
	 * must not already have been rejected, and the server must not have asked us to wait (a 429's
	 * Retry-After). Without the in-game check a client parked on the login screen posted every 20s
	 * forever. User-initiated actions use {@link #hasKeyAndConsent()} plus their own checks.
	 */
	private boolean syncAllowed()
	{
		return running && loggedIn && mainGame && !authRevoked && snapshot.get().hasIdentity()
			&& System.currentTimeMillis() >= retryAfterUntilMillis.get() && hasKeyAndConsent();
	}

	/**
	 * Clear the rejected-key halt. A 429's Retry-After is left alone (the rate limit is per IP, so it
	 * outlasts a character switch or a new key), and so is each endpoint's backoff.
	 */
	private void resumeSync()
	{
		authFailures.set(0);
		authRevoked = false;
	}

	/** Whether an upload may go out: the site hasn't switched it off and this build isn't too old. */
	private boolean uploadsOn(String feature)
	{
		return remoteConfig.on(feature) && !writesPaused();
	}

	/** The site said this build is older than it accepts writes from (min_version). */
	private boolean writesPaused()
	{
		return remoteConfig.tooOld(PluginVersion.VERSION);
	}

	/** A request that got no answer at all: that endpoint backs off. */
	private void noteFailure(String endpoint, long payload)
	{
		backoff.failed(endpoint, payload, false, System.currentTimeMillis(),
			remoteConfig.limitMs("sync_s"), remoteConfig.limitMs("backoff_max_s"));
	}

	/**
	 * Every background response funnels through here. See {@link SyncResponse} for how each status is
	 * read; a 2xx counts only in {@code shape} ({@code sent} is what a trades answer must confirm).
	 *
	 * <ul>
	 *   <li>OK clears this endpoint's backoff and any refusal parked for it.</li>
	 *   <li>A name or limit refusal (409, 403 {@code rsn_taken}) holds the endpoint for this identity
	 *       until the character or key changes, with the server's words for the panel; a 400/413
	 *       holds that exact payload. Neither is an outage, so neither backs off.</li>
	 *   <li>Everything else backs this endpoint off on its own. The same payload failing with a 500
	 *       {@link EndpointBackoff#GIVE_UP_AFTER} times over half an hour is given up on (parked,
	 *       returned as PAYLOAD_REJECTED so the caller treats it like a refused body). A request with
	 *       no payload (payload 0: the setups and layouts pulls) is never given up on, only backed off.</li>
	 *   <li>A rejected key counts toward stopping the loop, but only for the character in game:
	 *       {@code foreignKey} marks another character's key (a queued trade of an alt), whose
	 *       rejection only holds that upload.</li>
	 * </ul>
	 */
	private SyncResponse.Outcome noteSyncResult(Response r, String endpoint, String identity, long payload,
		SyncResponse.Shape shape, int sent, boolean foreignKey)
	{
		int code = r.code();
		String body = code == 304 ? "" : RuneToolsApiClient.bodyOrEmpty(r);
		SyncResponse.Outcome outcome = SyncResponse.classify(code, body, shape, sent);
		return noteOutcome(outcome, code, body, r.header("Retry-After"), endpoint, identity, payload, foreignKey);
	}

	private SyncResponse.Outcome noteOutcome(SyncResponse.Outcome outcome, int code, String body, String retryAfter,
		String endpoint, String identity, long payload, boolean foreignKey)
	{
		long now = System.currentTimeMillis();
		long base = remoteConfig.limitMs("sync_s");
		long max = remoteConfig.limitMs("backoff_max_s");
		switch (outcome)
		{
			case OK:
				backoff.succeeded(endpoint);
				parking.release(endpoint, identity);
				if (!foreignKey)
				{
					boolean wasRevoked = authRevoked;
					resumeSync();
					panel.setLastSync(nowString());
					// A sync that worked means any red status (a key that stopped working, the site
					// unreachable a moment ago) no longer holds: put it back to "Connected as ...".
					if (wasRevoked || panel.isStatusError())
					{
						updatePanelStatic();
					}
				}
				break;
			case NAME_TAKEN:
				parking.parkName(endpoint, identity);
				updatePanelStatic();
				log.debug("RuneTools: {} refused (HTTP {}) - this character's name is linked to another RuneTools"
					+ " account; holding it until the character or key changes", endpoint, code);
				break;
			case REFUSED:
				parking.parkName(endpoint, identity, SyncResponse.errorText(body));
				updatePanelStatic();
				log.debug("RuneTools: {} refused (HTTP {}) - holding it until the character or key changes", endpoint, code);
				break;
			case PAYLOAD_REJECTED:
				parking.parkPayload(endpoint, identity, payload);
				log.debug("RuneTools: {} rejected the payload (HTTP {}) - holding it until it changes", endpoint, code);
				break;
			case RATE_LIMITED:
				long wait = SyncResponse.retryAfterMillis(retryAfter, now, RETRY_AFTER_MAX_MS);
				if (wait > 0)
				{
					retryAfterUntilMillis.accumulateAndGet(now + wait, Math::max);
					log.debug("RuneTools: rate limited - server asked for {}s", wait / 1000L);
				}
				backoff.failed(endpoint, payload, false, now, Math.max(base, wait), max);
				break;
			case KEY_REJECTED:
				backoff.failed(endpoint, payload, false, now, base, max);
				if (foreignKey)
				{
					parking.parkName(endpoint, identity);   // that character's key: held until it is reconnected
				}
				else
				{
					chargeKeyRejected();
				}
				break;
			default:
				if (!foreignKey)
				{
					authFailures.set(0);   // "consecutive" rejections: any other answer breaks the streak
				}
				if (backoff.failed(endpoint, payload, payload != 0L && SyncResponse.serverError(code), now, base, max))
				{
					parking.parkPayload(endpoint, identity, payload);
					log.debug("RuneTools: {} failed {} times with the same payload - giving up on it", endpoint,
						EndpointBackoff.GIVE_UP_AFTER);
					return SyncResponse.Outcome.PAYLOAD_REJECTED;
				}
				log.debug("RuneTools: {} failed (HTTP {}) - backing off", endpoint, code);
				break;
		}
		return outcome;
	}

	/** One rejected-key answer, counted once per sweep (a sweep sends several requests). */
	private void chargeKeyRejected()
	{
		long sweep = syncSweep.get();
		if (authChargedSweep.getAndSet(sweep) == sweep)
		{
			return;
		}
		if (authFailures.incrementAndGet() >= SYNC_AUTH_FAILURES_MAX && !authRevoked)
		{
			// A revoked key never heals on its own: stop, and put the fix in the panel instead of
			// posting a dead key at the server until the client is closed.
			authRevoked = true;
			updatePanelStatic();
			log.warn("RuneTools: sync stopped after {} rejected sweeps - reconnect this character",
				SYNC_AUTH_FAILURES_MAX);
		}
	}

	/**
	 * Who a background request goes out as: the character (name + account hash) and the key it
	 * authenticates with. Parks are scoped to this, so another character, a rename or a newly-issued
	 * key always gets a fresh try. Only the key's hash is kept.
	 */
	private static String syncIdentity(String rsn, String accountHash, String key)
	{
		return (rsn != null ? rsn : "") + '|' + (accountHash != null ? accountHash : "") + '|'
			+ Integer.toHexString((key != null ? key : "").hashCode());
	}

	/** {@link #syncIdentity(String, String, String)} for the character logged in right now. */
	private String syncIdentity()
	{
		AccountSnapshot s = snapshot.get();
		return syncIdentity(s.rsn, s.accountHash, api.activeKey());
	}

	/** Assemble the panel's Combat Achievements view from the last cache read. */
	private void pushCaPanel()
	{
		CombatAchievements.Snapshot snap = lastCaSnapshot;
		if (snap == null || panel == null)
		{
			return;
		}
		int totalDone = 0, total = 0, earned = snap.totalEarnedPts(), possible = 0;
		List<RuneToolsPanel.CaTierRow> rows = new ArrayList<>();
		for (int i = 0; i < CombatAchievements.TIER_LABELS.length; i++)
		{
			totalDone += snap.tierDone[i];
			total += snap.tierTotal[i];
			possible += snap.tierPossiblePts[i];
			rows.add(new RuneToolsPanel.CaTierRow(CombatAchievements.TIER_LABELS[i],
				snap.tierDone[i], snap.tierTotal[i], snap.tierEarnedPts[i], snap.tierPossiblePts[i]));
		}
		String overall = totalDone + "/" + total + " tasks · " + earned + "/" + possible + " points";
		String next = null;
		int[] th = caThresholds;
		if (th != null)
		{
			for (int i = 0; i < th.length; i++)
			{
				if (th[i] > 0 && earned < th[i])
				{
					next = (th[i] - earned) + " points to complete " + CombatAchievements.TIER_LABELS[i];
					break;
				}
			}
		}

		panel.setCaProgress(overall, next, rows);
	}

	/** POST any collection-log totals/pages changed since the last successful sync. Scheduler thread. */
	private void syncCollectionLog()
	{
		if (!backoff.allowed(EP_COLLECTION_LOG, System.currentTimeMillis()) || !uploadsOn("clog"))
		{
			return;   // kept queued
		}
		JsonObject totals;
		JsonArray obtained;
		// Key -> page, kept together in ONE map: these two used to be a values() list and a separate
		// hash map zipped by position on retry, which re-filed pages under each other's keys the
		// moment a send failed.
		final Map<String, JsonObject> sentPages = new LinkedHashMap<>();
		final Map<String, Integer> sentHashes = new HashMap<>();
		final List<JsonObject> sentUnlocks = new ArrayList<>();
		final int generation;
		final String identity = syncIdentity();
		synchronized (clogLock)
		{
			if (!clogDirty)
			{
				return;
			}
			if (parking.isNameParked(EP_COLLECTION_LOG, identity))
			{
				return;   // the name is linked to another account: keep it all queued for another character/key
			}
			generation = clogGeneration;
			totals = clogTotals;
			obtained = clogObtained;
			// Announced items go only as the character that saw them; anyone else's are dropped.
			if (identity.equals(clogUnlocksOwner))
			{
				sentUnlocks.addAll(clogUnlocks);
			}
			clogUnlocks.clear();
			for (Map.Entry<String, JsonObject> en : clogChanged.entrySet())
			{
				sentPages.put(en.getKey(), en.getValue());
				Integer h = clogChangedHash.get(en.getKey());
				if (h != null)
				{
					sentHashes.put(en.getKey(), h);
				}
			}
			// Optimistically dequeue; re-queue on failure so a page is never silently lost.
			clogChanged.clear();
			clogChangedHash.clear();
			clogObtained = null;
			clogDirty = false;
		}
		List<JsonObject> pages = new ArrayList<>(sentPages.values());
		if (totals == null && pages.isEmpty() && obtained == null && sentUnlocks.isEmpty())
		{
			return;
		}
		JsonObject body = new JsonObject();
		stampIdentity(body);
		if (totals != null)
		{
			body.add("totals", totals);
		}
		JsonArray arr = new JsonArray();
		for (JsonObject p : pages)
		{
			arr.add(p);
		}
		body.add("pages", arr);
		// The complete obtained set from the whole-log transmit. Pages carry the names and grouping
		// for whatever the player has actually opened; this carries everything, and the site fills
		// the rest of the pages in from it.
		if (obtained != null)
		{
			body.add("obtained", obtained);
		}
		// Items the game announced since the last sync, with when: they reach the drop timeline at once.
		if (!sentUnlocks.isEmpty())
		{
			JsonArray unlocks = new JsonArray();
			for (JsonObject u : sentUnlocks)
			{
				unlocks.add(u);
			}
			body.add("new_items", unlocks);
		}
		final JsonArray sentObtained = obtained;
		final long payload = body.toString().hashCode();
		if (parking.isParked(EP_COLLECTION_LOG, identity, payload))
		{
			// The server already refused exactly this. Keep it queued, unsent: a newly-read page
			// changes the payload and earns another try.
			requeueCollectionPages(generation, sentPages, sentHashes, sentObtained);
			requeueUnlocks(identity, sentUnlocks);
			return;
		}
		api.postCollectionLog(body, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				requeueCollectionPages(generation, sentPages, sentHashes, sentObtained);
				requeueUnlocks(identity, sentUnlocks);
				noteFailure(EP_COLLECTION_LOG, payload);
				log.debug("RuneTools: collection-log sync failed (will retry): {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					SyncResponse.Outcome outcome = noteSyncResult(r, EP_COLLECTION_LOG, identity, payload,
						SyncResponse.Shape.OK_TRUE, 0, false);
					if (outcome == SyncResponse.Outcome.OK)
					{
						synchronized (clogLock)
						{
							clogSentHash.putAll(sentHashes);   // don't re-send these unchanged pages
						}
					}
					else
					{
						requeueCollectionPages(generation, sentPages, sentHashes, sentObtained);
						if (outcome != SyncResponse.Outcome.PAYLOAD_REJECTED)
						{
							requeueUnlocks(identity, sentUnlocks);   // a refused body won't improve by resending
						}
						log.debug("RuneTools: collection-log sync HTTP {}", r.code());
					}
				}
			}
		});
	}

	/**
	 * Put pages back on the queue after a failed send so the next tick retries them. Each page goes
	 * back under its OWN key with its OWN hash, and a newer read of the same page always wins.
	 */
	private void requeueCollectionPages(int generation, Map<String, JsonObject> pages,
										Map<String, Integer> hashes, JsonArray obtained)
	{
		synchronized (clogLock)
		{
			if (generation != clogGeneration)
			{
				// The queue was discarded while this request was in flight (someone else's log, a
				// logout, a character switch). Putting it back would undo exactly that.
				return;
			}
			for (Map.Entry<String, JsonObject> en : pages.entrySet())
			{
				String key = en.getKey();
				if (clogChanged.containsKey(key))
				{
					continue;   // a newer read of this page is already queued
				}
				Integer sent = clogSentHash.get(key);
				Integer mine = hashes.get(key);
				if (sent != null && mine != null && !sent.equals(mine))
				{
					continue;   // a newer read of this page already made it to the server
				}
				clogChanged.put(key, en.getValue());
				Integer h = hashes.get(key);
				if (h != null)
				{
					clogChangedHash.put(key, h);
				}
			}
			if (obtained != null && clogObtained == null)
			{
				clogObtained = obtained;
			}
			clogDirty = true;
		}
	}

	/**
	 * Put announced items back after a failed send, ahead of any announced since, as long as the same
	 * character is still the one queuing them.
	 */
	private void requeueUnlocks(String identity, List<JsonObject> unlocks)
	{
		if (unlocks.isEmpty())
		{
			return;
		}
		synchronized (clogLock)
		{
			if (clogUnlocksOwner != null && !identity.equals(clogUnlocksOwner))
			{
				return;   // someone else is playing now: these were never theirs to send
			}
			clogUnlocksOwner = identity;
			List<JsonObject> merged = new ArrayList<>(unlocks);
			merged.addAll(clogUnlocks);
			clogUnlocks.clear();
			clogUnlocks.addAll(merged.subList(0, Math.min(merged.size(), MAX_CLOG_UNLOCKS)));
			clogDirty = true;
		}
	}

	/** Render the panel's Collection Log section from the latest totals. */
	private void pushClogPanel()
	{
		JsonObject t = clogTotals;
		if (t == null || panel == null)
		{
			return;
		}
		int obtained = t.has("obtained") ? t.get("obtained").getAsInt() : 0;
		int total = t.has("total") ? t.get("total").getAsInt() : 0;
		List<RuneToolsPanel.ClogTabRow> rows = new ArrayList<>();
		JsonArray tabs = t.getAsJsonArray("tabs");
		if (tabs != null)
		{
			for (JsonElement e : tabs)
			{
				JsonObject o = e.getAsJsonObject();
				rows.add(new RuneToolsPanel.ClogTabRow(
					o.get("name").getAsString(), o.get("obtained").getAsInt(), o.get("total").getAsInt()));
			}
		}
		int syncedPages;
		synchronized (clogLock)
		{
			syncedPages = clogSentHash.size() + clogChanged.size();
		}
		panel.setCollectionLog(obtained, total, rows, syncedPages);
	}

	/**
	 * Read Combat Achievements from the game cache and push them to the site's planner. The catalogue
	 * is sent once per session; completion is re-sent only when it actually changes (hash guard).
	 */
	private void syncCombatAchievements()
	{
		clientThread.invoke(() ->
		{
			if (!running || client.getGameState() != GameState.LOGGED_IN || !captureAllowed())
			{
				return;
			}
			CombatAchievements.Snapshot snap = CombatAchievements.read(client);
			if (snap == null)
			{
				return;   // CA cache not resolved yet
			}
			lastCaSnapshot = snap;
			caThresholds = CombatAchievements.readTierThresholds(client);
			pushCaPanel();
			if (!syncAllowed() || !backoff.allowed(EP_COMBAT_ACHIEVEMENTS, System.currentTimeMillis())
				|| !uploadsOn("ca"))
			{
				return;   // shown in the panel; sent once the endpoint may go again
			}
			boolean sendCatalog = !caCatalogSent;
			if (!sendCatalog && snap.completedHash == caCompletedHash)
			{
				return;   // nothing changed since the last successful post
			}
			// What this post would carry, cheaply: the catalogue (~145 KB) or not, plus the completion
			// state. Checked before building the body, so a refused catalogue costs nothing per sweep.
			final String identity = syncIdentity();
			final long payload = ((long) snap.completedHash << 1) | (sendCatalog ? 1L : 0L);
			if (parking.isParked(EP_COMBAT_ACHIEVEMENTS, identity, payload))
			{
				return;   // already refused for this character (name) or for exactly this content
			}
			JsonObject body = new JsonObject();
			stampIdentity(body);
			if (sendCatalog)
			{
				body.add("tasks", snap.tasks);
			}
			body.add("completed", snap.completed);
			if (snap.unknown.size() > 0)
			{
				body.add("unknown", snap.unknown);   // completion this build can't read (see CombatAchievements)
			}
			body.add("tiers", snap.tiers);
			final int hash = snap.completedHash;
			api.postCombatAchievements(body, new Callback()
			{
				@Override
				public void onFailure(Call call, IOException ex)
				{
					noteFailure(EP_COMBAT_ACHIEVEMENTS, payload);
					log.debug("RuneTools: CA sync failed: {}", ex.getMessage());
				}

				@Override
				public void onResponse(Call call, Response resp)
				{
					try (Response r = resp)
					{
						SyncResponse.Outcome outcome = noteSyncResult(r, EP_COMBAT_ACHIEVEMENTS, identity, payload,
							SyncResponse.Shape.OK_TRUE, 0, false);
						if (outcome == SyncResponse.Outcome.OK && identity.equals(syncIdentity()))
						{
							caCatalogSent = true;
							caCompletedHash = hash;
						}
					}
				}
			});
		});
	}

	/**
	 * Pull the user's bank layouts and apply any newly-imported ones (imported on the site) as
	 * in-game Bank Tags tabs. Tracks applied ids in config so each import is applied exactly once,
	 * and never re-applies the user's own exported originals.
	 */
	private void pollImportedLayouts()
	{
		if (!running || !config.syncSetups() || !remoteConfig.on("layouts_apply") || !syncAllowed()
			|| !backoff.allowed(EP_BANK_LAYOUTS, System.currentTimeMillis()))
		{
			return;
		}
		final String identity = syncIdentity();
		if (parking.isParked(EP_BANK_LAYOUTS, identity, 0L))
		{
			return;   // a GET has no payload to change, so a refusal holds until the character or key does
		}
		final String sentEtag = layoutsEtag;
		api.getBankLayouts(sentEtag, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				noteFailure(EP_BANK_LAYOUTS, 0L);
				log.debug("RuneTools: layout sync failed: {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					SyncResponse.Outcome outcome = noteSyncResult(r, EP_BANK_LAYOUTS, identity, 0L,
						SyncResponse.Shape.LAYOUTS, 0, false);
					if (r.code() == 304 || outcome != SyncResponse.Outcome.OK || !identity.equals(syncIdentity()))
					{
						return;
					}
					String body = RuneToolsApiClient.readBoundedBody(r);
					JsonObject o = new JsonParser().parse(body).getAsJsonObject();
					String received = o.has("etag") && !o.get("etag").isJsonNull() ? str(o, "etag", null) : null;
					if (received != null)
					{
						layoutsEtag = received;
					}
					if (SetupManager.etagChanged(sentEtag, received))
					{
						remotePoll.onChanged();   // something was added on the site; more may follow
					}
					Set<String> applied = readAppliedLayouts();
					boolean changed = false;
					// Only the newest whole bank import applies (rows come oldest first); older ones
					// it replaces are marked done without being built.
					JsonObject bankImport = null;
					String bankImportId = null;
					for (JsonObject l : newestImported(o.getAsJsonArray("layouts"), MAX_IMPORTED_LAYOUTS_PER_POLL))
					{
						String id = str(l, "id", null);
						if (id != null)
						{
							id = id.trim();   // readAppliedLayouts trims - normalise here so dedup matches
						}
						// The applied-set is a CSV; an id with a comma/newline would corrupt dedup, so
						// we can't safely track it - skip rather than risk re-applying forever.
						if (id == null || id.isEmpty()
							|| id.indexOf(',') >= 0 || id.indexOf('\n') >= 0 || id.indexOf('\r') >= 0)
						{
							continue;
						}
						if (applied.contains(id))
						{
							continue;
						}
						if ("bank".equals(str(l, "kind", "tab")))
						{
							if (bankImportId != null)
							{
								applied.add(bankImportId);
								changed = true;
							}
							bankImport = l;
							bankImportId = id;
							continue;
						}
						JsonArray cells = l.has("cells") && l.get("cells").isJsonArray() ? l.getAsJsonArray("cells") : null;
						if (cells == null || cells.size() == 0)
						{
							continue;
						}
						String name = BankOrganizer.sanitizeTagName(str(l, "name", "Imported layout"));
						if (name.isEmpty())
						{
							name = "Imported layout";
						}
						int icon = l.has("icon_item_id") && !l.get("icon_item_id").isJsonNull()
							? asInt(l, "icon_item_id", -1) : -1;
						// Mark applied FIRST so a payload that somehow still errors can never be
						// re-applied on every poll; the allocation is already bounded in cellsToArray.
						applied.add(id);
						changed = true;
						try
						{
							bankOrganizer.applyImportedLayout(name, icon, cellsToArray(cells));
							panel.setBankStatus("Imported \"" + name + "\" as a bank tab.", true);
						}
						catch (RuntimeException ex)
						{
							log.debug("RuneTools: skipped bad imported layout {}: {}", id, ex.toString());
						}
					}
					if (changed)
					{
						writeAppliedLayouts(applied);
					}
					if (bankImport != null)
					{
						applyBankImport(bankImportId, bankImport);
					}
				}
				catch (Exception ex)
				{
					log.debug("RuneTools: could not parse layouts: {}", ex.getMessage());
				}
			}
		});
	}

	/**
	 * The layouts imported from someone else (a {@code source_code}, or the older {@code imported}
	 * flag), at most {@code max} of them, the newest ones, returned oldest first. The player's own
	 * exports never count toward the cap, so they can't crowd a new import out.
	 */
	static List<JsonObject> newestImported(JsonArray rows, int max)
	{
		List<JsonObject> out = new ArrayList<>();
		if (rows == null)
		{
			return out;
		}
		for (int i = rows.size() - 1; i >= 0 && out.size() < max; i--)
		{
			JsonElement e = rows.get(i);
			if (e == null || !e.isJsonObject())
			{
				continue;
			}
			JsonObject l = e.getAsJsonObject();
			String source = str(l, "source_code", null);
			boolean imported = (source != null && !source.trim().isEmpty()) || isTrue(l, "imported");
			if (imported)
			{
				out.add(l);
			}
		}
		Collections.reverse(out);
		return out;
	}

	/** A JSON boolean field that is true; anything else (missing, null, a string) is false. */
	private static boolean isTrue(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	/**
	 * Build a positional layout array from server-supplied cells. Positions are attacker-controlled,
	 * so the array is sized to the largest <em>in-range</em> position only - never to a raw value that
	 * could force a multi-GB allocation (the confirmed OOM/DoS). Out-of-range cells are ignored.
	 */
	private static int[] cellsToArray(JsonArray cells)
	{
		int max = -1;
		int processed = 0;
		for (JsonElement e : cells)
		{
			if (++processed > MAX_LAYOUT_CELLS)
			{
				break;
			}
			int pos = asInt(e.getAsJsonObject(), "pos", -1);
			if (pos >= 0 && pos < MAX_LAYOUT_CELLS && pos > max)
			{
				max = pos;
			}
		}
		if (max < 0)
		{
			return new int[0];
		}
		int[] arr = new int[max + 1];
		Arrays.fill(arr, -1);
		processed = 0;
		for (JsonElement e : cells)
		{
			if (++processed > MAX_LAYOUT_CELLS)
			{
				break;
			}
			JsonObject c = e.getAsJsonObject();
			int pos = asInt(c, "pos", -1);
			int id = asInt(c, "item_id", 0);
			if (pos >= 0 && pos < arr.length && id > 0)
			{
				arr[pos] = id;
			}
		}
		return arr;
	}

	/**
	 * Build a whole bank layout imported on the site: its tabs plus a Misc tab of everything else in
	 * this character's bank. That needs the bank's contents, so until the bank has been opened this
	 * session it waits (bankImportWaiting) and finishes the moment it is.
	 */
	private void applyBankImport(String id, JsonObject l)
	{
		String name = BankOrganizer.sanitizeTagName(str(l, "name", "Imported bank"));
		final String label = name.isEmpty() ? "Imported bank" : name;
		final List<BankOrganizer.BankTab> tabs = new ArrayList<>();
		JsonArray arr = l.getAsJsonArray("tabs");
		if (arr != null)
		{
			for (JsonElement e : arr)
			{
				if (tabs.size() >= MAX_BANK_LAYOUT_TABS || !e.isJsonObject())
				{
					break;
				}
				JsonObject t = e.getAsJsonObject();
				JsonArray cells = t.getAsJsonArray("cells");
				if (cells == null || cells.size() == 0)
				{
					continue;
				}
				int icon = t.has("icon_item_id") && !t.get("icon_item_id").isJsonNull()
					? asInt(t, "icon_item_id", -1) : -1;
				tabs.add(new BankOrganizer.BankTab(str(t, "name", "Tab"), icon, cellsToArray(cells)));
			}
		}
		clientThread.invoke(() ->
		{
			Set<String> applied = readAppliedLayouts();
			if (!running || applied.contains(id))
			{
				return;   // switched off, or a second poll got here first
			}
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank == null)
			{
				bankImportWaiting = true;
				panel.setBankStatus("Open your bank to finish importing \"" + label + "\".", true);
				return;
			}
			applied.add(id);   // first, so a layout that somehow errors can't be rebuilt on every poll
			writeAppliedLayouts(applied);
			List<Integer> ids = new ArrayList<>();
			for (Item it : bank.getItems())
			{
				if (it.getId() > 0)
				{
					ids.add(it.getId());
				}
			}
			try
			{
				panel.setBankStatus(bankOrganizer.applyImportedBank(label, tabs, ids), true);
			}
			catch (RuntimeException ex)
			{
				log.debug("RuneTools: skipped bad imported bank {}: {}", id, ex.toString());
			}
		});
	}

	private void removeImportedBank()
	{
		if (!bankOrganizer.hasImportedBank())
