	/**
	 * "Missing items · cost to complete" for a setup's detail view: diff the setup's items against
	 * what the player owns (bank + inventory + equipment) and price the gap. Local + offline. Items
	 * are aggregated by canonical id (so a stack of 1000 runes is priced as 1000 and the same id in
	 * two lists is counted once), and a per-item breakdown drives the row's tooltip.
	 */
	private void computeMissingItems(GearSetup setup, Consumer<RuneToolsPanel.MissingResult> onResult)
	{
		clientThread.invoke(() ->
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			Set<Integer> owned = new HashSet<>();
			for (ItemContainer c : new ItemContainer[]{bank,
				client.getItemContainer(InventoryID.INV), client.getItemContainer(InventoryID.WORN)})
			{
				if (c == null)
				{
					continue;
				}
				for (Item it : c.getItems())
				{
					if (it.getId() > 0)
					{
						owned.add(itemManager.canonicalize(it.getId()));
					}
				}
			}
			// Aggregate the setup's requirements by canonical id (dedup across lists + fold in qty).
			Map<Integer, Long> need = new LinkedHashMap<>();
			for (Map.Entry<Integer, Integer> e : setup.filterItemCounts().entrySet())
			{
				int canon = itemManager.canonicalize(e.getKey());
				if (canon > 0)
				{
					need.merge(canon, (long) e.getValue(), Long::sum);
				}
			}
			int missing = 0;
			long cost = 0;
			List<RuneToolsPanel.MissingItem> breakdown = new ArrayList<>();
			for (Map.Entry<Integer, Long> e : need.entrySet())
			{
				int id = e.getKey();
				if (owned.contains(id))
				{
					continue;
				}
				missing++;
				long qty = e.getValue();
				long price = 0;
				try
				{
					price = itemManager.getItemPrice(id) * qty;
				}
				catch (RuntimeException ignored)
				{
					// unpriced item - count it, cost stays approximate
				}
				cost += price;
				String name = "item " + id;
				try
				{
					name = itemManager.getItemComposition(id).getName();
				}
				catch (RuntimeException ignored)
				{
					// no composition - fall back to the id
				}
				breakdown.add(new RuneToolsPanel.MissingItem(name, qty, price));
			}
			breakdown.sort((a, b) -> Long.compare(b.price, a.price));   // dearest first
			final String text = bank == null
				? "Open your bank to check what's missing."
				: missing == 0
					? "You own every item."
					: "Missing " + missing + " item" + (missing == 1 ? "" : "s")
						+ " · ~" + String.format("%,d", cost) + " gp";
			final RuneToolsPanel.MissingResult result = new RuneToolsPanel.MissingResult(
				text, bank != null ? breakdown : Collections.emptyList());
			SwingUtilities.invokeLater(() -> onResult.accept(result));
		});
	}

	private static final int[] BANK_TAB_COUNTS = {
		VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3,
		VarbitID.BANK_TAB_4, VarbitID.BANK_TAB_5, VarbitID.BANK_TAB_6,
		VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8, VarbitID.BANK_TAB_9,
	};

	/**
	 * Turn the native bank tab the user is currently viewing into a shareable Bank Tag. The bank
	 * container lists items tab-by-tab (tab 1, tab 2, ... then the main tab), and each numbered tab's
	 * size is a varbit - so we slice out exactly the open tab's items, in order, and hand them off.
	 */
	private void convertBankTab(String name)
	{
		clientThread.invoke(() ->
		{
			ItemContainer bank = client.getGameState() == GameState.LOGGED_IN
				? client.getItemContainer(InventoryID.BANK) : null;
			if (bank == null)
			{
				panel.setBankStatus(client.getGameState() == GameState.LOGGED_IN ? "Open your bank first." : MSG_LOG_IN,
					false);
				return;
			}
			int tab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
			if (tab < 1 || tab > BANK_TAB_COUNTS.length)
			{
				panel.setBankStatus("Open a numbered bank tab (1 to 9) first.", false);
				return;
			}
			int offset = 0;
			for (int i = 0; i < tab - 1; i++)
			{
				offset += client.getVarbitValue(BANK_TAB_COUNTS[i]);
			}
			int count = client.getVarbitValue(BANK_TAB_COUNTS[tab - 1]);
			Item[] items = bank.getItems();
			List<Integer> ids = new ArrayList<>();
			for (int i = offset; i < offset + count && i < items.length; i++)
			{
				int id = items[i].getId();
				if (id > 0)
				{
					ids.add(id);
				}
			}
			bankOrganizer.saveTabAsTag(name, ids, panel::setBankStatus);
		});
	}

	/**
	 * Share the whole bank's layout on runetools.com: numbered tabs 1-9, then the main tab, each item
	 * at its slot in its tab. A placeholder is shared as the item it keeps a place for and a bank
	 * filler as a gap. Only which items sit where is sent, never quantities.
	 */
	private void exportWholeBank()
	{
		if (!mayPublishLayout())
		{
			return;
		}
		clientThread.invoke(() ->
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank == null)
			{
				panel.setBankStatus("Open your bank, then share it.", false);
				return;
			}
			Item[] items = bank.getItems();
			int[] ids = new int[items.length];
			for (int i = 0; i < items.length; i++)
			{
				ids[i] = items[i].getId();
			}
			int[] counts = new int[BANK_TAB_COUNTS.length];
			for (int t = 0; t < counts.length; t++)
			{
				counts[t] = client.getVarbitValue(BANK_TAB_COUNTS[t]);
			}
			List<int[]> slices = BankOrganizer.nativeTabs(ids, counts, itemManager::canonicalize);
			JsonArray tabs = new JsonArray();
			int itemCount = 0;
			for (int t = 0; t < slices.size(); t++)
			{
				int[] slots = slices.get(t);
				JsonArray cells = new JsonArray();
				for (int i = 0; i < slots.length; i++)
				{
					if (slots[i] > 0)
					{
						JsonObject c = new JsonObject();
						c.addProperty("pos", i);
						c.addProperty("item_id", slots[i]);
						cells.add(c);
					}
				}
				if (cells.size() > 0)
				{
					JsonObject tab = new JsonObject();
					tab.addProperty("name", t == slices.size() - 1 ? "Main tab" : "Tab " + (t + 1));
					tab.addProperty("icon_item_id", cells.get(0).getAsJsonObject().get("item_id").getAsInt());
					tab.add("cells", cells);
					tabs.add(tab);
					itemCount += cells.size();
				}
			}
			if (tabs.size() == 0)
			{
				panel.setBankStatus("Your bank is empty.", false);
				return;
			}
			Player me = client.getLocalPlayer();
			final String suggested = me != null && me.getName() != null ? me.getName() + "'s bank" : "My bank";
			final int tabCount = tabs.size();
			final int total = itemCount;
			SwingUtilities.invokeLater(() ->
			{
				JTextField name = new JTextField(suggested, 20);
				JCheckBox listed = new JCheckBox("Public: anyone can find and import it", true);
				JPanel form = new JPanel();
				form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
				form.add(new JLabel("Name:"));
				form.add(name);
				form.add(listed);
				form.add(new JLabel("<html>" + total + " items in " + tabCount + " tab" + (tabCount == 1 ? "" : "s")
					+ ". Positions only, never quantities.</html>"));
				int ok = JOptionPane.showConfirmDialog(panel, form, "Share whole bank",
					JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
				if (ok != JOptionPane.OK_OPTION || name.getText().trim().isEmpty() || !mayPublishLayout())
				{
					return;   // (checked again: the character may have logged out while the dialog was open)
				}
				JsonObject body = new JsonObject();
				body.addProperty("name", name.getText().trim());
				body.addProperty("kind", "bank");
				body.addProperty("is_public", listed.isSelected());
				body.addProperty("icon_item_id", tabs.get(0).getAsJsonObject().get("icon_item_id").getAsInt());
				body.add("tabs", tabs);
				panel.setBankStatus("Sharing…", true);
				api.postBankLayout(body, bankLayoutCallback(listed.isSelected()));
			});
		});
	}

	/**
	 * Publish the currently-open bank tag (its layout + items) to the user's runetools.com profile,
	 * where others can view it and import it. Reads the tag on the client thread, names it on the
	 * EDT, then POSTs; on success copies the share link and opens the layout page.
	 */
	private void exportBankTag()
	{
		if (!mayPublishLayout())
		{
			return;
		}
		clientThread.invoke(() ->
		{
			String tag = bankTagsService.getActiveTag();
			if (tag == null || tag.isEmpty() || tag.startsWith(BankFilterController.TAG_PREFIX))
			{
				panel.setBankStatus("Open a tag tab in your bank first (Save tab as tag makes one).", false);
				return;
			}
			JsonArray cells = new JsonArray();
			Layout layout = layoutManager.loadLayout(tag);
			if (layout != null)
			{
				int[] arr = layout.getLayout();
				for (int i = 0; i < arr.length; i++)
				{
					if (arr[i] > 0)
					{
						JsonObject c = new JsonObject();
						c.addProperty("pos", i);
						c.addProperty("item_id", arr[i]);
						cells.add(c);
					}
				}
			}
			else
			{
				int pos = 0;
				for (int id : tagManager.getItemsForTag(tag))
				{
					if (id > 0)
					{
						JsonObject c = new JsonObject();
						c.addProperty("pos", pos++);
						c.addProperty("item_id", id);
						cells.add(c);
					}
				}
			}
			if (cells.size() == 0)
			{
				panel.setBankStatus("That tab is empty.", false);
				return;
			}
			int icon = cells.get(0).getAsJsonObject().get("item_id").getAsInt();
			SwingUtilities.invokeLater(() ->
			{
				String name = JOptionPane.showInputDialog(panel, "Layout name:", BankTagNames.shown(tag));
				if (name == null || name.trim().isEmpty() || !mayPublishLayout())
				{
					return;
				}
				JsonObject body = new JsonObject();
				body.addProperty("name", name.trim());
				body.addProperty("icon_item_id", icon);
				body.add("cells", cells);
				panel.setBankStatus("Publishing…", true);
				api.postBankLayout(body, bankLayoutCallback(true));
			});
		});
	}

	/**
	 * Whether a layout may be published now; when not, the message says why (consent, no key, the
	 * world, the site pausing it, an old build).
	 */
	private boolean mayPublishLayout()
	{
		if (blockedByConsent())
		{
			return false;
		}
		if (writesPaused())
		{
			panel.setBankStatus(MSG_UPDATE, false);
			return false;
		}
		if (!remoteConfig.on("layouts_publish"))
		{
			panel.setBankStatus(MSG_PAUSED, false);
			return false;
		}
		return true;
	}

	/** Handles a layout export's answer. A private one has no public page, so it opens "My layouts". */
	private Callback bankLayoutCallback(boolean isPublic)
	{
		return new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				panel.setBankStatus(SyncResponse.describe(0, null, "Couldn't publish the layout."), false);
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					String s = RuneToolsApiClient.bodyOrEmpty(r);
					if (r.isSuccessful() && SyncResponse.confirms(SyncResponse.Shape.OBJECT, s, 0))
					{
						String url = str(new JsonParser().parse(s).getAsJsonObject(), "url", null);
						// Only auto-open/copy a link that points at our own (or the configured dev)
						// server. A malicious/compromised responder must not be able to drive the
						// browser to an arbitrary phishing URL or poison the clipboard.
						final String u = isSafeShareUrl(url) ? url : null;
						if (!isPublic)
						{
							panel.setBankStatus("Saved privately.", true);
							openSignedIn("/layouts/mine");
						}
						else if (u != null)
						{
							copyToClipboard(u);
							panel.setBankStatus("Published. Link copied.", true);
							SwingUtilities.invokeLater(() -> LinkBrowser.browse(u));
						}
						else
						{
							panel.setBankStatus("Published to your profile.", true);
						}
					}
					else
					{
						panel.setBankStatus(SyncResponse.describe(r.code(), s, "Couldn't publish the layout."), false);
					}
				}
				catch (Exception ex)
				{
					panel.setBankStatus("Couldn't publish the layout. Unexpected answer from the site.", false);
				}
			}
		};
	}

	private void copyToClipboard(String text)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
		}
		catch (Exception ignored)
		{
			// clipboard may be unavailable; the browser still opens
		}
	}

