	private boolean hasKeyAndConsent()
	{
		return config.consent() && activeApiKey() != null;
	}

	// --- Per-character API keys: each game account gets its OWN RuneTools account + key, so a main
	// and an ironman/GIM never share one profile. Keys are stored per account hash ("key_<hash>"). ---

	/** The API key for the CURRENTLY logged-in character, or null if this character isn't linked yet. */
	private String activeApiKey()
	{
		return keyForHash(snapshot.get().accountHash);
	}

	/**
	 * Stamp the logged-in character's identity (rsn + account_hash) onto a sync body. The site
	 * publishes the collection log and combat achievements under the RSN, so it will only accept
	 * a name this character has linked - the account hash is what proves the link on a first sync.
	 */
	private void stampIdentity(JsonObject body)
	{
		AccountSnapshot s = snapshot.get();
		if (s.rsn != null)
		{
			body.addProperty("rsn", s.rsn);
		}
		if (s.accountHash != null)
		{
			body.addProperty("account_hash", s.accountHash);
		}
	}

	private String keyForHash(String hash)
	{
		if (hash == null || hash.isEmpty())
		{
			return null;   // no character logged in yet
		}
		String k = configManager.getConfiguration(RuneToolsConfig.GROUP, keyConfigKey(hash));
		return k != null && !k.trim().isEmpty() ? k.trim() : null;
	}

	private void storeKeyForHash(String hash, String key)
	{
		if (hash != null && !hash.isEmpty() && key != null && !key.trim().isEmpty())
		{
			configManager.setConfiguration(RuneToolsConfig.GROUP, keyConfigKey(hash), key.trim());
			resumeSync();   // a freshly-issued key is the fix for a rejected one: start syncing again
			backoff.clear();
		}
	}

	private static String keyConfigKey(String hash)
	{
		return "key_" + hash;
	}

	private void flushTrades()
	{
		if (!config.syncTrades() || !uploadsOn("trades"))
		{
			return;   // kept queued
		}
		List<Trade> batch;
		synchronized (pending)
		{
			if (pending.isEmpty())
			{
				return;
			}
			batch = new ArrayList<>(pending);
		}
		// One upload per character, each with that character's own key: a fill always lands in the
		// account of the character that made it (TradeGroups). Fills with no key here stay queued.
		long now = System.currentTimeMillis();
		AccountSnapshot snap = snapshot.get();
		TradeGroups.Plan plan = TradeGroups.plan(batch, this::keyForHash, snap.accountHash, snap.rsn, now);
		if (!plan.expired.isEmpty())
		{
			synchronized (pending)
			{
				pending.removeAll(plan.expired);
			}
			savePending();
			updatePanelStatic();
			log.debug("RuneTools: dropped {} queued fill(s) with no key for over 30 days", plan.expired.size());
		}
		String activeKey = activeApiKey();
		for (TradeGroups.Group g : plan.send)
		{
			final String endpoint = EP_TRADES + g.accountHash;
			final String identity = syncIdentity(g.rsn, g.accountHash, g.key);
			final List<Trade> group = g.trades;
			final long payload = group.hashCode();
			final boolean foreign = !g.key.equals(activeKey);
			if (!backoff.allowed(endpoint, now) || parking.isParked(endpoint, identity, payload))
			{
				continue;   // backing off, or refused before: the fills stay queued
			}
			if (!tradesInFlight.add(endpoint))
			{
				continue;   // this character's previous upload hasn't answered yet
			}
			log.debug("RuneTools: flushing {} trade(s)", group.size());
			api.postTrades(g.key, g.rsn, g.accountHash, group, new Callback()
			{
				@Override
				public void onFailure(Call call, IOException ex)
				{
					tradesInFlight.remove(endpoint);
					noteFailure(endpoint, payload);
					log.debug("RuneTools: trade sync failed (will retry): {}", ex.getMessage());
				}

				@Override
				public void onResponse(Call call, Response resp)
				{
					try (Response r = resp)
					{
						SyncResponse.Outcome outcome = noteSyncResult(r, endpoint, identity, payload,
							SyncResponse.Shape.TRADES, group.size(), foreign);
						if (outcome == SyncResponse.Outcome.OK)
						{
							// Dropped only now the server has confirmed it received exactly these.
							synchronized (pending)
							{
								pending.removeAll(group);
							}
							savePending();
							updatePanelStatic();
							log.debug("RuneTools: synced {} trade(s) OK", group.size());
						}
						else
						{
							log.debug("RuneTools: trade sync HTTP {} - fills kept queued", r.code());
						}
					}
					finally
					{
						tradesInFlight.remove(endpoint);
					}
				}
			});
		}
	}

	private void flushState()
	{
		if (!config.syncState() || !uploadsOn("state") || !stateDirty.get())
		{
			return;
		}
		if (!backoff.allowed(EP_STATE, System.currentTimeMillis()))
		{
			return;   // left dirty: sent once the endpoint may go again
		}
		final String identity = syncIdentity();
		if (parking.isNameParked(EP_STATE, identity))
		{
			return;   // the name is linked to another account; left dirty so another character or key sends it
		}
		// Clear up-front so a change that lands mid-request re-marks it dirty and is not lost.
		stateDirty.set(false);
		// Send one coherent, immutable cut. The bank goes only when it changed since the server last
		// accepted one (the server keeps the last bank when it's left out), and only with Include bank
		// on. The payload hash leaves out the capture time, which differs on every send.
		AccountSnapshot snap = snapshot.get();
		boolean includeBank = config.syncBank() && remoteConfig.on("bank") && snap.bank != null;
		final int bankHash = includeBank ? snap.bank.toString().hashCode() : 0;
		if (includeBank && chars.bankAlreadySent(bankHash))
		{
			includeBank = false;
		}
		final boolean sentBank = includeBank;
		JsonObject body = RuneToolsApiClient.stateBody(snap, includeBank);
		final long payload = body.toString().hashCode();
		if (parking.isParked(EP_STATE, identity, payload))
		{
			return;   // exactly this state was refused; the next change re-marks it dirty and is tried
		}
		body.addProperty("ts", System.currentTimeMillis());
		api.postState(body, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				stateDirty.set(true);
				noteFailure(EP_STATE, payload);
				log.debug("RuneTools: state sync failed (will retry): {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					SyncResponse.Outcome outcome = noteSyncResult(r, EP_STATE, identity, payload,
						SyncResponse.Shape.OK_TRUE, 0, false);
					if (outcome == SyncResponse.Outcome.OK)
					{
						if (sentBank && identity.equals(syncIdentity()))
						{
							chars.bankSent(bankHash);
						}
						log.debug("RuneTools: state synced OK");
					}
					else if (outcome == SyncResponse.Outcome.PAYLOAD_REJECTED)
					{
						// Parked, and deliberately not re-marked dirty: the next real change sends again.
						log.debug("RuneTools: state sync HTTP {} - not resending this state", r.code());
					}
					else
					{
						stateDirty.set(true);
						log.debug("RuneTools: state sync HTTP {} (will retry)", r.code());
					}
				}
			}
		});
	}

	// -- panel + connection test --------------------------------------------- //

	/**
	 * The panel's "Connect to RuneTools" / "Open RuneTools" button. Asks the site for a one-time
	 * browser-login code with this character's stored key and opens the site signed in. The site only
	 * does that for an account the key already opens and that has no email, and it never creates an
	 * account or hands out a key here. Otherwise it answers 403 with a reason: "email_signin" opens the
	 * account page (the browser signs in with the email), and "pair" (or an older server's
	 * "email_locked": no working key for this character) starts {@link #startPairing pairing}, which a
	 * person approves in the browser. Any other answer is shown as it is. The game account hash alone
	 * never opens an account. Consent-gated, since it links this character's name + account hash to a
	 * RuneTools account.
	 */
	private void openSiteLogin()
	{
		if (!config.consent())
		{
			panel.showMessage("Turn on consent in the RuneTools settings first.", false);
			return;
		}
		if (api.validBase() == null)
		{
			panel.showMessage(RuneToolsApiClient.BAD_URL_MESSAGE, false);
			return;
		}
		clientThread.invoke(() ->
		{
			Player p = client.getGameState() == GameState.LOGGED_IN ? client.getLocalPlayer() : null;
			final String rsn = p != null ? p.getName() : null;
			if (rsn == null || rsn.isEmpty())
			{
				// No character yet: nothing to sign in as, so just open the site.
				browseSafe(api.base() + "/");
				return;
			}
			if (!isMainGame())
			{
				panel.showMessage(MSG_NOT_HERE, false);
				return;
			}
			final String accountHash = currentHash();
			if (!remoteConfig.on("web_login"))
			{
				// The site has paused browser sign-in: connect if this character has no key, else just open it.
				if (keyForHash(accountHash) == null)
				{
					startPairing(accountHash, rsn);
				}
				else
				{
					browseSafe(api.base() + "/");
				}
				return;
			}
			panel.showMessage("Opening the site…", true);
			api.webLogin(accountHash, rsn, null, new Callback()
			{
				@Override
				public void onFailure(Call call, IOException ex)
				{
					panel.showMessage(SyncResponse.describe(0, null, "Couldn't open the site."), false);
				}

				@Override
				public void onResponse(Call call, Response resp)
				{
					try (Response r = resp)
					{
						String body = RuneToolsApiClient.bodyOrEmpty(r);
						if (r.code() == 403)
						{
							String why = SyncResponse.errorCode(body);
							if ("email_signin".equals(why))
							{
								// Nothing is wrong: the character is connected and syncing, but an account
								// with an email signs the browser in with that, never with the plugin's key.
								panel.clearMessage();
								updatePanelStatic();
								browseSafe(api.base() + "/account");
							}
							else if ("pair".equals(why) || "email_locked".equals(why))
							{
								// No working key for this character here: connect it by approving it in the browser.
								startPairing(accountHash, rsn);
							}
							else
							{
								panel.showMessage(SyncResponse.describe(403, body, "Couldn't open the site."), false);
							}
							return;
						}
						if (!r.isSuccessful() || !SyncResponse.confirms(SyncResponse.Shape.OBJECT, body, 0))
						{
							panel.showMessage(SyncResponse.describe(r.code(), body, "Couldn't open the site."), false);
							return;
						}
						String url = str(new JsonParser().parse(body).getAsJsonObject(), "url", null);
						// Only ever open a link to our own (configured) server - never an arbitrary URL.
						final String full = url != null && url.startsWith("/") ? api.base() + url : null;
						if (full != null && isSafeShareUrl(full))
						{
							panel.clearMessage();
							browseSafe(full);
						}
						else
						{
							panel.showMessage("Signed in. Open runetools.com to view your account.", true);
						}
					}
					catch (Exception ex)
					{
						// Never the body: it holds a one-time sign-in code.
						log.warn("RuneTools: couldn't read the site's answer to Connect (HTTP {}, {})",
							resp.code(), resp.header("Content-Type"));
						panel.showMessage("Couldn't open the site. Unexpected answer from the site.", false);
					}
				}
			});
		});
	}

	// -- pairing (how every character gets connected and receives its key) -- //

	/** One pending pairing: what to poll with, the code the player checks, and its deadline. */
	private static final class Pairing
	{
		final String pollToken;
		final String userCode;
		final String accountHash;
		final String rsn;
		final long expiresAtMillis;
		final AtomicBoolean inFlight = new AtomicBoolean();
		volatile long lastPollAt;

		Pairing(String pollToken, String userCode, String accountHash, String rsn, long expiresAtMillis)
		{
			this.pollToken = pollToken;
			this.userCode = userCode;
			this.accountHash = accountHash;
			this.rsn = rsn;
			this.expiresAtMillis = expiresAtMillis;
		}
	}

	private final AtomicReference<Pairing> pairing = new AtomicReference<>();

	/**
	 * Ask the site to pair this client, show the code, and open the approve page. There the player
	 * checks the code matches, then approves it into the account they're signed into, signs in or
	 * creates one, or continues without an email; {@link #pollPairing} then receives this
	 * character's key. The code stays in the message strip, where no background sync overwrites it.
	 */
	private void startPairing(String accountHash, String rsn)
	{
		if (!remoteConfig.on("pairing"))
		{
			panel.showMessage(MSG_PAUSED, false);
			return;
		}
		panel.showMessage("Opening the site to approve this connection…", true);
		api.pairStart(accountHash, rsn, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				panel.showMessage(SyncResponse.describe(0, null, "Couldn't start connecting."), false);
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					String body = RuneToolsApiClient.bodyOrEmpty(r);
					if (!r.isSuccessful() || !SyncResponse.confirms(SyncResponse.Shape.OBJECT, body, 0))
					{
						panel.showMessage(SyncResponse.describe(r.code(), body, "Couldn't start connecting."), false);
						return;
					}
					JsonObject o = new JsonParser().parse(body).getAsJsonObject();
					String token = str(o, "poll_token", null);
					String code = RemoteConfig.clean(str(o, "user_code", null), 16);
					String url = str(o, "url", null);
					long ttl = Math.max(30L, Math.min(3600L, asInt(o, "expires_in", 600)));
					if (token == null || code.isEmpty())
					{
						log.warn("RuneTools: the site's answer to pairing had no code (HTTP {})", r.code());
						panel.showMessage("Couldn't start connecting. Unexpected answer from the site.", false);
						return;
					}
					pairing.set(new Pairing(token, code, accountHash, rsn, System.currentTimeMillis() + ttl * 1000L));
					panel.showMessage("Approve this connection on the site. Code: " + code, true);
					// Only ever open a page on our own (configured) server.
					final String full = url != null && url.startsWith("/") ? api.base() + url : null;
					if (full != null && isSafeShareUrl(full))
					{
						SwingUtilities.invokeLater(() -> LinkBrowser.browse(full));
					}
				}
				catch (Exception ex)
				{
					log.warn("RuneTools: couldn't read the site's answer to pairing (HTTP {}, {})",
						resp.code(), resp.header("Content-Type"));
					panel.showMessage("Couldn't start connecting. Unexpected answer from the site.", false);
				}
			}
		});
	}

	/** While a pairing is pending, ask every few seconds whether the player has approved it. */
	@Schedule(period = 3, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void pollPairing()
	{
		final Pairing p = pairing.get();
		if (p == null || !running)
		{
			return;
		}
		// Approving hands this client the character's key, so only ask while it may sync: consent
		// given, and the character that asked still logged in (a hop or a loading screen is fine).
		GameState state = client.getGameState();
		String playing = snapshot.get().accountHash;
		if (!config.consent() || state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR
			|| (playing != null && p.accountHash != null && !playing.equals(p.accountHash)))
		{
			if (pairing.compareAndSet(p, null))
			{
				panel.showMessage("Connecting was cancelled. Press Connect to try again.", false);
			}
			return;
		}
		long now = System.currentTimeMillis();
		if (now > p.expiresAtMillis)
		{
			if (pairing.compareAndSet(p, null))
			{
				panel.showMessage("The connection request expired. Press Connect to try again.", false);
			}
			return;
		}
		if (now - p.lastPollAt < remoteConfig.limitMs("pair_poll_s") - 500L || !p.inFlight.compareAndSet(false, true))
		{
			return;   // the site asked for a slower poll, or the last one hasn't answered yet
		}
		p.lastPollAt = now;
		api.pairPoll(p.pollToken, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				p.inFlight.set(false);   // a network blip: the next tick asks again
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					if (r.code() == 410)
					{
						if (pairing.compareAndSet(p, null))
						{
							panel.showMessage("The connection request expired. Press Connect to try again.", false);
						}
						return;
					}
					if (!r.isSuccessful())
					{
						return;   // a 429 or a server hiccup: keep the pairing, ask again next tick
					}
					JsonObject o = new JsonParser().parse(RuneToolsApiClient.readBoundedBody(r)).getAsJsonObject();
					String key = str(o, "api_key", null);
					if ("approved".equals(str(o, "status", "")) && key != null && key.startsWith("rtk_")
						&& pairing.compareAndSet(p, null))
					{
						storeKeyForHash(p.accountHash, key);
						updatePanelStatic();   // "Connected as ..."
						panel.showMessage("Connected" + (p.rsn != null ? " as " + p.rsn : "") + ".", true);
					}
				}
				catch (Exception ex)
				{
					log.debug("RuneTools: pairing poll failed: {}", ex.getMessage());
				}
				finally
				{
					p.inFlight.set(false);
				}
			}
		});
	}

	// Colours copied from WikiDpsManager (the game's stone-button text colours).
	private static final int DPS_BTN_COLOUR = 0xff981f;
	private static final int DPS_BTN_HOVER = 0xffffff;

	/**
	 * Inject a "RuneTools DPS" button into the equipment-bonuses interface ("Equip Your Character"),
	 * copying RuneLite's own Wiki "View DPS" button: the same trigger (the stat-bonus setup script)
	 * and the same technique of cloning the native "Set Bonus" button's sprites so ours matches the
	 * game UI exactly. Best-effort: any widget-API hiccup is caught so it can never break the plugin.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired e)
	{
		if (e.getScriptId() == CollectionLog.TRANSMIT_SCRIPT)
		{
			collectTransmittedClogItem(e);
			return;
		}
		if (e.getScriptId() != ScriptID.EQUIPMENT_SET_STAT_BONUS_SETUP)
		{
			return;
		}
		Object[] args = e.getScriptEvent() != null ? e.getScriptEvent().getArguments() : null;
		if (args == null || args.length < 5 || !(args[1] instanceof Integer) || !(args[4] instanceof Integer))
		{
			return;
		}
		if ((int) args[4] == 1 || WidgetUtil.componentToInterface((int) args[1]) != EQUIP_GROUP)
		{
			return;   // only the stats page (not the set-bonus page) of the equipment interface
		}
		try
		{
			// The setup script rebuilds the interface's children on every fire (destroying our old
			// button), so re-add it each time - the same as the Wiki plugin - rather than dedup-guard;
			// otherwise toggling to Set Bonus and back would leave our button gone until reopen.
			dpsButton = null;
			dpsWidgets.clear();
			addDpsButton();
		}
		catch (RuntimeException ex)
		{
			log.debug("RuneTools: couldn't add equipment DPS button: {}", ex.toString());
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == EQUIP_GROUP)
		{
			dpsButton = null;   // dynamic children are destroyed with the interface; allow a fresh add
			dpsWidgets.clear();
		}
		else if (e.getGroupId() == InterfaceID.COLLECTION)
		{
			clogAskedThisOpen = false;
		}
	}

	/**
	 * Build a "RuneTools DPS" button in the equipment-bonuses interface by cloning the native "Set
	 * Bonus" button's 9 sprite pieces + text (the WikiDpsManager technique), placed in the free space
	 * at the top-left of the interface so it doesn't collide with the game's / Wiki plugin's buttons.
	 * Re-run on every setup-script fire (onScriptPreFired resets {@code dpsButton} first).
	 */
	private void addDpsButton()
	{
		Widget parent = client.getWidget(EQUIP_PARENT);
		Widget setBonus = client.getWidget(EQUIP_SETBONUS);
		Widget[] ref;
		if (parent == null || setBonus == null || (ref = setBonus.getChildren()) == null || ref.length < 10)
		{
			return;
		}
		// Clone the native "Set Bonus" button's look, but drop ours in the free space at the TOP-LEFT
		// of the interface (left of the helmet slot) rather than the crowded bottom row - the bottom
		// already holds the game's Set Bonus + the Wiki plugin's View DPS, so ours was getting clipped.
		final int w = setBonus.getOriginalWidth();
		final int h = setBonus.getOriginalHeight();
		final int x = 4;
		final int y = 4;
		log.debug("RuneTools equip button: parent {}x{}, setBonus x={} y={} w={} h={}",
			parent.getWidth(), parent.getHeight(), setBonus.getOriginalX(), setBonus.getOriginalY(), w, h);

		int bgWidth = w - ref[0].getOriginalWidth();
		int bgHeight = h - ref[0].getOriginalHeight();
		int bgX = x + ref[0].getOriginalX() + (w - bgWidth) / 2;
		int bgY = y + ref[0].getOriginalY() + (h - bgHeight) / 2;
		Widget bg = parent.createChild(-1, WidgetType.GRAPHIC)
			.setSpriteId(ref[0].getSpriteId())
			.setPos(bgX, bgY)
			.setSize(bgWidth, bgHeight);
		bg.revalidate();
		dpsWidgets.add(bg);

		for (int i = 1; i < 9; i++)
		{
			Widget piece = parent.createChild(-1, WidgetType.GRAPHIC)
				.setSpriteId(ref[i].getSpriteId())
				.setSize(ref[i].getOriginalWidth(), ref[i].getOriginalHeight())
				.setPos(x + ref[i].getOriginalX(), y + ref[i].getOriginalY());
			piece.revalidate();
			dpsWidgets.add(piece);
		}

		final Widget text = parent.createChild(-1, WidgetType.TEXT)
			.setText("RuneTools DPS")
			.setTextColor(DPS_BTN_COLOUR)
			.setFontId(ref[9].getFontId())
			.setTextShadowed(ref[9].getTextShadowed())
			.setXTextAlignment(ref[9].getXTextAlignment())
			.setYTextAlignment(ref[9].getYTextAlignment())
			.setPos(x, y)
			.setSize(w, h);
		text.setHasListener(true);
		text.setOnMouseOverListener((JavaScriptCallback) ev -> text.setTextColor(DPS_BTN_HOVER));
		text.setOnMouseLeaveListener((JavaScriptCallback) ev -> text.setTextColor(DPS_BTN_COLOUR));
		text.setAction(0, "View DPS with RuneTools");
		text.setOnOpListener((JavaScriptCallback) ev ->
		{
			if (running)
			{
				checkDps();
			}
		});
		text.revalidate();
		parent.revalidate();
		dpsWidgets.add(text);
		dpsButton = text;
	}

	/**
	 * Take our button out of the equipment interface when the plugin is switched off: every widget it
	 * is made of is hidden and stops listening, so nothing of it stays on screen or clickable. The
	 * interface drops these dynamic children itself the next time it is drawn.
	 */
	private void removeDpsButton()
	{
		clientThread.invoke(() ->
		{
			for (Widget w : dpsWidgets)
			{
				try
				{
					w.setHidden(true);
					w.setHasListener(false);
					w.setAction(0, null);
				}
				catch (RuntimeException ex)
				{
					log.debug("RuneTools: couldn't hide the equipment DPS button: {}", ex.toString());
				}
			}
			dpsWidgets.clear();
			dpsButton = null;
			Widget parent = client.getWidget(EQUIP_PARENT);
			if (parent != null)
			{
				parent.revalidate();
			}
		});
	}

	/**
	 * Open the RuneTools DPS calculator pre-filled with the gear you're currently wearing. Reads the
	 * worn equipment on the client thread, encodes the item ids, and opens {@code /calculators/dps} -
	 * the site resolves each item to its slot and infers your combat style from the weapon. No account
	 * data is sent (the ids ride the URL the browser opens), so this isn't consent-gated.
	 */
	private void checkDps()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				panel.showMessage(MSG_LOG_IN, false);
				return;
			}
			ItemContainer eq = client.getItemContainer(InventoryID.WORN);
			if (eq == null)
			{
				panel.showMessage("Wear some gear first.", false);
				return;
			}
			// Send an explicit slot->id map plus the combat style, not a flat id list. The site then
			// never has to guess a slot, and - crucially - the style comes from the worn weapon's own
			// stats, so a charged weapon (trident/sceptre/shadow) whose id isn't in the site's gear
			// catalog still loads as magic/ranged instead of silently defaulting to melee.
			StringBuilder gear = new StringBuilder();
			String style = null;
			for (EquipSlot s : EQUIP_SLOTS)
			{
				Item it = eq.getItem(s.slot.getSlotIdx());
				if (it == null || it.getId() <= 0)
				{
					continue;
				}
				if (gear.length() > 0)
				{
					gear.append(',');
				}
				gear.append(s.name).append(':').append(itemManager.canonicalize(it.getId()));
				if (s.slot == EquipmentInventorySlot.WEAPON)
				{
					style = weaponStyle(it.getId());
				}
			}
			if (gear.length() == 0)
			{
				panel.showMessage("Wear some gear first.", false);
				return;
			}
			String url = api.base() + "/calculators/dps?gear=" + gear;
			if (style != null)
			{
				url += "&style=" + style;
			}
			browseSafe(url);
		});
	}

	/**
	 * The worn combat style inferred from a weapon's own equipment bonuses (magic / ranged / melee) -
	 * catalog-independent, so it's correct even for a charged weapon the site's gear list doesn't know.
	 * Returns null if the item has no equipment stats (then the site keeps its default).
	 */
	private String weaponStyle(int itemId)
	{
		ItemStats st = itemManager.getItemStats(itemId);
		if (st == null)
		{
			return null;
		}
		ItemEquipmentStats e = st.getEquipment();
		if (e == null)
		{
			return null;
		}
		int mag = e.getAmagic();
		int rng = e.getArange();
		int mel = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
		if (mag > mel && mag >= rng)
		{
			return "magic";
		}
		if (rng > mel && rng >= mag)
		{
			return "ranged";
		}
		return "melee";
	}

	/** Equipment slot -> the DPS site's slot name, in the order the handoff lists them. */
	private static final class EquipSlot
	{
		final EquipmentInventorySlot slot;
		final String name;

		EquipSlot(EquipmentInventorySlot slot, String name)
		{
			this.slot = slot;
			this.name = name;
		}
	}

	private static final EquipSlot[] EQUIP_SLOTS = {
		new EquipSlot(EquipmentInventorySlot.HEAD, "head"),
		new EquipSlot(EquipmentInventorySlot.CAPE, "cape"),
		new EquipSlot(EquipmentInventorySlot.AMULET, "neck"),
		new EquipSlot(EquipmentInventorySlot.WEAPON, "weapon"),
		new EquipSlot(EquipmentInventorySlot.BODY, "body"),
		new EquipSlot(EquipmentInventorySlot.SHIELD, "shield"),
		new EquipSlot(EquipmentInventorySlot.LEGS, "legs"),
		new EquipSlot(EquipmentInventorySlot.GLOVES, "hands"),
		new EquipSlot(EquipmentInventorySlot.BOOTS, "feet"),
		new EquipSlot(EquipmentInventorySlot.RING, "ring"),
		new EquipSlot(EquipmentInventorySlot.AMMO, "ammo"),
	};

	private void updatePanelStatic()
	{
		if (panel == null)
		{
			return;
		}
		int n;
		synchronized (pending)
		{
			n = pending.size();
		}
		panel.setPending(n);
		boolean linked = activeApiKey() != null;
		// A key the server keeps rejecting is functionally "not connected", so put the CTA back to
		// "Connect to RuneTools" - re-linking the character is exactly what mints a working key.
		// Before login the character isn't known yet, so there is nothing to connect: "Open RuneTools".
		boolean known = snapshot.get().hasIdentity();
		boolean offWorld = loggedIn && !mainGame;
		panel.setConnectButton(!known || (linked && !authRevoked));   // "Connect to RuneTools" vs "Open RuneTools"
		String reason = known ? parking.parkedReason(syncIdentity()) : null;
		if (api.validBase() == null)
		{
			panel.setStatus(RuneToolsApiClient.BAD_URL_MESSAGE, false);
		}
		else if (writesPaused())
		{
			panel.setStatus(MSG_UPDATE, false);
		}
		else if (offWorld)
		{
			panel.setStatus(MSG_NOT_HERE, false);
		}
		else if (!known)
		{
			panel.setStatus("Log in to the game. Connected characters sync by themselves.", true);
		}
		else if (!config.consent())
		{
			panel.setStatus("Turn on consent in the RuneTools settings.", false);
		}
		else if (!linked)
		{
			panel.setStatus("Not connected", false);
		}
		else if (authRevoked)
		{
			// Sticky: every other panel update would otherwise paint "Connected as ..." back over the
			// only message that tells the user why nothing is syncing any more.
			panel.setStatus(SYNC_REVOKED_MSG, false);
		}
		else if (reason != null)
		{
			// Sticky for the same reason: the key works and other syncs carry on, but some are held
			// (a name linked to another account, or a limit), and this says why in the server's words.
			panel.setStatus(reason.isEmpty() ? SYNC_NAME_TAKEN_MSG : reason, false);
		}
		else
		{
			panel.setStatus("Connected as " + snapshot.get().rsn, true);
		}
		// The CA and Collection Log views say why they can't sync instead of giving advice that wouldn't work.
		String gate = offWorld ? MSG_NOT_HERE
			: !known ? "Log in to the game."
			: !config.consent() ? "Turn on consent in the RuneTools settings."
			: !linked || authRevoked ? "Connect this character."
			: null;
		panel.setGates(gate != null ? gate : config.syncCombatAchievements() ? null : "Sync off",
			gate != null ? gate : config.syncCollectionLog() ? null : "Sync off");
	}

	// -- persistence of the unsynced-trade queue ----------------------------- //

	/**
	 * Queue a captured fill for upload and cap the backlog, oldest-first. See
	 * {@link #MAX_PENDING_TRADES}: the queue is rewritten into RuneLite's config on every fill, so an
	 * unbounded one turns a long outage into an ever-growing blob re-serialised per trade. The newest
	 * fills are the ones the site's P/L is still missing, so it's the oldest that go.
	 */
	private void queuePending(Trade t)
	{
		synchronized (pending)
		{
			pending.add(t);
			if (pending.size() > MAX_PENDING_TRADES)
			{
				// Worth a line in the log: losing a fill is only ever the symptom of a much longer
				// outage, and this is the one place that says so.
				log.warn("RuneTools: unsynced-trade queue full ({}) - dropping the oldest fill",
					MAX_PENDING_TRADES);
				trimPending();
			}
		}
	}

	/** Caller must hold the {@code pending} lock. */
	private void trimPending()
	{
		while (pending.size() > MAX_PENDING_TRADES)
		{
			pending.remove(0);
		}
	}

	private void loadPending()
	{
		try
		{
			String raw = debounced.get(PENDING_KEY);
			if (raw == null || raw.isEmpty())
			{
				return;
			}
			JsonArray arr = new JsonParser().parse(raw).getAsJsonArray();
			List<Trade> loaded = new ArrayList<>();
			for (JsonElement el : arr)
			{
				loaded.add(Trade.fromPendingJson(el.getAsJsonObject()));
			}
			synchronized (pending)
			{
				pending.clear();
				pending.addAll(loaded);
				trimPending();   // a blob written before the cap existed must not be inherited whole
			}
		}
		catch (Exception ex)
		{
			log.debug("Could not load pending trades: {}", ex.getMessage());
			synchronized (pending)
			{
				pending.clear();
			}
		}
	}

	private void savePending()
	{
		try
		{
			// Build the snapshot and hand it over under the same lock, so two threads calling
			// savePending() (client thread on capture; OkHttp thread after a flush) can't
			// interleave and let a stale, larger queue overwrite a just-flushed one. The write itself
			// happens a moment later, once, from DebouncedConfig.
			synchronized (pending)
			{
				JsonArray arr = new JsonArray();
				for (Trade t : pending)
				{
					arr.add(t.toPendingJson());
				}
				debounced.set(PENDING_KEY, arr.size() == 0 ? null : arr.toString());
			}
		}
		catch (Exception ex)
		{
			log.debug("Could not persist pending trades: {}", ex.getMessage());
		}
	}

	/** Null-safe string accessor with a fallback (untrusted-JSON friendly). */
	private static String str(JsonObject o, String key, String fallback)
	{
		try
		{
			JsonElement e = o.get(key);
			return e != null && !e.isJsonNull() ? e.getAsString() : fallback;
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	/** Null-safe int accessor with a fallback - never throws on a missing/non-numeric field. */
	private static int asInt(JsonObject o, String key, int fallback)
	{
		try
		{
			JsonElement e = o.get(key);
			return e != null && !e.isJsonNull() ? e.getAsInt() : fallback;
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	// -- the site's settings for the plugin (RemoteConfig) ------------------- //

	/** The last good copy cached in this plugin's config, or the defaults. */
	private RemoteConfig cachedRemoteConfig()
	{
		RemoteConfig rc = RemoteConfig.parse(configManager.getConfiguration(RuneToolsConfig.GROUP, CONFIG_CACHE_KEY));
		return rc != null ? rc : RemoteConfig.defaults();
	}

	/**
	 * Fetch the site's settings: after consent at login ({@code force}, at most once a minute), when
	 * the live-update answer names a new config_tag ({@code force}), and every config_s (30 minutes)
	 * otherwise. A 404 or an answer that isn't a JSON object leaves the last good copy in force.
	 * {@code tag} (the live answer's config_tag, or null) becomes the one sent back once the site has
	 * answered this fetch; a fetch that doesn't start (the gap, one in flight) leaves it unchanged.
	 */
	private void fetchRemoteConfig(boolean force, String tag)
	{
		long now = System.currentTimeMillis();
		long gap = force ? CONFIG_MIN_GAP_MS : remoteConfig.limitMs("config_s");
		if (!running || !config.consent() || now - lastConfigFetchAt < gap || !configInFlight.compareAndSet(false, true))
		{
			return;
		}
		lastConfigFetchAt = now;
		api.getConfig(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				configInFlight.set(false);
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					if (tag != null && running)
					{
						lastConfigTag = tag;   // the site answered for this tag, whatever it said
					}
					if (r.code() != 200 || !running)
					{
						return;   // no config on this server (404), or not now: keep what we have
					}
					RemoteConfig rc = RemoteConfig.parse(RuneToolsApiClient.bodyOrEmpty(r));
					if (rc != null)
					{
						applyRemoteConfig(rc, true);
					}
				}
				finally
				{
					configInFlight.set(false);
				}
			}
		});
	}

	/** Put a remote config in force, cache it, and show its notice. */
	private void applyRemoteConfig(RemoteConfig rc, boolean cache)
	{
		boolean wasPaused = writesPaused();
		remoteConfig = rc;
		if (cache)
		{
			configManager.setConfiguration(RuneToolsConfig.GROUP, CONFIG_CACHE_KEY, rc.raw());
		}
		remotePoll.setBounds(rc.limitMs("poll_min_s"), rc.limitMs("poll_max_s"));
		if (!rc.on("live"))
		{
			api.cancelLive();
		}
		RemoteConfig.Message m = rc.message();
		if (writesPaused())
		{
			panel.setNotice(MSG_UPDATE, "warn", null);
		}
		else if (m != null)
		{
			final String link = m.link != null ? api.base() + m.link : null;
			panel.setNotice(m.text, m.level, link != null && isSafeShareUrl(link) ? () -> LinkBrowser.browse(link) : null);
			announceOnce(m);
		}
		else
		{
			panel.setNotice(null, null, null);
		}
		if (wasPaused != writesPaused())
		{
			updatePanelStatic();
		}
	}

	/** A notice from the site goes to chat once (per id, ever); it never opens anything by itself. */
	private void announceOnce(RemoteConfig.Message m)
	{
		String seen = configManager.getConfiguration(RuneToolsConfig.GROUP, NOTICE_SEEN_KEY);
		if (m.id.equals(seen) || !loggedIn)
		{
			return;
		}
		configManager.setConfiguration(RuneToolsConfig.GROUP, NOTICE_SEEN_KEY, m.id);
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("RuneTools: ")
			.append(ChatColorType.NORMAL).append(Text.escapeJagex(m.text))
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(msg).build());
	}

	/**
	 * True only if {@code url} is safe to auto-open/copy: https (or loopback http for a dev server)
	 * pointing at the configured RuneTools host (or a subdomain of it), or a loopback address.
	 */
	private boolean isSafeShareUrl(String url)
	{
		if (url == null || url.trim().isEmpty())
		{
			return false;
		}
		try
		{
			java.net.URI uri = new java.net.URI(url.trim());
			String scheme = uri.getScheme();
			String host = uri.getHost();
			if (scheme == null || host == null)
			{
				return false;
			}
			scheme = scheme.toLowerCase();
			if (!scheme.equals("https"))
			{
				return false;      // https only - no cleartext http, javascript:, file:, custom schemes
			}
			boolean loopback = RuneToolsApiClient.isLoopbackHost(host);
			String baseHost = RuneToolsApiClient.hostOf(api.base());
			boolean sameSite = !baseHost.isEmpty()
				&& (host.equalsIgnoreCase(baseHost) || host.toLowerCase().endsWith("." + baseHost.toLowerCase()));
			return loopback || sameSite;
		}
		catch (Exception ex)
		{
			return false;
		}
	}

	private static String nowString()
	{
		return LocalTime.now().withNano(0).toString();
	}

	private static BufferedImage icon()
	{
		// The RuneTools rune (a gold R on a rune stone), the same mark as the Plugin Hub icon.png and
		// runetools.com. Built from the site's master by ge-trader/scripts/build_brand_icons.py.
		return ImageUtil.loadImageResource(RuneToolsPlugin.class, "nav_icon.png");
	}
}

package com.runetools;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * A per-slot snapshot of a GE offer, kept between events so we can compute fill deltas without
 * double-counting (see {@link OfferTracker}). Price and spent are {@code long} to match
 * {@code GrandExchangeOffer} since RuneLite 1.13; narrowing them back to int could overflow on a
 * large offer. Mutable with a no-arg constructor so Gson can round-trip it.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class SavedOffer
{
	private int itemId;
	private long price;
	private int totalQuantity;
	private int quantitySold;   // cumulative units filled so far
	private long spent;         // cumulative gp moved so far
	private GrandExchangeOfferState state;

	static SavedOffer from(GrandExchangeOffer o)
	{
		return new SavedOffer(o.getItemId(), o.getPrice(), o.getTotalQuantity(),
			o.getQuantitySold(), o.getSpent(), o.getState());
	}
}

package com.runetools;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tracks this login session's Grand Exchange activity for the panel: a running realized-profit
 * estimate (FIFO-matched buys -> sells, minus the 2% GE tax) plus the most recent fills. This is a
 * quick in-game glance only - the site keeps the authoritative, tax-exact P/L history.
 *
 * <p>Only ever touched from the client thread (the offer-changed handler), so it needs no locking.
 */
class SessionTracker
{
	private static final int MAX_RECENT = 12;
	private static final long TAX_CAP = 5_000_000L;   // GE tax caps at 5m per item

	private final Map<Integer, Deque<long[]>> buyLots = new HashMap<>();   // itemId -> queue of {qtyRemaining, unitPrice}
	private final Deque<Trade> recent = new ArrayDeque<>();
	private long realizedProfit;

	void record(Trade t)
	{
		if (t == null)
		{
			return;
		}
		if ("buy".equals(t.getSide()))
		{
			buyLots.computeIfAbsent(t.getItemId(), k -> new ArrayDeque<>())
				.addLast(new long[]{t.getQty(), t.getPrice()});
		}
		else if ("sell".equals(t.getSide()))
		{
			final long taxPerItem = Math.min(t.getPrice() / 50L, TAX_CAP);   // 2% GE tax per item, capped
			long qty = t.getQty();
			final Deque<long[]> lots = buyLots.get(t.getItemId());
			while (qty > 0 && lots != null && !lots.isEmpty())
			{
				final long[] lot = lots.peekFirst();
				final long take = Math.min(qty, lot[0]);
				realizedProfit += (t.getPrice() - taxPerItem - lot[1]) * take;
				lot[0] -= take;
				qty -= take;
				if (lot[0] <= 0)
				{
					lots.removeFirst();
				}
			}
			if (lots != null && lots.isEmpty())
			{
				buyLots.remove(t.getItemId());   // drop the itemId once its lots are fully matched, so the map can't grow unbounded
			}
			// any sell qty with no matching buy this session is ignored (cost basis unknown)
		}
		recent.addFirst(t);
		while (recent.size() > MAX_RECENT)
		{
			recent.removeLast();
		}
	}

	long realizedProfit()
	{
		return realizedProfit;
	}

	List<Trade> recent()
	{
		return new ArrayList<>(recent);   // snapshot for the EDT
	}
}

package com.runetools;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * A named group of setups shared as one on the site ("3 Man Bandos"), as one setup sees it: which
 * collection, the role this setup plays in it ("Tank") and its place in the list. Optional: a setup
 * the site sends without one is simply in no collection.
 */
@Value
class SetupCollection
{
	private static final int MAX_PER_SETUP = 20;

	long id;
	String name;
	String role;
	int order;

	/**
	 * The collections a setup's JSON names: {@code collection} (one object) and/or {@code collections}
	 * (an array of them). An entry with a missing key or a wrong type is ignored, so a malformed field
	 * reads as "no collection" and never breaks the setup itself.
	 */
	static List<SetupCollection> parse(JsonObject setup)
	{
		List<SetupCollection> out = new ArrayList<>();
		if (setup == null)
		{
			return out;
		}
		add(out, setup.get("collection"));
		JsonElement many = setup.get("collections");
		if (many != null && many.isJsonArray())
		{
			for (JsonElement e : many.getAsJsonArray())
			{
				if (out.size() >= MAX_PER_SETUP)
				{
					break;
				}
				add(out, e);
			}
		}
		return out;
	}

	private static void add(List<SetupCollection> out, JsonElement e)
	{
		SetupCollection c = one(e);
		if (c == null)
		{
			return;
		}
		for (SetupCollection have : out)
		{
			if (have.id == c.id)
			{
				return;   // named twice (in both fields): once is enough
			}
		}
		out.add(c);
	}

	/**
	 * One collection object, or null when id or name is missing, or any field is the wrong type. A
	 * missing (or null) role reads as no role and a missing order as 0, so a site that leaves them out
	 * still groups the setup.
	 */
	static SetupCollection one(JsonElement e)
	{
		if (e == null || !e.isJsonObject())
		{
			return null;
		}
		JsonObject o = e.getAsJsonObject();
		JsonPrimitive id = primitive(o, "id");
		JsonPrimitive name = primitive(o, "name");
		JsonPrimitive role = primitive(o, "role");
		JsonPrimitive order = primitive(o, "order");
		if (id == null || !id.isNumber() || name == null || !name.isString() || (role != null && !role.isString())
			|| (order != null && !order.isNumber()) || wrongType(o, "role") || wrongType(o, "order"))
		{
			return null;
		}
		double idValue = id.getAsDouble();
		double orderValue = order != null ? order.getAsDouble() : 0d;
		if (idValue != Math.rint(idValue) || idValue <= 0 || idValue > Long.MAX_VALUE
			|| orderValue != Math.rint(orderValue) || Math.abs(orderValue) > Integer.MAX_VALUE)
		{
			return null;
		}
		String n = RemoteConfig.clean(name.getAsString(), 80).trim();
		if (n.isEmpty())
		{
			return null;
		}
		String r = role != null ? RemoteConfig.clean(role.getAsString(), 40).trim() : "";
		return new SetupCollection(id.getAsLong(), n, r, order != null ? order.getAsInt() : 0);
	}

	/** A field that is there, not null, and not a plain value (an object or an array). */
	private static boolean wrongType(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && !e.isJsonNull() && !e.isJsonPrimitive();
	}

	private static JsonPrimitive primitive(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsJsonPrimitive() : null;
	}
}

package com.runetools;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The setups list as the panel shows it. A setup in no collection is a row of its own, where it has
 * always been. The first setup of a collection brings the collection's header there, followed by all
 * its setups in their {@code order}, each labelled by its role. A setup in several collections is
 * listed under each. Plain logic, so it can be unit-tested.
 */
final class SetupGroups
{
	/** One line of the list: a collection header ({@code setup} null) or a setup. */
	static final class Row
	{
		final String header;      // the collection's name, for a header row
		final GearSetup setup;    // the setup, for a setup row
		final String label;       // what the row reads: the role inside a collection, else the setup's name
		final String tooltip;     // the setup's name when the label is a role, else null
		final boolean indented;   // a setup inside a collection

		private Row(String header, GearSetup setup, String label, String tooltip, boolean indented)
		{
			this.header = header;
			this.setup = setup;
			this.label = label;
			this.tooltip = tooltip;
			this.indented = indented;
		}
	}

	private SetupGroups()
	{
	}

	static List<Row> rows(List<GearSetup> setups)
	{
		// Each collection's members, with the collection's first name, in first-seen order.
		Map<Long, List<GearSetup>> members = new LinkedHashMap<>();
		Map<Long, String> names = new LinkedHashMap<>();
		for (GearSetup s : setups)
		{
			for (SetupCollection c : collectionsOf(s))
			{
				members.computeIfAbsent(c.getId(), k -> new ArrayList<>()).add(s);
				names.putIfAbsent(c.getId(), c.getName());
			}
		}
		List<Row> out = new ArrayList<>();
		Set<Long> shown = new HashSet<>();
		for (GearSetup s : setups)
		{
			List<SetupCollection> mine = collectionsOf(s);
			if (mine.isEmpty())
			{
				out.add(new Row(null, s, name(s), null, false));
				continue;
			}
			for (SetupCollection c : mine)
			{
				if (!shown.add(c.getId()))
				{
					continue;
				}
				out.add(new Row(names.get(c.getId()), null, names.get(c.getId()), null, false));
				List<GearSetup> list = new ArrayList<>(members.get(c.getId()));
				final long cid = c.getId();
				list.sort(Comparator.comparingInt(g -> orderIn(g, cid)));   // stable: ties keep list order
				for (GearSetup g : list)
				{
					String role = roleIn(g, cid);
					boolean hasRole = role != null && !role.isEmpty();
					out.add(new Row(null, g, hasRole ? role : name(g), hasRole ? name(g) : null, true));
				}
			}
		}
		return out;
	}

	private static List<SetupCollection> collectionsOf(GearSetup s)
	{
		List<SetupCollection> c = s.getCollections();
		return c != null ? c : new ArrayList<>();
	}

	private static int orderIn(GearSetup g, long collectionId)
	{
		for (SetupCollection c : collectionsOf(g))
		{
			if (c.getId() == collectionId)
			{
				return c.getOrder();
			}
		}
		return 0;
	}

	private static String roleIn(GearSetup g, long collectionId)
	{
		for (SetupCollection c : collectionsOf(g))
		{
			if (c.getId() == collectionId)
			{
				return c.getRole();
			}
		}
		return null;
	}

	private static String name(GearSetup s)
	{
		return s.getName() != null ? s.getName() : "Setup";
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;

/**
 * Pulls the user's gear setups from RuneTools, caches them (persisted in RuneLite's config so they
 * survive restarts) and tracks which one is "active". The cache and its ETag are kept per account
 * hash, so one character's setups are never shown, filtered or deleted as another's. Polling uses a
 * full pull with an {@code If-None-Match} ETag, so an unchanged server returns 304. How often it polls
 * is the plugin's call ({@link PollSchedule}).
 *
 * <p>Every write reports its own result through {@link Host#message}, with the server's words when it
 * gave any; a write that failed pulls the server's copy again, so a refused edit doesn't stay on
 * screen as if it had been saved.
 */
@Slf4j
class SetupManager
{
	private static final String KEY_SETUPS = "setups";
	private static final String KEY_ETAG = "setupsEtag";
	private static final int MAX_SETUPS = 500;   // cap on how many (untrusted) setups we parse/keep
	private static final long IMPORT_GAP_MS = 400L;   // between imported setups: ~150 a minute at most

	/** What the manager needs from the plugin. */
	interface Host
	{
		/** Whether a background pull may go out now (signed in, consent, not backing off, not switched off). */
		boolean mayPull();

		/** Whether a write may go out; when not, the host has already said why in the panel. */
		boolean mayWrite();

		/** A pull's answer, for the plugin's sync health (status 0 = no answer). */
		void pulled(int status, String body, boolean confirmed);

		/** The result of something the player did (saved, deleted, imported, refused). */
		void message(String text, boolean ok);

		/** The setup list changed. */
		void changed(List<GearSetup> setups);

		/** A setup was removed on the site: drop its bank tag and layout. */
		void deleted(long id);

		/** A poll found the setups changed on the site since the last one. */
		void remoteChanged();
	}

	private final DebouncedConfig store;
	private final RuneToolsApiClient api;
	private final Host host;
	private final ScheduledExecutorService executor;

	private volatile String account;   // account hash the list belongs to; null before a character is in game
	private volatile List<GearSetup> setups = Collections.emptyList();
	private volatile String etag;
	private volatile long activeId = -1;
	private volatile boolean closed;

	// One update PUT in flight at a time; edits that arrive during it coalesce (latest wins per setup)
	// so two quick edits can't race on the wire and clobber each other. Each edit is serialised when it
	// is made, on the thread that made it, so a later edit can't change what an earlier one sends.
	private final Object pushGate = new Object();
	private boolean updateInFlight;
	private final Map<Long, JsonObject> pendingUpdates = new LinkedHashMap<>();

	SetupManager(DebouncedConfig store, RuneToolsApiClient api, Host host, ScheduledExecutorService executor)
	{
		this.store = store;
		this.api = api;
		this.host = host;
		this.executor = executor;
	}

	/** Stop for good (the plugin was switched off). */
	void close()
	{
		closed = true;
	}

	/** True when a poll sent with {@code sent} came back with a different, real ETag. */
	static boolean etagChanged(String sent, String received)
	{
		return sent != null && !sent.isEmpty() && received != null && !received.equals(sent);
	}

	static String setupsKey(String accountHash)
	{
		return KEY_SETUPS + "_" + accountHash;
	}

	static String etagKey(String accountHash)
	{
		return KEY_ETAG + "_" + accountHash;
	}

	/**
	 * The character in game is now {@code accountHash} (null: nobody). Shows that character's cached
	 * setups and forgets the previous one's; nothing is deleted for it.
	 */
	void switchAccount(String accountHash)
	{
		String now = accountHash != null && !accountHash.isEmpty() ? accountHash : null;
		if (now == null ? account == null : now.equals(account))
		{
			return;
		}
		synchronized (pushGate)
		{
			pendingUpdates.clear();   // edits queued for the previous character's setups
		}
		account = now;
		activeId = -1;
		load(now);
		host.changed(setups);
	}

	List<GearSetup> getSetups()
	{
		return setups;
	}

	GearSetup getActive()
	{
		long id = activeId;
		for (GearSetup s : setups)
		{
			if (s.getId() == id)
			{
				return s;
			}
		}
		return null;
	}

	void setActive(long id)
	{
		activeId = id;
	}

	void clearActive()
	{
		activeId = -1;
	}

	/** Ask the site for this account's setups (an ETag poll). Gated by {@link Host#mayPull}. */
	void poll()
	{
		final String forAccount = account;
		if (closed || forAccount == null || !host.mayPull())
		{
			return;
		}
		final String sentEtag = etag;
		api.getSetups(sentEtag, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				if (!closed)
				{
					host.pulled(0, null, false);
				}
				log.debug("RuneTools: setups sync failed (will retry): {}", ex.getMessage());
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					if (closed || !forAccount.equals(account))
					{
						return;   // switched off, or another character is in game now
					}
					if (r.code() == 304)
					{
						host.pulled(304, null, true);
						return;
					}
					String body = RuneToolsApiClient.bodyOrEmpty(r);
					boolean confirmed = r.isSuccessful()
						&& SyncResponse.confirms(SyncResponse.Shape.SETUPS, body, 0);
					host.pulled(r.code(), body, confirmed);
					if (!confirmed)
					{
						log.debug("RuneTools: setups sync HTTP {} (not applied)", r.code());
						return;   // never wipe the list over an answer that isn't a setups list
					}
					apply(forAccount, sentEtag, new JsonParser().parse(body).getAsJsonObject());
				}
				catch (Exception ex)
				{
					log.debug("RuneTools: could not parse setups: {}", ex.getMessage());
				}
			}
		});
	}

	private void apply(String forAccount, String sentEtag, JsonObject o)
	{
		JsonArray arr = o.getAsJsonArray("setups");
		List<GearSetup> parsed = parseList(arr);
		// Diff old vs new ids so setups removed on the site drop their bank tag + layout.
		Set<Long> removed = new HashSet<>();
		for (GearSetup s : setups)
		{
			removed.add(s.getId());
		}
		for (GearSetup s : parsed)
		{
			removed.remove(s.getId());
		}
		setups = Collections.unmodifiableList(parsed);
		for (Long id : removed)
		{
			host.deleted(id);
		}
		String received = o.has("etag") && !o.get("etag").isJsonNull() ? safeString(o.get("etag")) : null;
		if (received != null)
		{
			etag = received;
		}
		persist(forAccount, arr);
		host.changed(setups);
		if (etagChanged(sentEtag, received))
		{
			host.remoteChanged();
		}
		log.debug("RuneTools: {} gear setup(s) synced", parsed.size());
	}

	/** Save a new setup on the site. {@code s} is serialised now, on the caller's thread. */
	void pushCreate(GearSetup s)
	{
		if (closed || !host.mayWrite())
		{
			return;
		}
		final String name = displayName(s);
		final JsonObject body = s.toJson();
		host.message("Saving \"" + name + "\"…", true);
		api.createSetup(body, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				host.message(SyncResponse.describe(0, null, "Couldn't save \"" + name + "\"."), false);
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					String b = RuneToolsApiClient.bodyOrEmpty(r);
					if (r.isSuccessful() && SyncResponse.confirms(SyncResponse.Shape.SETUP, b, 0))
					{
						host.message("Saved \"" + name + "\".", true);
					}
					else
					{
						host.message(SyncResponse.describe(r.code(), b, "Couldn't save \"" + name + "\"."), false);
					}
				}
				refresh();
			}
		});
	}

	/**
	 * Save an edit. {@code s} is shown at once and serialised now, on the caller's thread (the Swing
	 * thread for panel edits), so nothing done to it afterwards changes what is sent.
	 */
	void pushUpdate(GearSetup s)
	{
		if (closed || !host.mayWrite())
		{
			revert();   // put the last copy from the site back over an edit that won't be sent
			return;
		}
		final JsonObject body = s.toJson();
		replaceLocal(s);   // reflect the edit in the panel immediately; the poll after the PUT reconciles
		synchronized (pushGate)
		{
			if (updateInFlight)
			{
				pendingUpdates.put(s.getId(), body);
				return;
			}
			updateInFlight = true;
		}
		sendUpdate(s.getId(), body);
	}

	/**
	 * Optimistically swap the matching cached setup for {@code s} and notify listeners, so a "Refresh
	 * from game" shows in the open detail view without waiting for the server round-trip. The
	 * following {@link #poll()} overwrites it with the server's copy. In-place slot edits mutate the
	 * cached object itself and the panel already shows them, so those skip the re-render.
	 */
	private void replaceLocal(GearSetup s)
	{
		List<GearSetup> copy = new ArrayList<>(setups);
		for (int i = 0; i < copy.size(); i++)
		{
			GearSetup existing = copy.get(i);
			if (existing.getId() == s.getId())
			{
				if (existing == s)
				{
					return;
				}
				copy.set(i, s);
				setups = Collections.unmodifiableList(copy);
				host.changed(setups);
				return;
			}
		}
	}

	private void sendUpdate(long id, JsonObject body)
	{
		final String name = body.has("name") ? safeString(body.get("name")) : "Setup";
		api.updateSetup(id, body, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				try
				{
					log.debug("RuneTools: setup update failed: {}", ex.getMessage());
					host.message(SyncResponse.describe(0, null, "Couldn't save \"" + name + "\"."), false);
					revert();   // show what the site really has
				}
				finally
				{
					afterUpdate();
				}
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					String b = RuneToolsApiClient.bodyOrEmpty(r);
					if (!(r.isSuccessful() && SyncResponse.confirms(SyncResponse.Shape.SETUP, b, 0)))
					{
						log.debug("RuneTools: setup update HTTP {}", r.code());
						host.message(SyncResponse.describe(r.code(), b, "Couldn't save \"" + name + "\"."), false);
						revert();
					}
					else
					{
						refresh();   // the panel then shows the site's copy
					}
				}
				finally
				{
					afterUpdate();
				}
			}
		});
	}

	private void afterUpdate()
	{
		Long nextId = null;
		JsonObject next = null;
		synchronized (pushGate)
		{
			Iterator<Map.Entry<Long, JsonObject>> it = pendingUpdates.entrySet().iterator();
			if (it.hasNext() && !closed)
			{
				Map.Entry<Long, JsonObject> en = it.next();
				nextId = en.getKey();
				next = en.getValue();
				it.remove();
			}
			else
			{
				updateInFlight = false;
			}
		}
		if (next != null)
		{
			sendUpdate(nextId, next);
		}
	}

	void pushDelete(long id)
	{
		if (closed || !host.mayWrite())
		{
			return;
		}
		api.deleteSetup(id, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				host.message(SyncResponse.describe(0, null, "Couldn't delete the setup."), false);
				revert();
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				try (Response r = resp)
				{
					String b = RuneToolsApiClient.bodyOrEmpty(r);
					if (r.isSuccessful() && SyncResponse.confirms(SyncResponse.Shape.DELETED, b, 0))
					{
						host.message("Deleted.", true);
					}
					else
					{
						host.message(SyncResponse.describe(r.code(), b, "Couldn't delete the setup."), false);
					}
				}
				refresh();
			}
		});
	}

	/**
	 * Save setups imported from Inventory Setups, one request at a time and a little apart (the site
	 * allows about 240 plugin requests a minute from one address), then pull once. Stops at a rate
	 * limit, a full setup list or a rejected key, and reports what was really saved. Each setup is only
	 * sent while the character that started the import can still save (same character in game,
	 * consent on, signed in, connected): a logout, a switch or consent turned off part way stops it.
	 */
	void importMany(List<GearSetup> list)
	{
		final String forAccount = account;
		if (closed || forAccount == null || list.isEmpty() || !host.mayWrite())
		{
			return;
		}
		List<JsonObject> bodies = new ArrayList<>();
		for (GearSetup g : list)
		{
			bodies.add(g.toJson());
		}
		host.message("Importing " + bodies.size() + " setup" + (bodies.size() == 1 ? "" : "s") + "…", true);
		importNext(forAccount, bodies, 0, 0, 0);
	}

	private void importNext(String forAccount, List<JsonObject> bodies, int index, int created, int failed)
	{
		if (closed)
		{
			return;
		}
		if (index >= bodies.size())
		{
			finishImport(bodies.size(), created, failed, null);
			return;
		}
		if (index > 0 && (!forAccount.equals(account) || !host.mayWrite()))
		{
			finishImport(bodies.size(), created, failed, "Import stopped.");
			return;
		}
		api.createSetup(bodies.get(index), new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				next(created, failed + 1);
			}

			@Override
			public void onResponse(Call call, Response resp)
			{
				String stop = null;
				boolean ok;
				try (Response r = resp)
				{
					String b = RuneToolsApiClient.bodyOrEmpty(r);
					ok = r.isSuccessful() && SyncResponse.confirms(SyncResponse.Shape.SETUP, b, 0);
					if (!ok && (r.code() == 429 || r.code() == 409 || r.code() == 401 || r.code() == 403))
					{
						stop = SyncResponse.describe(r.code(), b, "Import stopped.");
					}
				}
				if (stop != null)
				{
					finishImport(bodies.size(), created, failed, stop);
					return;
				}
				next(ok ? created + 1 : created, ok ? failed : failed + 1);
			}

			private void next(int c, int f)
			{
				if (closed)
				{
					return;
				}
				if (executor != null)
				{
					executor.schedule(() -> importNext(forAccount, bodies, index + 1, c, f), IMPORT_GAP_MS,
						TimeUnit.MILLISECONDS);
				}
				else
				{
					importNext(forAccount, bodies, index + 1, c, f);
				}
			}
		});
	}

	private void finishImport(int total, int created, int failed, String stoppedBecause)
	{
		if (closed)
		{
			return;
		}
		host.message(importSummary(total, created, failed, stoppedBecause), created == total);
		if (created > 0)
		{
			refresh();
		}
	}

	/** "Imported 3 setups." or "Imported 2 of 5. 1 failed. <why it stopped>" */
	static String importSummary(int total, int created, int failed, String stoppedBecause)
	{
		if (created == total)
		{
			return "Imported " + total + " setup" + (total == 1 ? "" : "s") + ".";
		}
		StringBuilder sb = new StringBuilder("Imported ").append(created).append(" of ").append(total).append('.');
		if (failed > 0)
		{
			sb.append(' ').append(failed).append(" failed.");
		}
		if (stoppedBecause != null)
		{
			sb.append(' ').append(stoppedBecause);
		}
		return sb.toString();
	}

	/**
	 * A write was refused or never sent: show the last copy the site gave (the cached one, which edits
	 * made in the panel haven't touched), then pull a fresh one.
	 */
	private void revert()
	{
		if (closed)
		{
			return;
		}
		String forAccount = account;
		load(forAccount);
		host.changed(setups);
		refresh();
	}

	/** Pull the server's copy now, bypassing the ETag (after a write). */
	private void refresh()
	{
		if (closed)
		{
			return;
		}
		etag = null;
		poll();
	}

	private static String displayName(GearSetup s)
	{
		return s.getName() != null && !s.getName().trim().isEmpty() ? s.getName().trim() : "Setup";
	}

	private void persist(String forAccount, JsonArray arr)
	{
		store.set(setupsKey(forAccount), arr != null ? arr.toString() : "[]");
		store.set(etagKey(forAccount), etag);
	}

	/** Read one account's cache. Its ETag is trusted only when the cached list itself parsed. */
	private void load(String forAccount)
	{
		etag = null;
		setups = Collections.emptyList();
		if (forAccount == null)
		{
			return;
		}
		try
		{
			String raw = store.get(setupsKey(forAccount));
			if (raw == null || raw.isEmpty())
			{
				return;
			}
			JsonElement root = new JsonParser().parse(raw);
			if (!root.isJsonArray())
			{
				return;
			}
			setups = Collections.unmodifiableList(parseList(root.getAsJsonArray()));
			etag = store.get(etagKey(forAccount));
		}
		catch (Exception ex)
		{
			setups = Collections.emptyList();
			etag = null;
			log.debug("RuneTools: could not load cached setups: {}", ex.getMessage());
		}
	}

	private static List<GearSetup> parseList(JsonArray arr)
	{
		List<GearSetup> parsed = new ArrayList<>();
		if (arr == null)
		{
			return parsed;
		}
		for (JsonElement e : arr)
		{
			if (parsed.size() >= MAX_SETUPS)
			{
				break;
			}
			if (!e.isJsonObject())
			{
				continue;
			}
			try
			{
				GearSetup g = GearSetup.fromJson(e.getAsJsonObject());
				if (g.getId() > 0)   // skip a malformed/id-less element rather than drop the batch
				{
					parsed.add(g);
				}
			}
			catch (RuntimeException ex)
			{
				log.debug("RuneTools: skipped a malformed setup: {}", ex.getMessage());
			}
		}
		return parsed;
	}

	private static String safeString(JsonElement e)
	{
		try
		{
			return e.getAsString();
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}
}

package com.runetools;

import java.util.function.Consumer;

/**
 * Bridge the setups panel uses to touch the live game: open the in-game item search (the same
 * chatbox search Inventory Setups uses), read the item currently in a live equipment/inventory slot
 * and look up item names. All callbacks are delivered back on the Swing EDT so the panel can mutate
 * its widgets.
 */
interface SlotEditor
{
	/** An item and how many: {@code id} -1 for an empty slot. */
	interface ItemPick
	{
		void accept(int id, int qty);
	}

	/** Open the in-game Item Search; {@code onPicked} gets the chosen (canonicalised) item id. */
	void searchItem(String tooltip, ItemPick onPicked);

	/** Read the worn item at the given equipment slot index, with its quantity (ammo). */
	void readEquipSlot(int equipIdx, ItemPick onItem);

	/** Read the inventory item at the given index, with its quantity. */
	void readInvSlot(int index, ItemPick onItem);

	/** Resolve whether an item holds Dizana's quiver ammo (drives the extra ammo slot). */
	void isQuiver(int itemId, Consumer<Boolean> onResult);

	/** The item's name, for a slot's tooltip. */
	void itemName(int itemId, Consumer<String> onName);
}

package com.runetools;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/**
 * One inventory/equipment slot in the setups panel: an item (or spellbook) sprite, a NE fuzzy "*"
 * indicator, and a right-click menu the panel fills. Mirrors Inventory Setups' slot - the popup
 * mouse listener is attached to BOTH the panel and the image label, otherwise the image swallows
 * the right-click and no menu ever appears (the bug in the first cut).
 */
final class SlotLabel extends JPanel
{
	static final int W = 46;
	static final int H = 42;

	private final JLabel image = new JLabel();
	private final JLabel fuzzyStar = new JLabel();
	private final JPopupMenu menu = new JPopupMenu();
	private int itemId = -1;
	private int qty;

	SlotLabel(Color bg)
	{
		setLayout(new GridBagLayout());
		setPreferredSize(new Dimension(W, H));
		setMinimumSize(new Dimension(W, H));
		setMaximumSize(new Dimension(W, H));   // else a BoxLayout parent (e.g. Spellbook) stretches it wider
		setBackground(bg);

		fuzzyStar.setFont(FontManager.getRunescapeSmallFont());
		fuzzyStar.setForeground(Color.YELLOW);
		image.setHorizontalAlignment(JLabel.CENTER);

		add(image);
		add(fuzzyStar, new GridBagConstraints(0, 0, 1, 1, 1, 1,
			GridBagConstraints.NORTHEAST, GridBagConstraints.NONE, new Insets(0, 0, 0, 0), 0, 0));

		MouseAdapter popup = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				maybeShow(e);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				maybeShow(e);
			}

			private void maybeShow(MouseEvent e)
			{
				if (e.isPopupTrigger() && menu.getComponentCount() > 0)
				{
					menu.show(e.getComponent(), e.getX(), e.getY());
				}
			}
		};
		addMouseListener(popup);
		image.addMouseListener(popup);
	}

	void setItem(ItemManager itemManager, int id, int qty)
	{
		this.itemId = id;
		this.qty = Math.max(1, qty);
		if (itemManager == null || id <= 0)
		{
			clear();
			return;
		}
		itemManager.getImage(id, this.qty, this.qty > 1).addTo(image);
		setToolTipText(qty > 1 ? "x" + String.format("%,d", this.qty) : null);   // the name follows (setName)
	}

	/** Put the item's name in the tooltip, once it has been looked up, if the slot still holds it. */
	void setName(int forId, String name)
	{
		if (forId == itemId && itemId > 0 && name != null && !name.isEmpty())
		{
			setToolTipText(name + (qty > 1 ? " x" + String.format("%,d", qty) : ""));
		}
	}

	int getQty()
	{
		return itemId > 0 ? qty : 0;
	}

	/** Render a non-item sprite (e.g. a spellbook icon). */
	void setImage(BufferedImage img, String tip)
	{
		this.itemId = -1;
		image.setIcon(img == null ? null : new ImageIcon(img));
		setToolTipText(tip);
	}

	void setFuzzy(boolean f)
	{
		fuzzyStar.setText(f ? "*" : "");
	}

	int getItemId()
	{
		return itemId;
	}

	JPopupMenu menu()
	{
		return menu;
	}

	void clear()
	{
		image.setIcon(null);
		itemId = -1;
		qty = 0;
		setToolTipText(null);
		fuzzyStar.setText("");
	}
}

package com.runetools;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Remembers, per sync endpoint, a refusal that sending again can't change, so the background loop
 * stops re-posting the same thing every sweep.
 *
 * <ul>
 *   <li>A <b>name</b> park (409 or 403 {@code rsn_taken}, another 409 such as a limit, or a key that
 *       belongs to another character and was rejected) holds everything on that endpoint for one
 *       identity: the server is refusing the character, not the data, so no payload helps. It can
 *       carry the server's own words, for the panel.</li>
 *   <li>A <b>payload</b> park (400 or 413) holds one exact payload for one identity. A changed payload
 *       is tried again.</li>
 * </ul>
 *
 * <p>An identity is the character's name, its account hash and the API key it authenticates with, so a
 * park lapses on its own the moment another character logs in, the name changes, or a new key is
 * issued. A success on the endpoint clears it too. Nothing here is persisted: a client restart also
 * gets one fresh try. Thread-safe, since the scheduler, client and OkHttp threads all consult it.
 */
final class SyncParking
{
	private static final class Park
	{
		final String identity;
		final boolean wholeEndpoint;   // a name park: every payload is held
		final long payload;
		final String reason;           // the server's words for a whole-endpoint park, or null

		Park(String identity, boolean wholeEndpoint, long payload, String reason)
		{
			this.identity = identity;
			this.wholeEndpoint = wholeEndpoint;
			this.payload = payload;
			this.reason = reason;
		}
	}

	private final Map<String, Park> parks = new ConcurrentHashMap<>();

	/** True when {@code endpoint} must not send {@code payload} as {@code identity}. */
	boolean isParked(String endpoint, String identity, long payload)
	{
		Park p = parks.get(endpoint);
		if (p == null)
		{
			return false;
		}
		if (!p.identity.equals(identity))
		{
			parks.remove(endpoint, p);   // another character or key: the old refusal no longer applies
			return false;
		}
		return p.wholeEndpoint || p.payload == payload;
	}

	/** True when {@code endpoint} is refusing this identity's name, whatever the payload. */
	boolean isNameParked(String endpoint, String identity)
	{
		Park p = parks.get(endpoint);
		return p != null && p.wholeEndpoint && p.identity.equals(identity);
	}

	/** True when any endpoint is refusing this identity's name (drives the panel's status line). */
	boolean anyNameParked(String identity)
	{
		return parkedReason(identity) != null;
	}

	/**
	 * Why an endpoint is refusing this identity: the server's words, "" when it gave none, or null when
	 * nothing is held for it.
	 */
	String parkedReason(String identity)
	{
		String found = null;
		for (Park p : parks.values())
		{
			if (p.wholeEndpoint && p.identity.equals(identity))
			{
				if (p.reason != null && !p.reason.isEmpty())
				{
					return p.reason;
				}
				found = "";
			}
		}
		return found;
	}

	/** The server won't publish under this identity's name on {@code endpoint}. */
	void parkName(String endpoint, String identity)
	{
		parkName(endpoint, identity, null);
	}

	/** The server refuses everything from this identity on {@code endpoint}, for {@code reason}. */
	void parkName(String endpoint, String identity, String reason)
	{
		parks.put(endpoint, new Park(identity, true, 0L, reason));
	}

	/** Forget every park (a new login). */
	void clear()
	{
		parks.clear();
	}

	/** The server can never accept this exact payload from this identity on {@code endpoint}. */
	void parkPayload(String endpoint, String identity, long payload)
	{
		// Never narrow a name park to one payload: a late answer to an older request must not reopen
		// an endpoint the server has already said no to for this character.
		parks.compute(endpoint, (k, p) -> p != null && p.wholeEndpoint && p.identity.equals(identity)
			? p : new Park(identity, false, payload, null));
	}

	/** The endpoint accepted something from this identity, so whatever it refused before is moot. */
	void release(String endpoint, String identity)
	{
		parks.computeIfPresent(endpoint, (k, p) -> p.identity.equals(identity) ? null : p);
	}
}

package com.runetools;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

/**
 * How the plugin treats one HTTP answer from the RuneTools server. Kept free of OkHttp and RuneLite
 * types so the rules can be unit-tested on their own.
 *
 * <ul>
 *   <li>{@link Outcome#OK}: any 2xx in the shape the request expects, or 304 (an ETag poll's
 *       "unchanged"). A 2xx in the wrong shape (a captive portal, a proxy's page) is {@code FAILED}.</li>
 *   <li>{@link Outcome#KEY_REJECTED}: 401, or a JSON 403 whose {@code code} is {@code bad_key}. Counts
 *       toward stopping the loop, since a revoked key never heals on its own.</li>
 *   <li>{@link Outcome#NAME_TAKEN}: a 409 or JSON 403 whose {@code code} is {@code rsn_taken}. The key
 *       is fine; the server won't publish under a name linked to another RuneTools account.</li>
 *   <li>{@link Outcome#REFUSED}: any other 409 (a limit such as {@code limit_reached} or the in-game
 *       name cap). Sending again as the same character can't succeed, and the server's own words say
 *       why.</li>
 *   <li>{@link Outcome#PAYLOAD_REJECTED}: 400 or 413. The server can never accept this exact body.</li>
 *   <li>{@link Outcome#RATE_LIMITED}: 429.</li>
 *   <li>{@link Outcome#FAILED}: everything else, a 404, a 5xx, a 403 that isn't one of the above (a
 *       Cloudflare or proxy page) and a transport failure (status 0). An ordinary failure: that
 *       endpoint backs off and tries again.</li>
 * </ul>
 */
final class SyncResponse
{
	/** The {@code code} the server puts on a refusal to publish under somebody else's in-game name. */
	static final String RSN_TAKEN = "rsn_taken";
	/** The {@code code} on a 403 that means the key itself is no good. */
	static final String BAD_KEY = "bad_key";

	/** What a 2xx answer must look like before the request counts as done. */
	enum Shape
	{
		/** Anything (an ETag poll's empty 304 never reaches the check). */
		ANY,
		/** A JSON object with {@code "ok": true}: state, Combat Achievements, Collection Log, achievements. */
		OK_TRUE,
		/** A JSON object whose {@code received} equals the number of trades sent. */
		TRADES,
		/** A JSON object with a {@code setups} array. */
		SETUPS,
		/** A JSON object with a {@code layouts} array. */
		LAYOUTS,
		/** A JSON object carrying the setup's numeric {@code id}. */
		SETUP,
		/** A JSON object carrying {@code deleted}. */
		DELETED,
		/** Any JSON object. */
		OBJECT
	}

	enum Outcome
	{
		OK,
		KEY_REJECTED,
		NAME_TAKEN,
		REFUSED,
		PAYLOAD_REJECTED,
		RATE_LIMITED,
		FAILED
	}

	private SyncResponse()
	{
	}

	/**
	 * Classify a status. {@code errorCode} is the {@code code} field of the JSON error body, or null
	 * (also null when the body wasn't JSON at all).
	 */
	static Outcome classify(int status, String errorCode)
	{
		if ((status >= 200 && status < 300) || status == 304)
		{
			return Outcome.OK;
		}
		switch (status)
		{
			case 401:
				return Outcome.KEY_REJECTED;
			case 403:
				if (BAD_KEY.equals(errorCode))
				{
					return Outcome.KEY_REJECTED;
				}
				return RSN_TAKEN.equals(errorCode) ? Outcome.NAME_TAKEN : Outcome.FAILED;
			case 409:
				return RSN_TAKEN.equals(errorCode) ? Outcome.NAME_TAKEN : Outcome.REFUSED;
			case 400:
			case 413:
				return Outcome.PAYLOAD_REJECTED;
			case 429:
				return Outcome.RATE_LIMITED;
			default:
				return Outcome.FAILED;
		}
	}

	/** Classify an answer whose body has been read: a 2xx counts only in the expected shape. */
	static Outcome classify(int status, String body, Shape shape, int sent)
	{
		if (status >= 200 && status < 300 && !confirms(shape, body, sent))
		{
			return Outcome.FAILED;
		}
		return classify(status, status >= 400 && status < 500 ? errorCode(body) : null);
	}

	/** Whether a 4xx body is worth reading for its {@code code} and {@code error}. */
	static boolean readsErrorBody(int status)
	{
		return status >= 400 && status < 500;
	}

	/**
	 * What counts toward giving up on one payload: a 500, the server failing on what it was sent. A
	 * 502, 503, 504 or a Cloudflare 52x is the site or the way to it being down, which says nothing
	 * about the payload, so an outage never gives anything up.
	 */
	static boolean serverError(int status)
	{
		return status == 500;
	}

	/** Whether a 2xx body is the shape {@code shape} promises. Never throws. */
	static boolean confirms(Shape shape, String body, int sent)
	{
		if (shape == Shape.ANY)
		{
			return true;
		}
		JsonObject o = object(body);
		if (o == null)
		{
			return false;
		}
		switch (shape)
		{
			case OK_TRUE:
				return isTrue(o.get("ok"));
			case TRADES:
			{
				JsonElement e = o.get("received");
				return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() && e.getAsInt() == sent;
			}
			case SETUPS:
				return o.get("setups") != null && o.get("setups").isJsonArray();
			case LAYOUTS:
				return o.get("layouts") != null && o.get("layouts").isJsonArray();
			case SETUP:
			{
				JsonElement e = o.get("id");
				return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() && e.getAsLong() > 0;
			}
			case DELETED:
				return o.has("deleted");
			default:
				return true;
		}
	}

	/** The {@code code} field of a JSON error body, or null for anything else. Never throws. */
	static String errorCode(String body)
	{
		return field(body, "code", 64);
	}

	/**
	 * The {@code error} text of a JSON error body, cleaned and capped for the panel, or null when the
	 * body has none (an HTML page, an empty body). Never throws.
	 */
	static String errorText(String body)
	{
		String t = field(body, "error", 200);
		return t != null && !t.trim().isEmpty() ? t.trim() : null;
	}

	/**
	 * What to tell the player about a failed request they made: the server's own {@code error} text
	 * when it sent one, else {@code fallback} with a short reason. {@code status} 0 is no answer. A
	 * rejected key always says so: the site's own text for a 401 is about signing in on the site,
	 * which is not what fixes it in the plugin.
	 */
	static String describe(int status, String body, String fallback)
	{
		if (status == 401 || (status == 403 && BAD_KEY.equals(errorCode(body))))
		{
			return "Key rejected. Reconnect this character.";
		}
		String text = status >= 400 ? errorText(body) : null;
		if (text != null)
		{
			return text;
		}
		if (status == 429)
		{
			return "Too many requests. Try again in a minute.";
		}
		if (status == 0)
		{
			return fallback + " The site didn't answer.";
		}
		if (status >= 200 && status < 300)
		{
			return fallback + " Unexpected answer from the site.";
		}
		return fallback + " (HTTP " + status + ")";
	}

	private static String field(String body, String key, int max)
	{
		JsonObject o = object(body);
		if (o == null)
		{
			return null;
		}
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		return p.isString() || p.isNumber() ? RemoteConfig.clean(p.getAsString(), max) : null;
	}

	private static JsonObject object(String body)
	{
		if (body == null || body.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = new JsonParser().parse(body);
			return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
		}
		catch (RuntimeException ex)
		{
			return null;   // an HTML error page from a proxy, a truncated body, ...
		}
	}

	private static boolean isTrue(JsonElement e)
	{
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	/**
	 * How long a {@code Retry-After} header asks us to wait, in milliseconds: either delta-seconds or
	 * an HTTP-date. Returns -1 when the header is absent or unreadable, 0 for a date already past, and
	 * never more than {@code maxMillis}, so a garbled or hostile value can't silence the plugin for good.
	 */
	static long retryAfterMillis(String header, long nowMillis, long maxMillis)
	{
		if (header == null)
		{
			return -1;
		}
		String v = header.trim();
		if (v.isEmpty())
		{
			return -1;
		}
		long millis;
		if (v.chars().allMatch(c -> c >= '0' && c <= '9'))
		{
			// More than 12 digits is past any cap we'd honour and could overflow the multiply.
			millis = v.length() > 12 ? maxMillis : Long.parseLong(v) * 1000L;
		}
		else
		{
			try
			{
				millis = ZonedDateTime.parse(v, DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toEpochMilli()
					- nowMillis;
			}
			catch (DateTimeParseException ex)
			{
				return -1;
			}
		}
		return Math.max(0L, Math.min(millis, maxMillis));
	}
}

package com.runetools;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.Value;

/**
 * One completed (or partially-filled) Grand Exchange transaction, ready to upload.
 *
 * <p>{@code rsn} and {@code accountHash} identify which character made the trade so a batch
 * can be attributed correctly even if the player has since switched accounts; they are used
 * for grouping only and are sent as top-level fields, not repeated per trade.
 */
@Value
public class Trade
{
	int itemId;
	String side;      // "buy" | "sell"
	int qty;          // units filled by THIS delta
	long price;       // gp per item (spentDelta / qtyDelta); long, like GrandExchangeOffer since RuneLite 1.13
	long tsMillis;    // client capture time; the server folds ms -> seconds
	String extId;     // idempotency hint: slot:item:side:cumulativeQty
	String rsn;
	String accountHash;

	/** This trade as one element of the unsynced-trade queue persisted in RuneLite's config. */
	JsonObject toPendingJson()
	{
		JsonObject o = new JsonObject();
		o.addProperty("itemId", itemId);
		o.addProperty("side", side);
		o.addProperty("qty", qty);
		o.addProperty("price", price);
		o.addProperty("tsMillis", tsMillis);
		o.addProperty("extId", extId);
		o.addProperty("rsn", rsn);
		if (accountHash != null)
		{
			o.addProperty("accountHash", accountHash);
		}
		return o;
	}

	/**
	 * Read one element of the persisted queue back. Queues saved before RuneLite 1.13 hold
	 * {@code price} as an int; {@code getAsLong} reads that and the wider form alike, so an
	 * upgrade never drops a backlog of unsynced fills.
	 */
	static Trade fromPendingJson(JsonObject o)
	{
		return new Trade(
			o.get("itemId").getAsInt(), o.get("side").getAsString(),
			o.get("qty").getAsInt(), o.get("price").getAsLong(),
			o.get("tsMillis").getAsLong(), o.get("extId").getAsString(),
			optString(o, "rsn"), optString(o, "accountHash"));
	}

	private static String optString(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && !e.isJsonNull() ? e.getAsString() : null;
	}
}

package com.runetools;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * Splits the unsynced-trade queue into uploads, one per character, each sent with that character's
 * own key. A fill always goes to the RuneTools account of the character that made it, never to
 * whoever is logged in when the queue is flushed.
 *
 * <ul>
 *   <li>Trades are grouped by the account hash captured with them.</li>
 *   <li>A group whose character has no key here (an alt that was never connected, or a fill captured
 *       before the account hash was known) stays queued, and is dropped once it is older than
 *       {@link #KEYLESS_TTL_MS}.</li>
 *   <li>A missing name is filled only from the same character: another of its queued fills, or the
 *       character in game when it is that same account hash.</li>
 * </ul>
 *
 * <p>Plain logic, so it can be unit-tested.
 */
final class TradeGroups
{
	/** How long a fill with no key to send it with is kept, waiting for its character to connect. */
	static final long KEYLESS_TTL_MS = 30L * 24L * 60L * 60L * 1000L;

	/** One upload: a character's fills and the key that sends them. */
	static final class Group
	{
		final String accountHash;
		final String rsn;
		final String key;
		final List<Trade> trades;

		Group(String accountHash, String rsn, String key, List<Trade> trades)
		{
			this.accountHash = accountHash;
			this.rsn = rsn;
			this.key = key;
			this.trades = trades;
		}
	}

	/** What to send now, and the keyless fills too old to keep. */
	static final class Plan
	{
		final List<Group> send;
		final List<Trade> expired;

		Plan(List<Group> send, List<Trade> expired)
		{
			this.send = send;
			this.expired = expired;
		}
	}

	private TradeGroups()
	{
	}

	static Plan plan(List<Trade> pending, Function<String, String> keyForHash, String currentHash,
		String currentRsn, long nowMillis)
	{
		Map<String, List<Trade>> byHash = new LinkedHashMap<>();
		for (Trade t : pending)
		{
			String h = t.getAccountHash() != null ? t.getAccountHash() : "";
			byHash.computeIfAbsent(h, k -> new ArrayList<>()).add(t);
		}
		List<Group> send = new ArrayList<>();
		List<Trade> expired = new ArrayList<>();
		for (Map.Entry<String, List<Trade>> en : byHash.entrySet())
		{
			String hash = en.getKey().isEmpty() ? null : en.getKey();
			List<Trade> trades = en.getValue();
			String key = hash != null ? keyForHash.apply(hash) : null;
			if (key == null || key.isEmpty())
			{
				for (Trade t : trades)
				{
					if (nowMillis - t.getTsMillis() > KEYLESS_TTL_MS)
					{
						expired.add(t);
					}
				}
				continue;
			}
			String rsn = null;
			for (Trade t : trades)
			{
				if (t.getRsn() != null && !t.getRsn().isEmpty())
				{
					rsn = t.getRsn();   // the newest name this character traded under
				}
			}
			if (rsn == null && hash.equals(currentHash) && currentRsn != null && !currentRsn.isEmpty())
			{
				rsn = currentRsn;
			}
			send.add(new Group(hash, rsn, key, Collections.unmodifiableList(trades)));
		}
		return new Plan(send, expired);
	}
}

package com.runetools;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * AdventureLog against the game's real message texts (colour tags removed, as the plugin hands them
 * in). Messages for a tick arrive before that tick's GameTick, so each test feeds a tick's messages
 * and then calls {@code onTick}.
 */
public class AdventureLogTest
{
	private static final long NOW = 1_790_000_000_000L;

	private static final class Toggles implements AdventureLog.Settings
	{
		final Set<AdventureLog.Category> on = EnumSet.allOf(AdventureLog.Category.class);
		long min = 1_000_000L;

		@Override
		public boolean on(AdventureLog.Category category)
		{
			return on.contains(category);
		}

		@Override
		public long minValue()
		{
			return min;
		}
	}

	private final Toggles toggles = new Toggles();
	private final AdventureLog log = new AdventureLog(toggles);
	private int tick;

	/** One tick: its messages, then its GameTick. Returns what finished. */
	private List<JsonObject> tick(String... messages)
	{
		for (String m : messages)
		{
			log.onGameMessage(m, NOW);
		}
		log.onTick(++tick);
		return log.drain();
	}

	private List<JsonObject> ticks(int n)
	{
		List<JsonObject> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			out.addAll(tick());
		}
		return out;
	}

	private static JsonObject only(List<JsonObject> events, String type)
	{
		JsonObject found = null;
		for (JsonObject e : events)
		{
			if (type.equals(e.get("type").getAsString()))
			{
				Assert.assertNull("more than one " + type, found);
				found = e;
			}
		}
		Assert.assertNotNull("no " + type + " in " + events, found);
		return found;
	}

	@Test
	public void combatTasksKeepTheTierAndNameWithoutThePoints()
	{
		JsonObject e = only(tick("Congratulations, you've completed a hard combat task: Whack-a-Mole (3 points)."), "ca_task");
		Assert.assertEquals("hard", e.get("tier").getAsString());
		Assert.assertEquals("Whack-a-Mole", e.get("task").getAsString());
		Assert.assertEquals(NOW, e.get("ts").getAsLong());
		Assert.assertEquals(16, e.get("id").getAsString().length());

		e = only(tick("Congratulations, you've completed an elite combat task: Perfect Zulrah."), "ca_task");
		Assert.assertEquals("elite", e.get("tier").getAsString());
		Assert.assertEquals("Perfect Zulrah", e.get("task").getAsString());
	}

	@Test
	public void diaryAreaCompletions()
	{
		JsonObject e = only(tick("Congratulations! You have completed all of the hard tasks in the Varrock area. "
			+ "Speak to Toby to claim your reward."), "diary");
		Assert.assertEquals("hard", e.get("tier").getAsString());
		Assert.assertEquals("Varrock", e.get("area").getAsString());

		e = only(tick("Congratulations! You have completed all of the elite tasks in the Kourend & Kebos area. "
			+ "Speak to Elise to claim your reward."), "diary");
		Assert.assertEquals("Kourend & Kebos", e.get("area").getAsString());
		// a single task is not an area completion
		Assert.assertTrue(tick("Well done! You have completed an easy task in the Karamja area. "
			+ "Your Achievement Diary has been updated.").isEmpty());
	}

