package com.runetools;

import org.junit.Assert;
import org.junit.Test;

public class SessionTrackerTest
{
	private static Trade trade(String side, int qty, long price)
	{
		return new Trade(20997, side, qty, price, 0L, side + qty, "Zezima", "1");
	}

	@Test
	public void realizedProfitIsExactPastTheIntRange()
	{
		SessionTracker s = new SessionTracker();
		s.record(trade("buy", 2, 3_000_000_000L));
		s.record(trade("sell", 2, 3_100_000_000L));
		// Tax is 2% per item capped at 5m: (3.1b - 5m - 3.0b) x 2.
		Assert.assertEquals(190_000_000L, s.realizedProfit());
	}

	@Test
	public void sellWithoutABuyThisSessionIsIgnored()
	{
		SessionTracker s = new SessionTracker();
		s.record(trade("sell", 1, 1_000L));
		Assert.assertEquals(0L, s.realizedProfit());
		Assert.assertEquals(1, s.recent().size());
	}
}

package com.runetools;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/** Setup collections are optional: without them the list is exactly what it always was. */
public class SetupCollectionsTest
{
	private static JsonObject json(String s)
	{
		return new JsonParser().parse(s).getAsJsonObject();
	}

	private static GearSetup setup(long id, String name, SetupCollection... in)
	{
		GearSetup g = new GearSetup();
		g.setId(id);
		g.setName(name);
		g.setCollections(new ArrayList<>(Arrays.asList(in)));
		return g;
	}

	private static SetupCollection coll(long id, String name, String role, int order)
	{
		return new SetupCollection(id, name, role, order);
	}

	@Test
	public void aSetupWithoutTheFieldIsInNoCollection()
	{
		GearSetup g = GearSetup.fromJson(json("{\"id\": 5, \"name\": \"Vorkath\"}"));
		Assert.assertTrue(g.getCollections().isEmpty());
	}

	@Test
	public void oneCollectionOrSeveralAreRead()
	{
		GearSetup one = GearSetup.fromJson(json("{\"id\": 5, \"name\": \"Tank\", "
			+ "\"collection\": {\"id\": 9, \"name\": \"3 Man Bandos\", \"role\": \"Tank\", \"order\": 1}}"));
		Assert.assertEquals(Collections.singletonList(coll(9, "3 Man Bandos", "Tank", 1)), one.getCollections());

		GearSetup many = GearSetup.fromJson(json("{\"id\": 5, \"name\": \"Ranger\", \"collections\": ["
			+ "{\"id\": 9, \"name\": \"3 Man Bandos\", \"role\": \"Ranger\", \"order\": 2},"
			+ "{\"id\": 10, \"name\": \"Duo Bandos\", \"role\": \"Ranger\", \"order\": 0}]}"));
		Assert.assertEquals(2, many.getCollections().size());
		Assert.assertEquals(10L, many.getCollections().get(1).getId());
	}

	@Test
	public void aMissingRoleOrOrderStillGroupsTheSetup()
	{
		String[] ok = {
			"\"collection\": {\"id\": 9, \"name\": \"Bandos\", \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": \"Bandos\", \"role\": null, \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": \"Bandos\", \"role\": \"\"}",
			"\"collection\": {\"id\": 9, \"name\": \"Bandos\", \"order\": null}",
		};
		for (String b : ok)
		{
			GearSetup g = GearSetup.fromJson(json("{\"id\": 5, \"name\": \"Tank\", " + b + "}"));
			Assert.assertEquals(b, 1, g.getCollections().size());
			SetupCollection c = g.getCollections().get(0);
			Assert.assertEquals(b, 9L, c.getId());
			Assert.assertEquals(b, "", c.getRole());
			Assert.assertTrue(b, c.getOrder() == 0 || c.getOrder() == 1);
		}
	}

	@Test
	public void aMalformedCollectionIsNoCollection()
	{
		String[] bad = {
			"\"collection\": \"3 Man Bandos\"",
			"\"collection\": {\"name\": \"x\", \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": \"9\", \"name\": \"x\", \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": 9.5, \"name\": \"x\", \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": -1, \"name\": \"x\", \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": 4, \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": \"  \", \"role\": \"Tank\", \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": \"x\", \"role\": [], \"order\": 1}",
			"\"collection\": {\"id\": 9, \"name\": \"x\", \"role\": \"Tank\", \"order\": \"1\"}",
			"\"collection\": {\"id\": 9, \"name\": \"x\", \"role\": \"Tank\", \"order\": {}}",
			"\"collection\": null",
			"\"collections\": {\"id\": 9}",
			"\"collections\": [1, \"a\", null, []]",
		};
		for (String b : bad)
		{
			GearSetup g = GearSetup.fromJson(json("{\"id\": 5, \"name\": \"Tank\", " + b + "}"));
			Assert.assertTrue(b, g.getCollections().isEmpty());
			Assert.assertEquals(b, 5L, g.getId());
		}
	}

	@Test
	public void namedInBothFieldsCountsOnce()
	{
		GearSetup g = GearSetup.fromJson(json("{\"id\": 5, "
			+ "\"collection\": {\"id\": 9, \"name\": \"Bandos\", \"role\": \"Tank\", \"order\": 1},"
			+ "\"collections\": [{\"id\": 9, \"name\": \"Bandos\", \"role\": \"Tank\", \"order\": 1}]}"));
		Assert.assertEquals(1, g.getCollections().size());
	}

	@Test
	public void withoutCollectionsTheListIsUnchanged()
	{
		List<GearSetup> list = Arrays.asList(setup(1, "Vorkath"), setup(2, "Zulrah"));
		List<SetupGroups.Row> rows = SetupGroups.rows(list);
		Assert.assertEquals(2, rows.size());
		Assert.assertEquals("Vorkath", rows.get(0).label);
		Assert.assertSame(list.get(1), rows.get(1).setup);
		Assert.assertFalse(rows.get(0).indented);
		Assert.assertNull(rows.get(0).tooltip);
	}

	@Test
	public void aCollectionsSetupsSitUnderItsNameInOrderByRole()
	{
		SetupCollection tank = coll(9, "3 Man Bandos", "Tank", 1);
		SetupCollection mage = coll(9, "3 Man Bandos", "Mage", 3);
		SetupCollection ranger = coll(9, "3 Man Bandos", "Ranger", 2);
		List<GearSetup> list = Arrays.asList(
			setup(1, "Vorkath"),
			setup(2, "Bandos mage", mage),
			setup(3, "Bandos tank", tank),
			setup(4, "Zulrah"),
			setup(5, "Bandos ranger", ranger));
		List<SetupGroups.Row> rows = SetupGroups.rows(list);
		String[] labels = new String[rows.size()];
		for (int i = 0; i < rows.size(); i++)
		{
			labels[i] = rows.get(i).label;
		}
		Assert.assertArrayEquals(new String[]{"Vorkath", "3 Man Bandos", "Tank", "Ranger", "Mage", "Zulrah"}, labels);
		Assert.assertNull("a header opens nothing", rows.get(1).setup);
		Assert.assertEquals("3 Man Bandos", rows.get(1).header);
		Assert.assertTrue(rows.get(2).indented);
		Assert.assertEquals("Bandos tank", rows.get(2).tooltip);
		Assert.assertEquals(3L, rows.get(2).setup.getId());
	}

	@Test
	public void aSetupInSeveralCollectionsIsListedUnderEach()
	{
		GearSetup shared = setup(1, "Ranger kit", coll(9, "Trio", "Ranger", 2), coll(10, "Duo", "Ranger", 1));
		GearSetup tank = setup(2, "Tank kit", coll(9, "Trio", "Tank", 1));
		List<SetupGroups.Row> rows = SetupGroups.rows(Arrays.asList(shared, tank));
		Assert.assertEquals(5, rows.size());
		Assert.assertEquals("Trio", rows.get(0).header);
		Assert.assertEquals("Tank", rows.get(1).label);
		Assert.assertEquals("Ranger", rows.get(2).label);
		Assert.assertEquals("Duo", rows.get(3).header);
		Assert.assertSame(shared, rows.get(4).setup);
	}

	@Test
	public void aSetupWithNoRoleIsLabelledByItsName()
	{
		List<SetupGroups.Row> rows = SetupGroups.rows(Collections.singletonList(setup(1, "Kit", coll(9, "Trio", "", 0))));
		Assert.assertEquals("Kit", rows.get(1).label);
		Assert.assertNull(rows.get(1).tooltip);
	}
}

package com.runetools;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * The /state body must carry exactly what the server stores and what the consent text and README
 * promise: nothing more. A field added here has to be added to both of those as well.
 */
public class StateBodyTest
{
	private static final Set<String> ALWAYS = new HashSet<>(Arrays.asList(
		"rsn", "account_hash", "members", "gp", "free_slots", "offers", "inventory"));

	private static AccountSnapshot full()
	{
		JsonObject attack = new JsonObject();
		attack.addProperty("level", 99);
		attack.addProperty("xp", 13034431);
		JsonObject skills = new JsonObject();
		skills.add("attack", attack);
		JsonArray bank = new JsonArray();
		JsonObject coins = new JsonObject();
		coins.addProperty("item_id", 995);
		coins.addProperty("qty", 1000L);
		bank.add(coins);
		JsonArray worn = new JsonArray();
		JsonObject fang = new JsonObject();
		fang.addProperty("item_id", 26219);
		fang.addProperty("qty", 1);
		worn.add(fang);
		return AccountSnapshot.empty().toBuilder()
			.rsn("Zezima")
			.accountHash("123456789")
			.members(true)
			.gp(1000L)
			.freeSlots(8)
			.bank(bank)
			.equipment(worn)
			.skills(skills)
			.build();
	}

	@Test
	public void sendsExactlyTheStoredFields()
	{
		JsonObject body = RuneToolsApiClient.stateBody(full());
		Set<String> expected = new HashSet<>(ALWAYS);
		expected.add("bank");
		expected.add("equipment");
		expected.add("skills");
		Assert.assertEquals(expected, body.keySet());
	}

	@Test
	public void neverSendsFieldsTheServerDiscards()
	{
		JsonObject body = RuneToolsApiClient.stateBody(full());
		for (String dropped : new String[]{"world", "quests", "slayer", "bronzeman", "ts"})
		{
			Assert.assertFalse(dropped + " should not be sent", body.has(dropped));
		}
	}

	@Test
	public void uncapturedBankEquipmentAndSkillsAreLeftOutSoTheServerKeepsItsCopy()
	{
		AccountSnapshot s = AccountSnapshot.empty().toBuilder().rsn("Zezima").accountHash("1").build();
		JsonObject body = RuneToolsApiClient.stateBody(s);
		Assert.assertEquals(ALWAYS, body.keySet());
	}

	@Test
	public void skillsAreSentAsCaptured()
	{
		JsonObject body = RuneToolsApiClient.stateBody(full());
		JsonObject attack = body.getAsJsonObject("skills").getAsJsonObject("attack");
		Assert.assertEquals(99, attack.get("level").getAsInt());
		Assert.assertEquals(13034431, attack.get("xp").getAsInt());
	}
}

package com.runetools;

import org.junit.Assert;
import org.junit.Test;

public class SyncParkingTest
{
	private static final String CA = "combat-achievements";
	private static final String CLOG = "collection-log";
	private static final String MAIN = "Zezima|111|key1";
	private static final String ALT = "Zezima Alt|222|key2";

	@Test
	public void nothingIsParkedByDefault()
	{
		SyncParking p = new SyncParking();
		Assert.assertFalse(p.isParked(CA, MAIN, 1L));
		Assert.assertFalse(p.isNameParked(CA, MAIN));
		Assert.assertFalse(p.anyNameParked(MAIN));
	}

	@Test
	public void nameParkHoldsEveryPayloadForThatCharacterOnly()
	{
		SyncParking p = new SyncParking();
		p.parkName(CA, MAIN);
		Assert.assertTrue(p.isParked(CA, MAIN, 1L));
		Assert.assertTrue(p.isParked(CA, MAIN, 2L));   // changing the payload doesn't help
		Assert.assertTrue(p.isNameParked(CA, MAIN));
		Assert.assertTrue(p.anyNameParked(MAIN));
		Assert.assertFalse(p.isParked(CLOG, MAIN, 1L));   // per endpoint
		Assert.assertFalse(p.anyNameParked(ALT));
	}

	@Test
	public void anotherCharacterOrKeyGetsAFreshTry()
	{
		SyncParking p = new SyncParking();
		p.parkName(CA, MAIN);
		Assert.assertFalse(p.isParked(CA, ALT, 1L));
		Assert.assertFalse(p.isParked(CA, "Zezima|111|key2", 1L));   // same character, newly-issued key
	}

	@Test
	public void payloadParkHoldsOnlyThatPayload()
	{
		SyncParking p = new SyncParking();
		p.parkPayload(CLOG, MAIN, 42L);
		Assert.assertTrue(p.isParked(CLOG, MAIN, 42L));
		Assert.assertFalse(p.isParked(CLOG, MAIN, 43L));   // a changed payload may be retried
		Assert.assertFalse(p.isNameParked(CLOG, MAIN));
		Assert.assertFalse(p.anyNameParked(MAIN));
	}

	@Test
	public void aLateBadRequestDoesNotNarrowANamePark()
	{
		SyncParking p = new SyncParking();
		p.parkName(CA, MAIN);
		p.parkPayload(CA, MAIN, 7L);
		Assert.assertTrue(p.isParked(CA, MAIN, 8L));
		Assert.assertTrue(p.isNameParked(CA, MAIN));
	}

	@Test
	public void successReleasesOnlyItsOwnCharactersPark()
	{
		SyncParking p = new SyncParking();
		p.parkName(CA, MAIN);
		p.release(CA, ALT);   // a late success for someone else changes nothing
		Assert.assertTrue(p.isNameParked(CA, MAIN));
		p.release(CA, MAIN);
		Assert.assertFalse(p.isParked(CA, MAIN, 1L));
		Assert.assertFalse(p.anyNameParked(MAIN));
	}
}

package com.runetools;

import com.runetools.SyncResponse.Outcome;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import org.junit.Assert;
import org.junit.Test;

public class SyncResponseTest
{
	private static final long MAX = 60L * 60L * 1000L;

	@Test
	public void successAndNotModifiedAreOk()
	{
		Assert.assertEquals(Outcome.OK, SyncResponse.classify(200, null));
		Assert.assertEquals(Outcome.OK, SyncResponse.classify(204, null));
		Assert.assertEquals(Outcome.OK, SyncResponse.classify(304, null));
	}

	@Test
	public void notFoundIsAnOrdinaryFailure()
	{
		// It backs that endpoint off like any failure (it used to be ignored and retried every sweep).
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(404, null));
	}

	@Test
	public void onlyUnauthorizedAndABadKeyCodeRejectTheKey()
	{
		Assert.assertEquals(Outcome.KEY_REJECTED, SyncResponse.classify(401, null));
		Assert.assertEquals(Outcome.KEY_REJECTED, SyncResponse.classify(403, SyncResponse.BAD_KEY));
	}

	@Test
	public void aForbiddenPageThatIsntOursIsAnOrdinaryFailure()
	{
		// Cloudflare or a proxy answering 403 with its own page must never halt sync as a "revoked key".
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(403, null));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(403, "something_else"));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(403,
			"<html><body>Attention Required! | Cloudflare</body></html>", SyncResponse.Shape.ANY, 0));
	}

	@Test
	public void nameConflictIsNotAKeyRejection()
	{
		Assert.assertEquals(Outcome.NAME_TAKEN, SyncResponse.classify(409, SyncResponse.RSN_TAKEN));
		Assert.assertEquals(Outcome.NAME_TAKEN, SyncResponse.classify(403, SyncResponse.RSN_TAKEN));
	}

	@Test
	public void otherConflictsAreRefusalsNotNameConflicts()
	{
		Assert.assertEquals(Outcome.REFUSED, SyncResponse.classify(409, null));
		Assert.assertEquals(Outcome.REFUSED, SyncResponse.classify(409, "limit_reached"));
		String cap = "{\"error\": \"This account already syncs 20 in-game names.\"}";
		Assert.assertEquals(Outcome.REFUSED, SyncResponse.classify(409, cap, SyncResponse.Shape.OK_TRUE, 0));
		Assert.assertEquals("This account already syncs 20 in-game names.", SyncResponse.errorText(cap));
	}

	@Test
	public void aSuccessInTheWrongShapeIsAFailure()
	{
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(200, "<html>Captive portal</html>",
			SyncResponse.Shape.OK_TRUE, 0));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(200, "{\"ok\": false}", SyncResponse.Shape.OK_TRUE, 0));
		Assert.assertEquals(Outcome.OK, SyncResponse.classify(200, "{\"ok\": true, \"rsn\": \"Zezima\"}",
			SyncResponse.Shape.OK_TRUE, 0));
		// A setups answer without its array must never be taken as "no setups" (it would wipe the list).
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.SETUPS, "{\"server_ts\": 1}", 0));
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.SETUPS, "{\"setups\": {}}", 0));
		Assert.assertTrue(SyncResponse.confirms(SyncResponse.Shape.SETUPS, "{\"setups\": []}", 0));
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.LAYOUTS, "[]", 0));
		Assert.assertTrue(SyncResponse.confirms(SyncResponse.Shape.LAYOUTS, "{\"layouts\": []}", 0));
		Assert.assertTrue(SyncResponse.confirms(SyncResponse.Shape.SETUP, "{\"id\": 12, \"name\": \"x\"}", 0));
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.SETUP, "{\"name\": \"x\"}", 0));
	}

	@Test
	public void tradesCountOnlyWhenTheServerConfirmsEveryOne()
	{
		String body = "{\"imported\": 2, \"received\": 3, \"total\": 10}";
		Assert.assertTrue(SyncResponse.confirms(SyncResponse.Shape.TRADES, body, 3));
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.TRADES, body, 4));
		Assert.assertFalse(SyncResponse.confirms(SyncResponse.Shape.TRADES, "{\"ok\": true}", 3));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(200, "", SyncResponse.Shape.TRADES, 3));
	}

	@Test
	public void describeUsesTheServersWordsAndNoStatusCodeWhenItHasThem()
	{
		String limit = "{\"error\": \"You can keep up to 300 gear setups. Delete one to add another.\", "
			+ "\"code\": \"limit_reached\"}";
		Assert.assertEquals("You can keep up to 300 gear setups. Delete one to add another.",
			SyncResponse.describe(409, limit, "Couldn't save."));
		Assert.assertEquals("Couldn't save. (HTTP 503)", SyncResponse.describe(503, "<html>down</html>", "Couldn't save."));
		Assert.assertEquals("Key rejected. Reconnect this character.", SyncResponse.describe(401, "", "Couldn't save."));
		// the site's 401 body is about signing in on the site, not what the player needs to do here
		Assert.assertEquals("Key rejected. Reconnect this character.",
			SyncResponse.describe(401, "{\"error\":\"Sign in to use this feature.\"}", "Couldn't save."));
		Assert.assertEquals("Key rejected. Reconnect this character.",
			SyncResponse.describe(403, "{\"error\":\"Bad key\",\"code\":\"bad_key\"}", "Couldn't save."));
		Assert.assertEquals("Couldn't save. The site didn't answer.", SyncResponse.describe(0, null, "Couldn't save."));
		Assert.assertEquals("Couldn't save. Unexpected answer from the site.",
			SyncResponse.describe(200, "<html></html>", "Couldn't save."));
	}

	@Test
	public void onlyAFiveHundredCountsTowardGivingUp()
	{
		Assert.assertTrue(SyncResponse.serverError(500));
		for (int outage : new int[]{502, 503, 504, 520, 521, 522, 524})
		{
			Assert.assertFalse("an outage says nothing about the payload: " + outage, SyncResponse.serverError(outage));
		}
		Assert.assertFalse(SyncResponse.serverError(404));
		Assert.assertFalse(SyncResponse.serverError(0));
	}

	@Test
	public void badRequestAndTooLargeRejectThePayload()
	{
		Assert.assertEquals(Outcome.PAYLOAD_REJECTED, SyncResponse.classify(400, null));
		Assert.assertEquals(Outcome.PAYLOAD_REJECTED, SyncResponse.classify(413, null));
	}

	@Test
	public void rateLimitAndEverythingElse()
	{
		Assert.assertEquals(Outcome.RATE_LIMITED, SyncResponse.classify(429, null));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(0, null));     // transport failure
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(500, null));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(503, null));
		Assert.assertEquals(Outcome.FAILED, SyncResponse.classify(405, null));
	}

	@Test
	public void clientErrorsAreReadForTheirCode()
	{
		Assert.assertTrue(SyncResponse.readsErrorBody(403));
		Assert.assertTrue(SyncResponse.readsErrorBody(409));
		Assert.assertFalse(SyncResponse.readsErrorBody(200));
		Assert.assertFalse(SyncResponse.readsErrorBody(500));
	}

	@Test
	public void errorCodeIsReadFromTheServersBody()
	{
		Assert.assertEquals("rsn_taken", SyncResponse.errorCode(
			"{\"error\": \"That in-game name belongs to another RuneTools account.\", \"code\": \"rsn_taken\"}"));
		Assert.assertNull(SyncResponse.errorCode("{\"error\": \"Sign in to use this feature.\"}"));
	}

	@Test
	public void errorCodeNeverThrowsOnJunk()
	{
		Assert.assertNull(SyncResponse.errorCode(null));
		Assert.assertNull(SyncResponse.errorCode(""));
		Assert.assertNull(SyncResponse.errorCode("<html><body>403 Forbidden</body></html>"));
		Assert.assertNull(SyncResponse.errorCode("[1, 2]"));
		Assert.assertNull(SyncResponse.errorCode("{\"code\": {\"nested\": true}}"));
		Assert.assertNull(SyncResponse.errorCode("{\"code\": "));
	}

	@Test
	public void retryAfterSeconds()
	{
		Assert.assertEquals(60_000L, SyncResponse.retryAfterMillis("60", 0L, MAX));
		Assert.assertEquals(5_000L, SyncResponse.retryAfterMillis(" 5 ", 0L, MAX));
		Assert.assertEquals(0L, SyncResponse.retryAfterMillis("0", 0L, MAX));
	}

	@Test
	public void retryAfterIsCapped()
	{
		Assert.assertEquals(MAX, SyncResponse.retryAfterMillis("86400", 0L, MAX));
		Assert.assertEquals(MAX, SyncResponse.retryAfterMillis("99999999999999999999999", 0L, MAX));
	}

	@Test
	public void retryAfterHttpDate()
	{
		long now = Instant.parse("2026-10-07T12:00:00Z").toEpochMilli();
		String in90s = DateTimeFormatter.RFC_1123_DATE_TIME.format(
			Instant.ofEpochMilli(now + 90_000L).atZone(ZoneOffset.UTC));
		Assert.assertEquals(90_000L, SyncResponse.retryAfterMillis(in90s, now, MAX));
		Assert.assertEquals(0L, SyncResponse.retryAfterMillis("Wed, 21 Oct 2015 07:28:00 GMT", now, MAX));
	}

	@Test
	public void retryAfterAbsentOrUnreadable()
	{
		Assert.assertEquals(-1L, SyncResponse.retryAfterMillis(null, 0L, MAX));
		Assert.assertEquals(-1L, SyncResponse.retryAfterMillis("", 0L, MAX));
		Assert.assertEquals(-1L, SyncResponse.retryAfterMillis("soon", 0L, MAX));
		Assert.assertEquals(-1L, SyncResponse.retryAfterMillis("-5", 0L, MAX));
	}
}

package com.runetools;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/** Each character's fills go with its own key, never the key of whoever is logged in. */
public class TradeGroupsTest
{
	private static final long NOW = 100L * 24L * 60L * 60L * 1000L;

	private static Trade trade(String rsn, String hash, long ts)
	{
		return new Trade(4151, "buy", 1, 1_500_000L, ts, "0:4151:buy:1", rsn, hash);
	}

	private static Map<String, String> keys()
	{
		Map<String, String> k = new HashMap<>();
		k.put("111", "rtk_main");
		k.put("222", "rtk_alt");
		return k;
	}

	@Test
	public void eachCharacterIsSentWithItsOwnKey()
	{
		List<Trade> pending = Arrays.asList(trade("Main", "111", NOW), trade("Alt", "222", NOW), trade("Main", "111", NOW));
		TradeGroups.Plan plan = TradeGroups.plan(pending, keys()::get, "222", "Alt", NOW);
		Assert.assertEquals(2, plan.send.size());
		TradeGroups.Group main = plan.send.get(0);
		Assert.assertEquals("111", main.accountHash);
		Assert.assertEquals("rtk_main", main.key);
		Assert.assertEquals("Main", main.rsn);
		Assert.assertEquals(2, main.trades.size());
		TradeGroups.Group alt = plan.send.get(1);
		Assert.assertEquals("rtk_alt", alt.key);
		Assert.assertEquals(1, alt.trades.size());
		Assert.assertTrue(plan.expired.isEmpty());
	}

	@Test
	public void aCharacterWithNoKeyStaysQueued()
	{
		List<Trade> pending = Arrays.asList(trade("Ironman", "333", NOW - 1000L), trade(null, null, NOW));
		TradeGroups.Plan plan = TradeGroups.plan(pending, keys()::get, "111", "Main", NOW);
		Assert.assertTrue("never sent with the logged-in character's key", plan.send.isEmpty());
		Assert.assertTrue(plan.expired.isEmpty());
	}

	@Test
	public void keylessFillsExpireAfterThirtyDays()
	{
		Trade old = trade("Ironman", "333", NOW - TradeGroups.KEYLESS_TTL_MS - 1L);
		Trade recent = trade("Ironman", "333", NOW - 1000L);
		Trade orphan = trade(null, null, NOW - TradeGroups.KEYLESS_TTL_MS - 1L);
		TradeGroups.Plan plan = TradeGroups.plan(Arrays.asList(old, recent, orphan), keys()::get, "111", "Main", NOW);
		Assert.assertEquals(Arrays.asList(old, orphan), plan.expired);
	}

	@Test
	public void aMissingNameComesOnlyFromTheSameCharacter()
	{
		// Another of its own fills knows the name.
		TradeGroups.Plan own = TradeGroups.plan(Arrays.asList(trade(null, "111", NOW), trade("Main", "111", NOW)),
			keys()::get, "222", "Alt", NOW);
		Assert.assertEquals("Main", own.send.get(0).rsn);
		// The character in game is the same account: its name is used.
		TradeGroups.Plan same = TradeGroups.plan(Arrays.asList(trade(null, "111", NOW)), keys()::get, "111", "Main", NOW);
		Assert.assertEquals("Main", same.send.get(0).rsn);
		// A different character in game: never borrowed.
		TradeGroups.Plan other = TradeGroups.plan(Arrays.asList(trade(null, "111", NOW)), keys()::get, "222", "Alt", NOW);
		Assert.assertNull(other.send.get(0).rsn);
		Assert.assertEquals("rtk_main", other.send.get(0).key);
	}
}

package com.runetools;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Assert;
import org.junit.Test;

/** The unsynced-trade queue persisted in RuneLite's config must survive the int-to-long price change. */
public class TradeTest
{
	@Test
	public void queueSavedBeforeTheLongPriceChangeStillLoads()
	{
		// Exactly what savePending() wrote when price was an int (no accountHash on older entries).
		JsonObject old = new JsonParser().parse("{\"itemId\":4151,\"side\":\"buy\",\"qty\":3,"
			+ "\"price\":1500000,\"tsMillis\":1720000000000,\"extId\":\"0:4151:buy:3\",\"rsn\":\"Zezima\"}")
			.getAsJsonObject();
		Trade t = Trade.fromPendingJson(old);
		Assert.assertEquals(4151, t.getItemId());
		Assert.assertEquals(3, t.getQty());
		Assert.assertEquals(1_500_000L, t.getPrice());
		Assert.assertEquals("Zezima", t.getRsn());
		Assert.assertNull(t.getAccountHash());
	}

	@Test
	public void longPriceRoundTrips()
	{
		Trade t = new Trade(20997, "sell", 1, 4_000_000_000L, 1720000000000L, "3:20997:sell:1", null, "123");
		String saved = t.toPendingJson().toString();
		Assert.assertTrue(saved.contains("\"price\":4000000000"));
		Assert.assertEquals(t, Trade.fromPendingJson(new JsonParser().parse(saved).getAsJsonObject()));
	}
}
